import { Icon } from '@/design-system/Icon'
import { Card, EmptyState } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n } from '@/i18n'
import { fmtDate, formatRupiah } from '@/i18n/format'
import { canDependOn, dependents, resolveEventDates, withResolvedDates } from './deps'
import {
  currentBucket,
  groupByBucket,
  ownerLoad,
  planChecklist,
  type OwnerAssignment,
  type PlanKey,
} from './checklistPlan'
import { anchorDate, budgetTotals, paxForEvent } from './plannerMath'
import {
  EVENT_SCALES,
  FAMILY_OWNERS,
  PARTNER_OWNERS,
  type EventScale,
  type FamilyOwner,
  type PartnerOwner,
  type PlannerOf,
  type PlannerRecord,
} from './types'

/**
 * Countdown tab (W01..W05).
 *
 * Everything on this screen is read from IndexedDB through `useOwned()` and
 * recomputed: the event order, the derived dates, the generated checklist, the
 * ownership split. No sample data, and nothing about the dates is suggested by
 * the app — TemuDua does not know which dates are auspicious, which slots the KUA
 * has free, or which days are public holidays, so it asks and never proposes.
 */
export function Countdown({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const rows = useOwned<PlannerRecord>('wedding', me)

  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is PlannerOf<K> => r.kind === kind)

  const stored = of('wed_event')
  const resolved = resolveEventDates(stored)
  // Dependent events get their real date here, so the anchor, the checklist and
  // the per-event rollups all agree without knowing dependencies exist.
  const events = withResolvedDates(stored).sort((a, b) =>
    (a.date ?? '9999').localeCompare(b.date ?? '9999'),
  )
  // One scale row per couple, but a sync merge could land two. Newest edit wins,
  // deterministically — `readable()` returns primary-key order, not insertion
  // order, so "the last one in the array" would be a coin flip.
  const planRecord = of('wed_plan')
    .sort((a, b) => a.updatedAt.localeCompare(b.updatedAt))
    .at(-1)
  const scale: EventScale = planRecord?.scale ?? 'sedang'
  const checks = of('wed_check')
  const owns = of('wed_own')
  const budget = of('wed_budget2')
  const guests = of('wed_guest2')

  const anchor = anchorDate(events)
  const owners: Record<string, OwnerAssignment> = Object.fromEntries(
    owns.map((o) => [o.checkKey, { owner: o.owner, family: o.family }] as const),
  )
  const items = planChecklist({
    anchorDate: anchor,
    eventTypes: events.map((e) => e.eventType),
    scale,
    state: Object.fromEntries(checks.map((c) => [c.checkKey, c.status] as const)),
    owners,
  })
  const groups = groupByBucket(items)
  const nowBucket = currentBucket(anchor)
  const load = ownerLoad(items, PARTNER_OWNERS, FAMILY_OWNERS)

  const nameOf = (e: PlannerOf<'wed_event'>) =>
    e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const)
  const nameById = (id: string | undefined) => {
    const e = stored.find((x) => x.id === id)
    return e ? nameOf(e) : t('wedding2.cd.gone')
  }

  async function setScale(next: EventScale) {
    if (planRecord) await patch('wedding', planRecord.id, { scale: next })
    else
      await db.wedding.add({
        ...newEnvelope(me, 'C2_shared_ops'),
        kind: 'wed_plan',
        scale: next,
      } as never)
  }

  /** Writes one axis of ownership. Clearing both axes removes the row entirely. */
  async function setOwner(
    key: PlanKey,
    axis: 'owner' | 'family',
    value: PartnerOwner | FamilyOwner | '',
  ) {
    const existing = owns.find((o) => o.checkKey === key)
    const next = value === '' ? undefined : value
    if (!existing) {
      if (next)
        await db.wedding.add({
          ...newEnvelope(me, 'C2_shared_ops'),
          kind: 'wed_own',
          checkKey: key,
          [axis]: next,
        } as never)
      return
    }
    const other = axis === 'owner' ? existing.family : existing.owner
    if (!next && !other) await softDelete('wedding', existing.id, me)
    else await patch('wedding', existing.id, { [axis]: next })
  }

  async function setCheck(key: PlanKey, next: 'done' | 'skip' | null) {
    const existing = checks.find((c) => c.checkKey === key)
    if (!existing) {
      if (next)
        await db.wedding.add({
          ...newEnvelope(me, 'C2_shared_ops'),
          kind: 'wed_check',
          checkKey: key,
          status: next,
        } as never)
      return
    }
    if (!next) await softDelete('wedding', existing.id, me)
    else await patch('wedding', existing.id, { status: next })
  }

  const offsetLabel = (n: number) =>
    n === 0
      ? t('wedding2.cd.offSame')
      : n < 0
        ? t('wedding2.cd.offBefore', { n: -n })
        : t('wedding2.cd.offAfter', { n })

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.cd.intro')}</p>

      {/* Scale — W03 input ------------------------------------------------ */}
      <Card title={t('wedding2.cd.scaleCard')} icon="settings" hint={t('wedding2.cd.scaleHint')}>
        <div className="segmented segmented--wrap" role="group" aria-label={t('wedding2.cd.scaleCard')}>
          {EVENT_SCALES.map((s) => (
            <button key={s} aria-pressed={scale === s} onClick={() => setScale(s)}>
              {t(`wedding2.cd.scale.${s}` as const)}
            </button>
          ))}
        </div>
        <p className="card__hint">{t(`wedding2.cd.scaleWhat.${scale}` as const)}</p>
        <p className="disclaimer">{t('wedding2.cd.scaleCaveat')}</p>
      </Card>

      {/* Event order and dependencies — W01/W02 -------------------------- */}
      <Card title={t('wedding2.cd.order')} icon="calendar" hint={t('wedding2.cd.orderHint')}>
        {events.length === 0 ? (
          <EmptyState
            icon="calendar"
            title={t('wedding2.cd.noEvents')}
            hint={t('wedding2.cd.noEventsHint')}
          />
        ) : (
          events.map((e) => {
            const r = resolved.get(e.id)
            const followers = dependents(stored, e.id)
            const money = budgetTotals(budget.filter((b) => b.eventId === e.id))
            const pax = paxForEvent(guests, e.id)
            const parents = stored.filter((p) => canDependOn(stored, e.id, p.id))
            return (
              <div key={e.id} className="stack stack--tight" style={{ marginBottom: 'var(--space-4)' }}>
                <div className="row row--between">
                  <strong style={{ fontSize: 15 }}>{nameOf(e)}</strong>
                  <span className={e.date ? 'chip chip--blue' : 'chip'}>
                    {e.date ? fmtDate(e.date, 'd MMM yyyy', locale) : t('wedding2.cd.noDate')}
                  </span>
                </div>

                {e.dependsOn ? (
                  <p className="card__hint">
                    {t('wedding2.cd.derivedFrom', {
                      parent: nameById(e.dependsOn),
                      offset: offsetLabel(e.offsetDays ?? 0),
                    })}
                  </p>
                ) : (
                  <label className="stack stack--tight">
                    <span className="visually-hidden">{`${nameOf(e)} — ${t('wedding2.cd.fDate')}`}</span>
                    <input
                      type="date"
                      value={e.date ?? ''}
                      onChange={(ev) => patch('wedding', e.id, { date: ev.target.value || undefined })}
                    />
                  </label>
                )}

                {r?.problem && <p className="banner">{t(`wedding2.cd.dep.${r.problem}` as const)}</p>}

                <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
                  <label>
                    <span className="visually-hidden">{`${nameOf(e)} — ${t('wedding2.cd.fDependsOn')}`}</span>
                    <select
                      value={e.dependsOn ?? ''}
                      style={{ minHeight: 36, fontSize: 13 }}
                      onChange={(ev) =>
                        patch('wedding', e.id, {
                          dependsOn: ev.target.value || undefined,
                          offsetDays: ev.target.value ? (e.offsetDays ?? 0) : undefined,
                        })
                      }
                    >
                      <option value="">{t('wedding2.cd.ownDate')}</option>
                      {parents.map((p) => (
                        <option key={p.id} value={p.id}>
                          {t('wedding2.cd.followOpt', { name: nameOf(p) })}
                        </option>
                      ))}
                    </select>
                  </label>
                  {e.dependsOn && (
                    <label>
                      <span className="visually-hidden">{`${nameOf(e)} — ${t('wedding2.cd.fOffset')}`}</span>
                      <input
                        type="number"
                        step="1"
                        value={e.offsetDays ?? 0}
                        style={{ minHeight: 36, fontSize: 13, maxWidth: 96 }}
                        onChange={(ev) =>
                          patch('wedding', e.id, { offsetDays: Math.trunc(Number(ev.target.value) || 0) })
                        }
                      />
                    </label>
                  )}
                </div>

                <p className="card__hint">
                  {followers.length === 0
                    ? t('wedding2.cd.noFollowers')
                    : t('wedding2.cd.followers', {
                        n: followers.length,
                        names: followers.map(nameById).join(', '),
                      })}
                </p>

                <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
                  <span className="chip">{e.venue || t('wedding2.missVenue')}</span>
                  <span className="chip chip--mint">{t('wedding2.cd.eventPax', { n: pax.ya })}</span>
                  <span className="chip chip--yellow">
                    {t('wedding2.cd.eventMoney', {
                      planned: formatRupiah(money.planned, locale),
                      paid: formatRupiah(money.paid, locale),
                    })}
                  </span>
                </div>
              </div>
            )
          })
        )}
        <p className="disclaimer">{t('wedding2.cd.orderCaveat')}</p>
      </Card>

      {/* Who is holding what — W05 --------------------------------------- */}
      <Card title={t('wedding2.cd.loadCard')} icon="shared" hint={t('wedding2.cd.loadHint')}>
        <strong style={{ fontSize: 13 }}>{t('wedding2.cd.axisPartner')}</strong>
        <ul className="list">
          {[...PARTNER_OWNERS, 'none' as const].map((k) => (
            <li key={k} className="list__item">
              <Icon name="shared" size={18} />
              <span className="grow">
                {k === 'none' ? t('wedding2.cd.unassigned') : t(`wedding2.cd.own.${k}` as const)}
              </span>
              <span className="chip">
                {t('wedding2.cd.loadRow', {
                  open: load.partner.open[k],
                  handled: load.partner.handled[k],
                })}
              </span>
            </li>
          ))}
        </ul>
        <strong style={{ fontSize: 13 }}>{t('wedding2.cd.axisFamily')}</strong>
        <ul className="list">
          {[...FAMILY_OWNERS, 'none' as const].map((k) => (
            <li key={k} className="list__item">
              <Icon name="family" size={18} />
              <span className="grow">
                {k === 'none' ? t('wedding2.cd.unassigned') : t(`wedding2.cd.fam.${k}` as const)}
              </span>
              <span className="chip">
                {t('wedding2.cd.loadRow', {
                  open: load.family.open[k],
                  handled: load.family.handled[k],
                })}
              </span>
            </li>
          ))}
        </ul>
        <p className="disclaimer">{t('wedding2.cd.loadCaveat')}</p>
      </Card>

      {/* Countdown buckets — W04 ---------------------------------------- */}
      <Card title={t('wedding2.cd.buckets')} icon="tasks" hint={t('wedding2.cd.bucketsHint')}>
        {!anchor && <p className="banner">{t('wedding2.cd.noAnchor')}</p>}
        {groups.map((g) => (
          <div key={g.bucket} className="stack stack--tight" style={{ marginBottom: 'var(--space-4)' }}>
            <div className="row row--between">
              <strong style={{ fontSize: 14 }}>{t(`wedding2.cd.b.${g.bucket}` as const)}</strong>
              <span className="row" style={{ gap: 6 }}>
                {g.bucket === nowBucket && (
                  <span className="chip chip--blue">{t('wedding2.cd.now')}</span>
                )}
                <span className="chip">
                  {g.open === 0
                    ? t('wedding2.cd.allClear')
                    : t('wedding2.cd.openN', { n: g.open })}
                </span>
              </span>
            </div>
            <ul className="list">
              {/* `.list__item` already wraps and reserves the label's first line at
                  320 px — no inline width overrides here, they undo that tuning. */}
              {g.items.map((item) => (
                <li key={item.key} className="list__item">
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14, opacity: item.status === 'todo' ? 1 : 0.55 }}>
                      {t(`wedding2.chk.${item.key}` as const)}
                    </strong>
                    <span className="card__hint">
                      {item.dueDate ? fmtDate(item.dueDate, 'd MMM yyyy', locale) : t('wedding2.unknown')}
                      {item.status !== 'todo' ? ` · ${t(`wedding2.stat.${item.status}` as const)}` : ''}
                    </span>
                  </span>
                  {item.fromScale && (
                    <span className="chip">
                      {t('wedding2.cd.fromScale', { scale: t(`wedding2.cd.scale.${scale}` as const) })}
                    </span>
                  )}
                  {item.overdue && <span className="chip chip--yellow">{t('wedding2.overdueChip')}</span>}
                  <label>
                    <span className="visually-hidden">{`${t(`wedding2.chk.${item.key}` as const)} — ${t('wedding2.cd.fOwner')}`}</span>
                    <select
                      value={item.owner ?? ''}
                      style={{ minHeight: 36, fontSize: 13 }}
                      onChange={(ev) => setOwner(item.key, 'owner', ev.target.value as PartnerOwner | '')}
                    >
                      <option value="">{t('wedding2.cd.ownerNone')}</option>
                      {PARTNER_OWNERS.map((o) => (
                        <option key={o} value={o}>
                          {t(`wedding2.cd.own.${o}` as const)}
                        </option>
                      ))}
                    </select>
                  </label>
                  <label>
                    <span className="visually-hidden">{`${t(`wedding2.chk.${item.key}` as const)} — ${t('wedding2.cd.fFamily')}`}</span>
                    <select
                      value={item.family ?? ''}
                      style={{ minHeight: 36, fontSize: 13 }}
                      onChange={(ev) => setOwner(item.key, 'family', ev.target.value as FamilyOwner | '')}
                    >
                      <option value="">{t('wedding2.cd.familyNone')}</option>
                      {FAMILY_OWNERS.map((o) => (
                        <option key={o} value={o}>
                          {t(`wedding2.cd.fam.${o}` as const)}
                        </option>
                      ))}
                    </select>
                  </label>
                  {item.status === 'todo' ? (
                    <>
                      <button
                        className="btn btn--ghost btn--sm btn--icon"
                        onClick={() => setCheck(item.key, 'done')}
                      >
                        <Icon name="check" size={16} label={t('wedding2.markDone')} />
                      </button>
                      <button className="btn btn--ghost btn--sm" onClick={() => setCheck(item.key, 'skip')}>
                        {t('wedding2.markSkip')}
                      </button>
                    </>
                  ) : (
                    <button className="btn btn--ghost btn--sm" onClick={() => setCheck(item.key, null)}>
                      {t('wedding2.reopen')}
                    </button>
                  )}
                </li>
              ))}
            </ul>
          </div>
        ))}
      </Card>
    </div>
  )
}
