import type { ChecklistItem } from './checklist'
import type { EventType, FundSource, QuotaSide, Rsvp, VendorState } from './types'
import { FUND_SOURCES, QUOTA_SIDES } from './types'

/**
 * Planner maths (WED-06).
 *
 * Structural input types, not the stored records — so the tests can build a
 * three-field object instead of a full envelope, and so nothing in here can
 * reach the database. Returns keys and numbers only; no user-facing copy.
 */

export interface EventLike {
  id: string
  eventType: EventType
  date?: string
  venue?: string
  pic?: string
}
export interface GuestLike {
  quota: QuotaSide
  pax: number
  rsvp: Readonly<Record<string, Rsvp>>
}
export interface VendorLike {
  eventId?: string
  status: VendorState
  quote?: number
  bookingFee?: number
  dp?: number
  termin?: number
  pelunasan?: number
}
export interface BudgetLike {
  planned: number
  paid: number
  source: FundSource
}
export type Quota = Readonly<Record<QuotaSide, number>>

/**
 * The date the whole countdown hangs off. Akad/pemberkatan is the marriage
 * itself, so it wins over a resepsi that may sit weeks later; otherwise the
 * earliest dated event, so a couple who only booked the lamaran still gets a
 * usable countdown.
 */
export function anchorDate(events: readonly EventLike[]): string | undefined {
  const dated = events.filter((e) => e.date)
  const core = dated.filter((e) => e.eventType === 'akad' || e.eventType === 'pemberkatan')
  const pool = core.length > 0 ? core : dated
  return pool.map((e) => e.date!).sort()[0]
}

/** Pax per RSVP state for one event. `belum` covers guests with no answer yet. */
export function paxForEvent(
  guests: readonly GuestLike[],
  eventId: string,
): Record<Rsvp, number> {
  const out: Record<Rsvp, number> = { belum: 0, ya: 0, ragu: 0, nggak: 0 }
  for (const g of guests) out[g.rsvp[eventId] ?? 'belum'] += Math.max(0, g.pax)
  return out
}

export interface QuotaRow {
  side: QuotaSide
  used: number
  limit: number
  over: number
}

/** Invited pax per family bucket against its quota. Never per-partner scoring —
 *  it is a seating constraint, not a comparison between two people. */
export function quotaUsage(guests: readonly GuestLike[], quota?: Quota): QuotaRow[] {
  return QUOTA_SIDES.map((side) => {
    const used = guests.filter((g) => g.quota === side).reduce((s, g) => s + Math.max(0, g.pax), 0)
    const limit = quota?.[side] ?? 0
    return { side, used, limit, over: limit > 0 ? Math.max(0, used - limit) : 0 }
  })
}

export interface BudgetTotals {
  planned: number
  paid: number
  left: number
  bySource: Record<FundSource, { planned: number; paid: number }>
}

export function budgetTotals(items: readonly BudgetLike[]): BudgetTotals {
  const bySource = Object.fromEntries(
    FUND_SOURCES.map((s) => [s, { planned: 0, paid: 0 }]),
  ) as BudgetTotals['bySource']
  let planned = 0
  let paid = 0
  for (const b of items) {
    planned += b.planned
    paid += b.paid
    bySource[b.source].planned += b.planned
    bySource[b.source].paid += b.paid
  }
  return { planned, paid, left: planned - paid, bySource }
}

/**
 * What a vendor's payment terms add up to. `outstanding` stays undefined when
 * no quote was entered — an unknown remainder must read as unknown, not as
 * zero-owed.
 */
export function vendorTerms(v: VendorLike): { committed: number; outstanding?: number } {
  const committed = (v.bookingFee ?? 0) + (v.dp ?? 0) + (v.termin ?? 0) + (v.pelunasan ?? 0)
  return { committed, ...(v.quote === undefined ? {} : { outstanding: v.quote - committed }) }
}

// --- readiness ------------------------------------------------------------

export type RiskKey =
  | 'hasEvent'
  | 'dates'
  | 'checklistDue'
  | 'noOverspend'
  | 'vendors'
  | 'venues'
  | 'withinQuota'
  | 'budgetSet'
  | 'guests'
  | 'pics'
  | 'rundowns'
  | 'quotaSet'

/** Worst first. The dashboard names the top few in words rather than colouring a bar. */
const RISK_ORDER: readonly RiskKey[] = [
  'hasEvent',
  'dates',
  'checklistDue',
  'noOverspend',
  'vendors',
  'venues',
  'withinQuota',
  'budgetSet',
  'guests',
  'pics',
  'rundowns',
  'quotaSet',
]

export interface Risk {
  key: RiskKey
  n?: number
  amount?: number
}

export interface ReadinessInput {
  events: readonly EventLike[]
  /** Event ids that already have at least one rundown line. */
  rundownEventIds: readonly string[]
  guests: readonly GuestLike[]
  quota?: Quota
  vendors: readonly VendorLike[]
  budget: readonly BudgetLike[]
  checklist: readonly ChecklistItem[]
}

export interface Readiness {
  pct: number
  passed: number
  total: number
  risks: Risk[]
}

/**
 * "Siap acara" only — the logistics of the party. It deliberately shares
 * nothing with the WED-02 readiness answers about living together; blueprint 03
 * §7 requires the two never be mixed into one number, and a percentage over
 * someone's feelings about money or children would be exactly that.
 *
 * The number is a plain count of passed checkpoints over applicable ones, so it
 * is explainable: every missing point is also listed as a named risk.
 */
export function readiness(input: ReadinessInput): Readiness {
  const { events, rundownEventIds, guests, quota, vendors, budget, checklist } = input
  const rundowns = new Set(rundownEventIds)
  const money = budgetTotals(budget)
  const dueTodo = checklist.filter((c) => c.overdue).length
  const quotaSet = QUOTA_SIDES.some((s) => (quota?.[s] ?? 0) > 0)
  const overQuota = quotaUsage(guests, quota).filter((r) => r.over > 0)
  const hasEvents = events.length > 0

  const coveredByVendor = (id: string) =>
    vendors.some((v) => v.status === 'deal' && (v.eventId === undefined || v.eventId === id))

  const missing = (pred: (e: EventLike) => boolean) => events.filter(pred).length

  const checks: { key: RiskKey; applicable: boolean; ok: boolean; n?: number; amount?: number }[] = [
    { key: 'hasEvent', applicable: true, ok: hasEvents },
    { key: 'dates', applicable: hasEvents, ok: missing((e) => !e.date) === 0, n: missing((e) => !e.date) },
    { key: 'venues', applicable: hasEvents, ok: missing((e) => !e.venue) === 0, n: missing((e) => !e.venue) },
    { key: 'pics', applicable: hasEvents, ok: missing((e) => !e.pic) === 0, n: missing((e) => !e.pic) },
    {
      key: 'rundowns',
      applicable: hasEvents,
      ok: missing((e) => !rundowns.has(e.id)) === 0,
      n: missing((e) => !rundowns.has(e.id)),
    },
    {
      key: 'vendors',
      applicable: hasEvents,
      ok: missing((e) => !coveredByVendor(e.id)) === 0,
      n: missing((e) => !coveredByVendor(e.id)),
    },
    { key: 'budgetSet', applicable: true, ok: budget.length > 0 },
    {
      key: 'noOverspend',
      applicable: budget.length > 0,
      ok: money.paid <= money.planned,
      amount: Math.max(0, money.paid - money.planned),
    },
    { key: 'guests', applicable: true, ok: guests.length > 0 },
    { key: 'quotaSet', applicable: guests.length > 0, ok: quotaSet },
    { key: 'withinQuota', applicable: quotaSet, ok: overQuota.length === 0, n: overQuota.length },
    {
      key: 'checklistDue',
      applicable: checklist.some((c) => c.due),
      ok: dueTodo === 0,
      n: dueTodo,
    },
  ]

  const applicable = checks.filter((c) => c.applicable)
  const passed = applicable.filter((c) => c.ok).length
  const total = applicable.length
  const failed = new Map(applicable.filter((c) => !c.ok).map((c) => [c.key, c]))

  return {
    pct: total === 0 ? 0 : Math.round((passed / total) * 100),
    passed,
    total,
    // Capped at three. A dashboard that lists twelve problems tells you nothing
    // about which one to do on Saturday.
    risks: RISK_ORDER.filter((k) => failed.has(k))
      .slice(0, 3)
      .map((k) => {
        const c = failed.get(k)!
        return {
          key: k,
          ...(c.n === undefined ? {} : { n: c.n }),
          ...(c.amount === undefined ? {} : { amount: c.amount }),
        }
      }),
  }
}
