import type { IssueSeverity } from './types'

/**
 * Day-of logic (W21, W24, W25).
 *
 * Structural inputs, numeric/key outputs — no envelope, no database, no
 * user-facing copy. The screen turns a level into a message key. Nothing here
 * ever names a single guest in a warning: a no-show is a count, not an accusation.
 */

/** "HH:MM" → minutes since midnight, or null if it is not a real time. */
export function parseHm(s: string): number | null {
  const m = /^(\d{1,2}):(\d{2})$/.exec(s.trim())
  if (!m) return null
  const h = Number(m[1])
  const min = Number(m[2])
  if (h > 23 || min > 59) return null
  return h * 60 + min
}

// -- W24 live rundown ------------------------------------------------------

export interface RundownLineLike {
  id: string
  time: string
}

export interface LivePosition {
  /** The line in progress now: the last one whose time has arrived. */
  currentId?: string
  /** The next line still to come. */
  nextId?: string
  /** Lines with an unreadable time, so the screen can flag them for a fix. */
  badTimeIds: string[]
}

/**
 * Where the clock sits in the rundown (W24). `current` is the last line whose
 * start time has passed, `next` is the first line still ahead — so before the
 * first line there is no current, and after the last there is no next. Lines with
 * a broken time are set aside rather than silently dropped, because on the day a
 * mistyped "25:00" should be visible, not invisible. Pure clock reading: it never
 * looks at a `done` flag, so marking a line done cannot skip the timeline forward.
 */
export function liveRundown(lines: readonly RundownLineLike[], nowMin: number): LivePosition {
  const timed = lines
    .map((l) => ({ id: l.id, min: parseHm(l.time) }))
    .filter((l): l is { id: string; min: number } => l.min !== null)
    .sort((a, b) => a.min - b.min)
  const badTimeIds = lines.filter((l) => parseHm(l.time) === null).map((l) => l.id)

  let currentId: string | undefined
  let nextId: string | undefined
  for (const l of timed) {
    if (l.min <= nowMin) currentId = l.id
    else {
      nextId = l.id
      break
    }
  }
  return { currentId, nextId, badTimeIds }
}

// -- W21 check-in reconciliation ------------------------------------------

export interface ReconcileGuestLike {
  pax: number
  /** W15: 'rsvp' means they actually replied yes. */
  invite?: string
  /** W20: set when they walked through the door. */
  checkedInAt?: string
}

export type CateringLevel = 'unknown' | 'under' | 'exact' | 'over'

export interface CheckinReconcile {
  /** Guests who checked in, and their summed pax. */
  arrivedGuests: number
  arrivedPax: number
  /** Confirmed (invite === 'rsvp') guests who never checked in. */
  noShowGuests: number
  noShowPax: number
  /** Arrived but never RSVP'd — came anyway. Surfaced, not scolded. */
  walkInGuests: number
  walkInPax: number
  /** Confirmed heads expected at the door. */
  expectedPax: number
  /** Catering headcount ordered, if the couple entered one. */
  cateringPax?: number
  /** arrivedPax − cateringPax. Undefined until a catering number exists. */
  cateringDiff?: number
  cateringLevel: CateringLevel
}

/**
 * Who came, who did not, and arrived heads against catering (W21). A guest is a
 * no-show only if they had confirmed — an unanswered invite was never a promise,
 * so it is not a broken one. Catering is compared, never assumed equal: a couple
 * who over-ordered by twenty seats sees that plainly, with no advice on what to
 * do about it.
 */
export function checkinReconcile(
  guests: readonly ReconcileGuestLike[],
  cateringPax?: number,
): CheckinReconcile {
  const pax = (g: ReconcileGuestLike) => Math.max(0, g.pax)
  const arrived = guests.filter((g) => g.checkedInAt)
  const confirmed = guests.filter((g) => g.invite === 'rsvp')
  const noShow = confirmed.filter((g) => !g.checkedInAt)
  const walkIn = arrived.filter((g) => g.invite !== 'rsvp')

  const arrivedPax = arrived.reduce((s, g) => s + pax(g), 0)
  const out: CheckinReconcile = {
    arrivedGuests: arrived.length,
    arrivedPax,
    noShowGuests: noShow.length,
    noShowPax: noShow.reduce((s, g) => s + pax(g), 0),
    walkInGuests: walkIn.length,
    walkInPax: walkIn.reduce((s, g) => s + pax(g), 0),
    expectedPax: confirmed.reduce((s, g) => s + pax(g), 0),
    cateringLevel: 'unknown',
  }
  if (cateringPax !== undefined && cateringPax > 0) {
    const diff = arrivedPax - cateringPax
    out.cateringPax = cateringPax
    out.cateringDiff = diff
    out.cateringLevel = diff === 0 ? 'exact' : diff > 0 ? 'over' : 'under'
  }
  return out
}

// -- W25 issue log ---------------------------------------------------------

export interface IssueLike {
  severity: IssueSeverity
  resolvedAt?: string
}

export interface IssueSummary {
  open: number
  resolved: number
  /** Open issues at the loudest level, for a single calm chip. */
  openPenting: number
}

/** Open vs resolved counts for the day's log (W25). Counts only — no verdict. */
export function issueSummary(issues: readonly IssueLike[]): IssueSummary {
  const open = issues.filter((i) => !i.resolvedAt)
  return {
    open: open.length,
    resolved: issues.length - open.length,
    openPenting: open.filter((i) => i.severity === 'penting').length,
  }
}
