/**
 * Angpao / gift record totals (W18).
 *
 * A private ledger of what came in — cash amounts and non-cash gifts. Records
 * are created private-by-default (C1_personal); only the owner may widen them.
 * This module just tallies what was recorded; it describes, never advises, and
 * never treats the sum as complete. No copy, no database.
 */

export interface GiftLike {
  amount?: number
  item?: string
}

export interface GiftTotals {
  count: number
  cashCount: number
  cashTotal: number
  itemCount: number
}

export function giftTotals(gifts: readonly GiftLike[]): GiftTotals {
  let cashCount = 0
  let cashTotal = 0
  let itemCount = 0
  for (const g of gifts) {
    if (g.amount && g.amount > 0) {
      cashCount += 1
      cashTotal += g.amount
    }
    if (g.item && g.item.trim()) itemCount += 1
  }
  return { count: gifts.length, cashCount, cashTotal, itemCount }
}
