/**
 * Beauty/prep critical-path logic (W29).
 *
 * On the day, hair-and-makeup is the real critical path: it cannot be rushed and
 * everyone must be dressed before the ceremony. Rather than ask the couple to
 * guess start times, this back-solves them from a single "must be ready by" time
 * — each person's tasks run in sequence and finish exactly at ready-by, so the
 * earliest start falls out of the durations. Move ready-by and every start moves.
 *
 * People prep in parallel (bride with the MUA, groom elsewhere), so each person
 * is an independent chain all ending at the same ready-by moment.
 *
 * Structural in, minutes out — the screen formats "HH:MM". No copy, no database.
 */

export interface PrepTaskLike {
  id: string
  person: string
  durationMin: number
  /** Sequence within a person's chain; lower runs first. Absent sorts last. */
  order?: number
}

export interface PrepSlot {
  id: string
  person: string
  startMin: number
  endMin: number
  durationMin: number
}

export interface PersonPrep {
  person: string
  startMin: number
  totalMin: number
}

export interface PrepPlan {
  /** Every task with a solved start/end, sorted by start then person. */
  slots: PrepSlot[]
  perPerson: PersonPrep[]
  /** Earliest start across everyone — when the first alarm goes off. */
  earliestStartMin: number
  /**
   * True when a chain would have to start before midnight (negative minutes):
   * the prep simply does not fit before ready-by. A real constraint to surface,
   * never silently clamped away.
   */
  tooEarly: boolean
}

/**
 * Back-solve the prep timeline from `readyByMin` (W29). Within each person, tasks
 * are chained so the last finishes at ready-by; across people the chains run in
 * parallel. Durations are clamped non-negative. Empty in → an empty plan that
 * starts at ready-by (nothing to begin early).
 */
export function prepSchedule(tasks: readonly PrepTaskLike[], readyByMin: number): PrepPlan {
  const byPerson = new Map<string, PrepTaskLike[]>()
  for (const t of tasks) {
    const list = byPerson.get(t.person) ?? []
    list.push(t)
    byPerson.set(t.person, list)
  }

  const slots: PrepSlot[] = []
  const perPerson: PersonPrep[] = []

  for (const [person, list] of byPerson) {
    // Stable order: explicit `order` first (asc), unset last, input order breaking ties.
    const ordered = list
      .map((t, i) => ({ t, i }))
      .sort((a, b) => {
        const oa = a.t.order ?? Number.POSITIVE_INFINITY
        const ob = b.t.order ?? Number.POSITIVE_INFINITY
        return oa === ob ? a.i - b.i : oa - ob
      })
      .map((x) => x.t)

    // Walk from the last task backwards: it ends at ready-by, each earlier task
    // ends where the next one starts.
    let cursor = readyByMin
    const personSlots: PrepSlot[] = []
    for (let k = ordered.length - 1; k >= 0; k--) {
      const dur = Math.max(0, ordered[k]!.durationMin)
      const endMin = cursor
      const startMin = cursor - dur
      personSlots.push({ id: ordered[k]!.id, person, startMin, endMin, durationMin: dur })
      cursor = startMin
    }
    const totalMin = personSlots.reduce((s, p) => s + p.durationMin, 0)
    perPerson.push({ person, startMin: cursor, totalMin })
    slots.push(...personSlots)
  }

  slots.sort((a, b) => (a.startMin === b.startMin ? a.person.localeCompare(b.person) : a.startMin - b.startMin))
  perPerson.sort((a, b) => a.person.localeCompare(b.person))
  const earliestStartMin = slots.length ? Math.min(...slots.map((s) => s.startMin)) : readyByMin
  return { slots, perPerson, earliestStartMin, tooEarly: earliestStartMin < 0 }
}
