import { useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, PARTNER_VISIBILITY_OPTIONS, Sheet, VisibilityBadge } from '@/components/ui'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { READINESS_AREAS, type ReadinessArea, type Visibility, type WeddingRecord } from '@/types/domain'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import { useT } from '@/i18n'
import { Planner } from './Planner'
import { Countdown } from './Countdown'
import { Money } from './MoneyTab'
import { GuestsTab } from './GuestsTab'
import { SeatingTab } from './SeatingTab'
import { FavorsTab } from './FavorsTab'
import { CheckinTab } from './CheckinTab'
import { DdayTab } from './DdayTab'
import { DocsTab } from './DocsTab'
import { LogisticsTab } from './LogisticsTab'
import { ExtrasTab } from './ExtrasTab'
import { SummaryTab } from './SummaryTab'
import './wedding.css'

/**
 * Wedding (WED-01..06).
 *
 * Workspaces that never blend: "siap hidup bareng" is about the marriage,
 * "siap acara" is about the party. Blueprint 03 §7 is explicit that readiness
 * answers must not sit inside a vendor checklist, and that private answers are
 * never auto-compared between partners. The third tab is the multi-event
 * planner (WED-06) and lives entirely on the "acara" side of that line.
 */

/** Phases in the order they happen; labels come from `wed.phase.*`. */
const PHASES = ['jauh_hari', 'sebulan', 'seminggu', 'hari_h'] as const

type Tab = 'readiness' | 'party' | 'plan' | 'countdown' | 'money' | 'guests' | 'seating' | 'favors' | 'checkin' | 'dday' | 'docs' | 'logistics' | 'extras' | 'summary'
type SheetKind = 'readiness' | 'wedding_task' | 'vendor' | 'guest' | 'wedding_budget' | null

export default function Wedding() {
  const { t, locale } = useI18n()
  const { profile, profiles } = useSession()
  const me = profile?.id
  const [tab, setTab] = useState<Tab>('readiness')
  const [sheet, setSheet] = useState<SheetKind>(null)
  const rows = useOwned<WeddingRecord>('wedding', me)

  if (!profile || !me) return null

  const of = <K extends WeddingRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is Extract<WeddingRecord, { kind: K }> => r.kind === kind)

  const readiness = of('readiness')
  const tasks = of('wedding_task')
  const vendors = of('vendor')
  const guests = of('guest')
  const budget = of('wedding_budget')

  const planned = budget.reduce((s, b) => s + b.planned, 0)
  const paid = budget.reduce((s, b) => s + b.paid, 0)
  const seats = guests.filter((g) => g.status !== 'nggak_hadir').reduce((s, g) => s + g.seats, 0)

  return (
    <div className="stack">
      <h1>{t('nav.wedding')}</h1>

      <div className="segmented segmented--wrap" role="group" aria-label={t('wed.tabGroup')}>
        <button aria-pressed={tab === 'readiness'} onClick={() => setTab('readiness')}>{t('wed.tabReadiness')}
        </button>
        <button aria-pressed={tab === 'party'} onClick={() => setTab('party')}>{t('wed.tabParty')}
        </button>
        <button aria-pressed={tab === 'plan'} onClick={() => setTab('plan')}>{t('wedding2.tab')}
        </button>
        <button aria-pressed={tab === 'countdown'} onClick={() => setTab('countdown')}>{t('wedding2.cd.tab')}
        </button>
        <button aria-pressed={tab === 'money'} onClick={() => setTab('money')}>{t('wedding2.mny.tab')}
        </button>
        <button aria-pressed={tab === 'guests'} onClick={() => setTab('guests')}>{t('wedding2.gst.tab')}
        </button>
        <button aria-pressed={tab === 'seating'} onClick={() => setTab('seating')}>{t('wedding2.seat.tab')}
        </button>
        <button aria-pressed={tab === 'favors'} onClick={() => setTab('favors')}>{t('wedding2.fav.tab')}
        </button>
        <button aria-pressed={tab === 'checkin'} onClick={() => setTab('checkin')}>{t('wedding2.chk.tab')}
        </button>
        <button aria-pressed={tab === 'dday'} onClick={() => setTab('dday')}>{t('wedding2.dday.tab')}
        </button>
        <button aria-pressed={tab === 'logistics'} onClick={() => setTab('logistics')}>{t('wedding2.log.tab')}
        </button>
        <button aria-pressed={tab === 'docs'} onClick={() => setTab('docs')}>{t('wedding2.doc.tab')}
        </button>
        <button aria-pressed={tab === 'extras'} onClick={() => setTab('extras')}>{t('wedding2.extra.tab')}
        </button>
        <button aria-pressed={tab === 'summary'} onClick={() => setTab('summary')}>{t('wedding2.sum.tab')}
        </button>
      </div>

      {tab === 'summary' ? (
        <SummaryTab me={me} />
      ) : tab === 'extras' ? (
        <ExtrasTab me={me} />
      ) : tab === 'docs' ? (
        <DocsTab me={me} />
      ) : tab === 'logistics' ? (
        <LogisticsTab me={me} />
      ) : tab === 'dday' ? (
        <DdayTab me={me} />
      ) : tab === 'checkin' ? (
        <CheckinTab me={me} />
      ) : tab === 'favors' ? (
        <FavorsTab me={me} />
      ) : tab === 'seating' ? (
        <SeatingTab me={me} />
      ) : tab === 'guests' ? (
        <GuestsTab me={me} />
      ) : tab === 'money' ? (
        <Money me={me} />
      ) : tab === 'countdown' ? (
        <Countdown me={me} />
      ) : tab === 'plan' ? (
        <Planner me={me} />
      ) : tab === 'readiness' ? (
        <>
          <p className="card__hint">{t('wed.readinessIntro')}
          </p>

          <Card
            title={t('wed.eightThings')}
            icon="checkin"
            action={
              <button className="btn btn--sm" onClick={() => setSheet('readiness')}>
                <Icon name="plus" size={16} /> {t('wed.answer')}
              </button>
            }
            hint={t('wed.readinessHint')}
          >
            <ul className="list">
              {READINESS_AREAS.map((area) => {
                const mine = readiness.filter((r) => r.area === area)
                return (
                  <li key={area} className="list__item">
                    <Icon name="heart" size={18} />
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{t(`area.${area}` as const)}</strong>
                      <span className="card__hint">
                        {mine.length === 0
                          ? t('wed.notAnswered')
                          : t(`wed.stance.${mine[mine.length - 1]!.stance}` as const)}
                      </span>
                    </span>
                    {mine.length > 0 && <VisibilityBadge visibility={mine[mine.length - 1]!.visibility} />}
                  </li>
                )
              })}
            </ul>
          </Card>

          {readiness.length > 0 && (
            <Card title={t('wed.yourAnswers')} icon="private">
              <ul className="list">
                {readiness.map((r) => (
                  <li key={r.id} className="list__item">
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 13 }}>{t(`area.${r.area}` as const)}</strong>
                      <span className="card__hint">{r.answer}</span>
                    </span>
                    <VisibilityBadge visibility={r.visibility} />
                    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', r.id, me)}>
                      <Icon name="close" size={16} label={t('wed.deleteAnswer')} />
                    </button>
                  </li>
                ))}
              </ul>
            </Card>
          )}

          <p className="disclaimer">{t('wed.elsimil')}
          </p>
        </>
      ) : (
        <>
          <Card title={t('wed.budget')} icon="money" action={<button className="btn btn--sm" onClick={() => setSheet('wedding_budget')}><Icon name="plus" size={16} /> {t('wed.budgetItem')}</button>}>
            {budget.length === 0 ? (
              <EmptyState icon="money" title={t('wed.noBudget')} hint={t('wed.noBudgetHint')} />
            ) : (
              <>
                <div className="row row--between" style={{ marginBottom: 'var(--space-2)' }}>
                  <span className="chip chip--yellow">{t('wed.planned', { amount: formatRupiah(planned, locale) })}</span>
                  <span className="chip chip--mint">{t('wed.paidTotal', { amount: formatRupiah(paid, locale) })}</span>
                  <span className="chip">{t('wed.remaining', { amount: formatRupiah(planned - paid, locale) })}</span>
                </div>
                <ul className="list">
                  {budget.map((b) => (
                    <li key={b.id} className="list__item">
                      <Icon name="money" size={18} />
                      <span className="grow stack stack--tight">
                        <strong style={{ fontSize: 14 }}>{b.label}</strong>
                        <span className="card__hint">
                          {t('wed.paidOf', {
                            paid: formatRupiah(b.paid, locale),
                            planned: formatRupiah(b.planned, locale),
                          })}
                          {b.dueDate ? ` · ${whenLabel(b.dueDate, t, locale)}` : ''}
                        </span>
                      </span>
                      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', b.id, me)}>
                        <Icon name="close" size={16} label={t('common.deleteX', { name: b.label })} />
                      </button>
                    </li>
                  ))}
                </ul>
              </>
            )}
          </Card>

          <Card title={t('wed.tasks')} icon="tasks" action={<button className="btn btn--sm" onClick={() => setSheet('wedding_task')}><Icon name="plus" size={16} /> {t('quick.task')}</button>}>
            {tasks.length === 0 ? (
              <EmptyState icon="tasks" title={t('wed.noTasks')} hint={t('wed.noTasksHint')} />
            ) : (
              PHASES.map((phase) => {
                const list = tasks.filter((t) => t.phase === phase)
                if (list.length === 0) return null
                return (
                  <div key={phase} className="stack stack--tight" style={{ marginBottom: 'var(--space-3)' }}>
                    <strong style={{ fontSize: 13 }}>{t(`wed.phase.${phase}` as const)}</strong>
                    <ul className="list">
                      {list.map((task) => (
                        <li key={task.id} className="list__item">
                          <button
                            className="btn btn--ghost btn--sm"
                            aria-label={`Tandai selesai: ${task.title}`}
                            onClick={() => patch('wedding', task.id, { status: task.status === 'done' ? 'todo' : 'done' })}
                          >
                            <Icon name="check" size={16} />
                          </button>
                          <span className="grow stack stack--tight">
                            <strong style={{ fontSize: 14, opacity: task.status === 'done' ? 0.55 : 1 }}>{task.title}</strong>
                            <span className="card__hint">
                              {profiles.find((p) => p.id === task.accountableProfileId)?.displayName ?? '—'}
                              {task.dueDate ? ` · ${whenLabel(task.dueDate, t, locale)}` : ''}
                            </span>
                          </span>
                        </li>
                      ))}
                    </ul>
                  </div>
                )
              })
            )}
          </Card>

          <Card title={t('wed.vendors')} icon="ring" action={<button className="btn btn--sm" onClick={() => setSheet('vendor')}><Icon name="plus" size={16} /> {t('wed.vendors')}</button>} hint={t('wed.vendorsHint')}>
            {vendors.length === 0 ? (
              <EmptyState icon="ring" title={t('wed.noVendors')} />
            ) : (
              <ul className="list">
                {vendors.map((v) => (
                  <li key={v.id} className="list__item">
                    <Icon name="ring" size={18} />
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{v.name}</strong>
                      <span className="card__hint">
                        {v.category}
                        {v.quotedPrice ? ` · ${formatRupiah(v.quotedPrice, locale)}` : ''}
                        {v.sourceNote ? ` · ${t('wed.knownFrom', { source: v.sourceNote })}` : ''}
                      </span>
                    </span>
                    <span className="chip">{v.status}</span>
                  </li>
                ))}
              </ul>
            )}
          </Card>

          <Card
            title={t('wed.guests')}
            icon="family"
            action={<button className="btn btn--sm" onClick={() => setSheet('guest')}><Icon name="plus" size={16} /> {t('wed.guests')}</button>}
            hint={t('wed.guestsHint', { entries: guests.length, seats })}
          >
            {guests.length === 0 ? (
              <EmptyState icon="family" title={t('wed.noGuests')} hint={t('wed.noGuestsHint')} />
            ) : (
              <ul className="list">
                {(['aku', 'pasangan', 'bersama'] as const).map((side) => {
                  const list = guests.filter((g) => g.side === side)
                  if (!list.length) return null
                  const s = list.reduce((a, g) => a + g.seats, 0)
                  return (
                    <li key={side} className="list__item">
                      <Icon name="shared" size={18} />
                      <span className="grow">
                        {t('wed.fromSide', { side: t(`wed.side.${side}` as const) })}
                      </span>
                      <span className="chip">{t('wed.entries', { n: list.length })}</span>
                      <span className="chip chip--blue">{t('wed.seats', { n: s })}</span>
                    </li>
                  )
                })}
              </ul>
            )}
          </Card>
        </>
      )}

      <WeddingSheet kind={sheet} onClose={() => setSheet(null)} me={me} profiles={profiles} />
    </div>
  )
}

function WeddingSheet({
  kind,
  onClose,
  me,
  profiles,
}: {
  kind: SheetKind
  onClose: () => void
  me: string
  profiles: { id: string; displayName: string }[]
}) {
  const t = useT()
  const [area, setArea] = useState<ReadinessArea>('values')
  const [answer, setAnswer] = useState('')
  const [stance, setStance] = useState<'belum' | 'lagi dipikir' | 'udah jelas'>('lagi dipikir')
  const [visibility, setVis] = useState<Visibility>('private')
  const [text, setText] = useState('')
  const [text2, setText2] = useState('')
  const [num, setNum] = useState('')
  const [num2, setNum2] = useState('')
  const [date, setDate] = useState('')
  const [owner, setOwner] = useState(me)
  const [phase, setPhase] = useState<'jauh_hari' | 'sebulan' | 'seminggu' | 'hari_h'>('jauh_hari')
  const [side, setSide] = useState<'aku' | 'pasangan' | 'bersama'>('bersama')

  function reset() {
    setAnswer('')
    setText('')
    setText2('')
    setNum('')
    setNum2('')
    setDate('')
  }

  async function save() {
    if (kind === 'readiness') {
      if (!answer.trim()) return
      await db.wedding.add({
        ...newEnvelope(me, 'C3_relationship', { visibility }),
        kind: 'readiness',
        area,
        prompt: area,
        answer: answer.trim(),
        stance,
      } as never)
    } else if (kind === 'wedding_task') {
      if (!text.trim()) return
      await db.wedding.add({
        ...newEnvelope(me, 'C2_shared_ops'),
        kind: 'wedding_task',
        title: text.trim(),
        accountableProfileId: owner,
        ...(date ? { dueDate: date } : {}),
        status: 'todo',
        phase,
      } as never)
    } else if (kind === 'vendor') {
      if (!text.trim()) return
      await db.wedding.add({
        ...newEnvelope(me, 'C2_shared_ops'),
        kind: 'vendor',
        name: text.trim(),
        category: text2.trim() || 'lainnya',
        ...(num ? { quotedPrice: Number(num) } : {}),
        status: 'dilirik',
      } as never)
    } else if (kind === 'guest') {
      if (!text.trim()) return
      await db.wedding.add({
        ...newEnvelope(me, 'C2_shared_ops'),
        kind: 'guest',
        name: text.trim(),
        side,
        seats: Number(num) || 1,
        status: 'draft',
      } as never)
    } else if (kind === 'wedding_budget') {
      if (!text.trim() || !num) return
      await db.wedding.add({
        ...newEnvelope(me, 'C2_shared_ops'),
        kind: 'wedding_budget',
        label: text.trim(),
        planned: Number(num),
        paid: Number(num2) || 0,
        ...(date ? { dueDate: date } : {}),
      } as never)
    }
    reset()
    onClose()
  }

  return (
    <Sheet open={kind !== null} onClose={onClose} title={kind ? t(`wed.sheet.${kind}` as const) : ''}>
      <div className="stack">
        {kind === 'readiness' && (
          <>
            <Field label={t('wed.aboutWhat')}>
              {(p) => (
                <select {...p} value={area} onChange={(e) => setArea(e.target.value as ReadinessArea)}>
                  {READINESS_AREAS.map((a) => (
                    <option key={a} value={a}>
                      {t(`area.${a}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
            <p className="banner">{t(`area.${area}.q` as const)}</p>
            <Field label={t('wed.yourAnswers')}>
              {(p) => <textarea {...p} value={answer} onChange={(e) => setAnswer(e.target.value)} />}
            </Field>
            <Field label={t('wed.stance')}>
              {(p) => (
                <select {...p} value={stance} onChange={(e) => setStance(e.target.value as typeof stance)}>
                  <option value="belum">{t('wed.stance.belum')}</option>
                  <option value="lagi dipikir">{t('wed.stance.lagi dipikir')}</option>
                  <option value="udah jelas">{t('wed.stance.udah jelas')}</option>
                </select>
              )}
            </Field>
            <Field label={t('common.whoCanSee')} hint={t('wed.answerPrivacyHint')}>
              {(p) => (
                <select {...p} value={visibility} onChange={(e) => setVis(e.target.value as Visibility)}>
                  {PARTNER_VISIBILITY_OPTIONS.map((v) => (
                    <option key={v} value={v}>
                      {t(`vis.opt.${v}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
          </>
        )}

        {kind === 'wedding_task' && (
          <>
            <Field label={t('home.taskWhat')}>
              {(p) => <input {...p} type="text" value={text} onChange={(e) => setText(e.target.value)} />}
            </Field>
            <Field label={t('common.who')}>
              {(p) => (
                <select {...p} value={owner} onChange={(e) => setOwner(e.target.value)}>
                  {profiles.map((x) => (
                    <option key={x.id} value={x.id}>
                      {x.displayName}
                    </option>
                  ))}
                </select>
              )}
            </Field>
            <Field label={t('wed.whenPhase')}>
              {(p) => (
                <select {...p} value={phase} onChange={(e) => setPhase(e.target.value as typeof phase)}>
                  {PHASES.map((p2) => (
                    <option key={p2} value={p2}>
                      {t(`wed.phase.${p2}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
            <Field label={t('home.deadline')} hint={t('common.optional')}>
              {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
            </Field>
          </>
        )}

        {kind === 'vendor' && (
          <>
            <Field label={t('wed.vendorName')}>{(p) => <input {...p} type="text" value={text} onChange={(e) => setText(e.target.value)} />}</Field>
            <Field label={t('wed.vendorCategory')} hint={t('wed.vendorCategoryHint')}>
              {(p) => <input {...p} type="text" value={text2} onChange={(e) => setText2(e.target.value)} />}
            </Field>
            <Field label={t('wed.vendorQuote')} hint={t('common.optional')}>
              {(p) => <input {...p} type="number" min="0" value={num} onChange={(e) => setNum(e.target.value)} />}
            </Field>
          </>
        )}

        {kind === 'guest' && (
          <>
            <Field label={t('wed.guestName')}>{(p) => <input {...p} type="text" value={text} onChange={(e) => setText(e.target.value)} />}</Field>
            <Field label={t('wed.guestSide')}>
              {(p) => (
                <select {...p} value={side} onChange={(e) => setSide(e.target.value as typeof side)}>
                  <option value="aku">{t('wed.side.aku')}</option>
                  <option value="pasangan">{t('wed.side.pasangan')}</option>
                  <option value="bersama">{t('wed.side.bersama')}</option>
                </select>
              )}
            </Field>
            <Field label={t('wed.guestSeats')}>
              {(p) => <input {...p} type="number" min="1" value={num} onChange={(e) => setNum(e.target.value)} />}
            </Field>
          </>
        )}

        {kind === 'wedding_budget' && (
          <>
            <Field label={t('wed.budgetLabel')}>{(p) => <input {...p} type="text" value={text} onChange={(e) => setText(e.target.value)} />}</Field>
            <Field label={t('wed.budgetPlanned')}>
              {(p) => <input {...p} type="number" min="0" value={num} onChange={(e) => setNum(e.target.value)} />}
            </Field>
            <Field label={t('wed.budgetPaid')} hint={t('wed.budgetPaidHint')}>
              {(p) => <input {...p} type="number" min="0" value={num2} onChange={(e) => setNum2(e.target.value)} />}
            </Field>
            <Field label={t('fin.dueDate')} hint={t('common.optional')}>
              {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
            </Field>
          </>
        )}

        <button className="btn btn--block" onClick={save}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
