import { useEffect, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n } from '@/i18n'
import { lodgingSummary } from './lodging'
import { requirementProgress } from './requirements'
import { shotProgress, cueProgress } from './creative'
import { contingencySummary } from './contingency'
import {
  REQ_CATEGORIES,
  REQ_STATES,
  SHOT_PRIORITY,
  type PlannerOf,
  type PlannerRecord,
  type ReqCategory,
  type ReqStatus,
  type ShotPriority,
} from './types'

/**
 * The last-mile event details (W31 accommodation, W32 legal/admin requirements,
 * W33 shot list, W34 music cues, W35 weather contingency). Everything renders
 * from IndexedDB via useOwned() and writes through newEnvelope/patch/softDelete;
 * no network is touched. Two of these cards deliberately generate nothing — the
 * requirements list ships empty because TemuDua does not know what KUA/Dukcapil
 * ask of you, and the contingency card forecasts no weather.
 */
export function ExtrasTab({ me }: { me: string }) {
  const { t } = useI18n()
  const rows = useOwned<PlannerRecord>('wedding', me)
  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is PlannerOf<K> => r.kind === kind)

  const events = of('wed_event')
  const eventLabel = (id?: string) => {
    if (!id) return t('wedding2.log.allEvents')
    const e = events.find((x) => x.id === id)
    return e ? e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const) : t('wedding2.log.eventGone')
  }

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.extra.intro')}</p>
      <LodgingCard me={me} places={of('wed_lodging')} events={events} eventLabel={eventLabel} />
      <RequirementsCard me={me} reqs={of('wed_req')} />
      <ShotCard me={me} shots={of('wed_shot')} events={events} eventLabel={eventLabel} />
      <CueCard me={me} cues={of('wed_cue')} events={events} eventLabel={eventLabel} />
      <ContingencyCard me={me} items={of('wed_contingency')} events={events} eventLabel={eventLabel} />
    </div>
  )
}

// -- W31 accommodation -----------------------------------------------------
function LodgingCard({
  me,
  places,
  events,
  eventLabel,
}: {
  me: string
  places: PlannerOf<'wed_lodging'>[]
  events: PlannerOf<'wed_event'>[]
  eventLabel: (id?: string) => string
}) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const summary = lodgingSummary(places)
  const status = (id: string) => summary.places.find((p) => p.id === id)!

  return (
    <Card
      title={t('wedding2.lodg.title')}
      icon="home"
      hint={t('wedding2.lodg.hint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('wedding2.lodg.add')}
        </button>
      }
    >
      {places.length === 0 ? (
        <EmptyState icon="home" title={t('wedding2.lodg.empty')} hint={t('wedding2.lodg.emptyHint')} />
      ) : (
        <>
          <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
            <span className="chip">{t('wedding2.lodg.beds', { n: summary.totalBeds })}</span>
            <span className="chip chip--blue">{t('wedding2.lodg.need', { n: summary.totalNeed })}</span>
            {summary.shortfall > 0 && (
              <span className="chip chip--yellow">{t('wedding2.lodg.short', { n: summary.shortfall })}</span>
            )}
          </div>
          <ul className="list">
            {places
              .slice()
              .sort((a, b) => a.label.localeCompare(b.label))
              .map((p) => {
                const st = status(p.id)
                return (
                  <li key={p.id} className="list__item">
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{p.label}</strong>
                      <span className="card__hint">
                        {eventLabel(p.eventId)}
                        {p.address ? ` · ${p.address}` : ''}
                        {p.checkIn ? ` · ${t('wedding2.lodg.checkIn', { date: p.checkIn })}` : ''}
                      </span>
                      {p.note && <span className="card__hint">{p.note}</span>}
                    </span>
                    {st.level !== 'unknown' && (
                      <span className={st.level === 'short' ? 'chip chip--yellow' : 'chip chip--mint'}>
                        {t('wedding2.lodg.occ', { cap: st.capacity, need: st.needPax })}
                      </span>
                    )}
                    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', p.id, me)}>
                      <Icon name="close" size={16} label={t('common.deleteX', { name: p.label })} />
                    </button>
                  </li>
                )
              })}
          </ul>
          <p className="disclaimer">{t('wedding2.lodg.caveat')}</p>
        </>
      )}
      <LodgingSheet open={open} onClose={() => setOpen(false)} me={me} events={events} />
    </Card>
  )
}

function LodgingSheet({
  open,
  onClose,
  me,
  events,
}: {
  open: boolean
  onClose: () => void
  me: string
  events: PlannerOf<'wed_event'>[]
}) {
  const { t } = useI18n()
  const [label, setLabel] = useState('')
  const [eventId, setEventId] = useState('')
  const [capacity, setCapacity] = useState('')
  const [needPax, setNeedPax] = useState('')
  const [address, setAddress] = useState('')
  const [checkIn, setCheckIn] = useState('')
  const [checkOut, setCheckOut] = useState('')

  useEffect(() => {
    if (open) {
      setLabel('')
      setCapacity('')
      setNeedPax('')
      setAddress('')
      setCheckIn('')
      setCheckOut('')
    }
  }, [open])

  async function save() {
    if (!label.trim()) return
    await db.wedding.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'wed_lodging',
      label: label.trim(),
      ...(eventId ? { eventId } : {}),
      ...(capacity ? { capacity: Math.max(0, Number(capacity) || 0) } : {}),
      ...(needPax ? { needPax: Math.max(0, Number(needPax) || 0) } : {}),
      ...(address.trim() ? { address: address.trim() } : {}),
      ...(checkIn ? { checkIn } : {}),
      ...(checkOut ? { checkOut } : {}),
    } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('wedding2.lodg.add')}>
      <div className="stack">
        <Field label={t('wedding2.lodg.fLabel')} hint={t('wedding2.lodg.fLabelHint')}>
          {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.lodg.fEvent')} hint={t('common.optional')}>
          {(p) => (
            <select {...p} value={eventId} onChange={(e) => setEventId(e.target.value)}>
              <option value="">{t('wedding2.log.allEvents')}</option>
              {events.map((e) => (
                <option key={e.id} value={e.id}>
                  {e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('wedding2.lodg.fCapacity')} hint={t('common.optional')}>
          {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={capacity} onChange={(e) => setCapacity(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.lodg.fNeed')} hint={t('common.optional')}>
          {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={needPax} onChange={(e) => setNeedPax(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.lodg.fAddress')} hint={t('common.optional')}>
          {(p) => <input {...p} type="text" value={address} onChange={(e) => setAddress(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.lodg.fCheckIn')} hint={t('common.optional')}>
          {(p) => <input {...p} type="date" value={checkIn} onChange={(e) => setCheckIn(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.lodg.fCheckOut')} hint={t('common.optional')}>
          {(p) => <input {...p} type="date" value={checkOut} onChange={(e) => setCheckOut(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!label.trim()}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}

// -- W32 legal / admin requirements (STRUCTURE ONLY) -----------------------
const REQ_CHIP: Record<ReqStatus, string> = {
  belum: 'chip',
  proses: 'chip chip--yellow',
  beres: 'chip chip--mint',
}

function RequirementsCard({ me, reqs }: { me: string; reqs: PlannerOf<'wed_req'>[] }) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const progress = requirementProgress(reqs)

  return (
    <Card
      title={t('wedding2.req.title')}
      icon="checkin"
      hint={t('wedding2.req.hint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('wedding2.req.add')}
        </button>
      }
    >
      <p className="banner">
        <Icon name="info" size={16} /> {t('wedding2.req.disclaimer')}
      </p>
      {reqs.length === 0 ? (
        <EmptyState icon="checkin" title={t('wedding2.req.empty')} hint={t('wedding2.req.emptyHint')} />
      ) : (
        <>
          <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
            <span className="chip chip--blue">{t('wedding2.req.done', { done: progress.doneCount, total: progress.total })}</span>
          </div>
          {REQ_CATEGORIES.map((cat) => {
            const list = reqs.filter((r) => r.category === cat).sort((a, b) => a.label.localeCompare(b.label))
            if (list.length === 0) return null
            return (
              <div key={cat} className="stack stack--tight" style={{ marginBottom: 'var(--space-3)' }}>
                <strong style={{ fontSize: 13 }}>{t(`wedding2.req.cat.${cat}` as const)}</strong>
                <ul className="list">
                  {list.map((r) => (
                    <li key={r.id} className="list__item">
                      <span className="grow stack stack--tight">
                        <strong style={{ fontSize: 14 }}>{r.label}</strong>
                        {(r.where || r.due || r.note) && (
                          <span className="card__hint">
                            {r.due ? t('wedding2.req.due', { date: r.due }) : ''}
                            {r.where ? `${r.due ? ' · ' : ''}${t('wedding2.req.at', { where: r.where })}` : ''}
                            {r.note ? `${r.due || r.where ? ' · ' : ''}${r.note}` : ''}
                          </span>
                        )}
                      </span>
                      <label>
                        <span className="visually-hidden">{`${r.label} — ${t('wedding2.req.fStatus')}`}</span>
                        <select
                          value={r.status}
                          style={{ minHeight: 36, fontSize: 13 }}
                          className={REQ_CHIP[r.status]}
                          onChange={(ev) => patch('wedding', r.id, { status: ev.target.value })}
                        >
                          {REQ_STATES.map((s) => (
                            <option key={s} value={s}>
                              {t(`wedding2.req.st.${s}` as const)}
                            </option>
                          ))}
                        </select>
                      </label>
                      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', r.id, me)}>
                        <Icon name="close" size={16} label={t('common.deleteX', { name: r.label })} />
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )
          })}
        </>
      )}
      <RequirementSheet open={open} onClose={() => setOpen(false)} me={me} />
    </Card>
  )
}

function RequirementSheet({ open, onClose, me }: { open: boolean; onClose: () => void; me: string }) {
  const { t } = useI18n()
  const [label, setLabel] = useState('')
  const [category, setCategory] = useState<ReqCategory>('kua')
  const [status, setStatus] = useState<ReqStatus>('belum')
  const [where, setWhere] = useState('')
  const [due, setDue] = useState('')

  useEffect(() => {
    if (open) {
      setLabel('')
      setStatus('belum')
      setWhere('')
      setDue('')
    }
  }, [open])

  async function save() {
    if (!label.trim()) return
    await db.wedding.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'wed_req',
      label: label.trim(),
      category,
      status,
      ...(where.trim() ? { where: where.trim() } : {}),
      ...(due ? { due } : {}),
    } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('wedding2.req.add')}>
      <div className="stack">
        <p className="card__hint">{t('wedding2.req.disclaimer')}</p>
        <Field label={t('wedding2.req.fLabel')} hint={t('wedding2.req.fLabelHint')}>
          {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.req.fCategory')}>
          {(p) => (
            <select {...p} value={category} onChange={(e) => setCategory(e.target.value as ReqCategory)}>
              {REQ_CATEGORIES.map((c) => (
                <option key={c} value={c}>
                  {t(`wedding2.req.cat.${c}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('wedding2.req.fWhere')} hint={t('common.optional')}>
          {(p) => <input {...p} type="text" value={where} onChange={(e) => setWhere(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.req.fDue')} hint={t('wedding2.req.fDueHint')}>
          {(p) => <input {...p} type="date" value={due} onChange={(e) => setDue(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.req.fStatus')}>
          {(p) => (
            <select {...p} value={status} onChange={(e) => setStatus(e.target.value as ReqStatus)}>
              {REQ_STATES.map((s) => (
                <option key={s} value={s}>
                  {t(`wedding2.req.st.${s}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!label.trim()}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}

// -- W33 shot list ---------------------------------------------------------
function ShotCard({
  me,
  shots,
  events,
  eventLabel,
}: {
  me: string
  shots: PlannerOf<'wed_shot'>[]
  events: PlannerOf<'wed_event'>[]
  eventLabel: (id?: string) => string
}) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const progress = shotProgress(shots)

  return (
    <Card
      title={t('wedding2.shot.title')}
      icon="memories"
      hint={t('wedding2.shot.hint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('wedding2.shot.add')}
        </button>
      }
    >
      {shots.length === 0 ? (
        <EmptyState icon="memories" title={t('wedding2.shot.empty')} hint={t('wedding2.shot.emptyHint')} />
      ) : (
        <>
          <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
            <span className="chip chip--blue">{t('wedding2.shot.captured', { done: progress.doneCount, total: progress.total })}</span>
            {progress.mustOutstanding > 0 && (
              <span className="chip chip--yellow">{t('wedding2.shot.mustLeft', { n: progress.mustOutstanding })}</span>
            )}
          </div>
          {SHOT_PRIORITY.map((prio) => {
            const list = shots.filter((s) => s.priority === prio).sort((a, b) => a.desc.localeCompare(b.desc))
            if (list.length === 0) return null
            return (
              <div key={prio} className="stack stack--tight" style={{ marginBottom: 'var(--space-3)' }}>
                <strong style={{ fontSize: 13 }}>{t(`wedding2.shot.prio.${prio}` as const)}</strong>
                <ul className="list">
                  {list.map((s) => (
                    <li key={s.id} className="list__item">
                      <button
                        className="btn btn--ghost btn--sm"
                        aria-pressed={!!s.done}
                        aria-label={t('wedding2.shot.toggle', { name: s.desc })}
                        onClick={() => patch('wedding', s.id, { done: !s.done })}
                      >
                        <Icon name="check" size={16} />
                      </button>
                      <span className="grow stack stack--tight">
                        <strong style={{ fontSize: 14, opacity: s.done ? 0.55 : 1 }}>{s.desc}</strong>
                        <span className="card__hint">
                          {eventLabel(s.eventId)}
                          {s.subjects ? ` · ${t('wedding2.shot.with', { who: s.subjects })}` : ''}
                          {s.note ? ` · ${s.note}` : ''}
                        </span>
                      </span>
                      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', s.id, me)}>
                        <Icon name="close" size={16} label={t('common.deleteX', { name: s.desc })} />
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )
          })}
        </>
      )}
      <ShotSheet open={open} onClose={() => setOpen(false)} me={me} events={events} />
    </Card>
  )
}

