// -- W34 music / moment cues ----------------------------------------------
function CueCard({
  me,
  cues,
  events,
  eventLabel,
}: {
  me: string
  cues: PlannerOf<'wed_cue'>[]
  events: PlannerOf<'wed_event'>[]
  eventLabel: (id?: string) => string
}) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const progress = cueProgress(cues)

  return (
    <Card
      title={t('wedding2.cue.title')}
      icon="calendar"
      hint={t('wedding2.cue.hint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('wedding2.cue.add')}
        </button>
      }
    >
      {cues.length === 0 ? (
        <EmptyState icon="calendar" title={t('wedding2.cue.empty')} hint={t('wedding2.cue.emptyHint')} />
      ) : (
        <>
          <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
            <span className="chip chip--blue">{t('wedding2.cue.picked', { n: progress.withTrack, total: progress.total })}</span>
            {progress.missingTrack > 0 && (
              <span className="chip chip--yellow">{t('wedding2.cue.missing', { n: progress.missingTrack })}</span>
            )}
          </div>
          <ul className="list">
            {cues
              .slice()
              .sort((a, b) => (a.time ?? '~').localeCompare(b.time ?? '~') || a.moment.localeCompare(b.moment))
              .map((c) => (
                <li key={c.id} className="list__item">
                  {c.time && <span className="chip">{c.time}</span>}
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{c.moment}</strong>
                    <span className="card__hint">
                      {eventLabel(c.eventId)}
                      {c.cueBy ? ` · ${t('wedding2.cue.by', { who: c.cueBy })}` : ''}
                      {c.note ? ` · ${c.note}` : ''}
                    </span>
                  </span>
                  <span className={c.track?.trim() ? 'chip chip--mint' : 'chip chip--yellow'}>
                    {c.track?.trim() ? c.track : t('wedding2.cue.noTrack')}
                  </span>
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', c.id, me)}>
                    <Icon name="close" size={16} label={t('common.deleteX', { name: c.moment })} />
                  </button>
                </li>
              ))}
          </ul>
        </>
      )}
      <CueSheet open={open} onClose={() => setOpen(false)} me={me} events={events} />
    </Card>
  )
}

function CueSheet({
  open,
  onClose,
  me,
  events,
}: {
  open: boolean
  onClose: () => void
  me: string
  events: PlannerOf<'wed_event'>[]
}) {
  const { t } = useI18n()
  const [moment, setMoment] = useState('')
  const [eventId, setEventId] = useState('')
  const [track, setTrack] = useState('')
  const [cueBy, setCueBy] = useState('')
  const [time, setTime] = useState('')

  useEffect(() => {
    if (open) {
      setMoment('')
      setTrack('')
      setCueBy('')
      setTime('')
    }
  }, [open])

  async function save() {
    if (!moment.trim()) return
    await db.wedding.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'wed_cue',
      moment: moment.trim(),
      ...(eventId ? { eventId } : {}),
      ...(track.trim() ? { track: track.trim() } : {}),
      ...(cueBy.trim() ? { cueBy: cueBy.trim() } : {}),
      ...(time ? { time } : {}),
    } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('wedding2.cue.add')}>
      <div className="stack">
        <Field label={t('wedding2.cue.fMoment')} hint={t('wedding2.cue.fMomentHint')}>
          {(p) => <input {...p} type="text" value={moment} onChange={(e) => setMoment(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.cue.fEvent')} hint={t('common.optional')}>
          {(p) => (
            <select {...p} value={eventId} onChange={(e) => setEventId(e.target.value)}>
              <option value="">{t('wedding2.log.allEvents')}</option>
              {events.map((e) => (
                <option key={e.id} value={e.id}>
                  {e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('wedding2.cue.fTrack')} hint={t('wedding2.cue.fTrackHint')}>
          {(p) => <input {...p} type="text" value={track} onChange={(e) => setTrack(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.cue.fCueBy')} hint={t('wedding2.cue.fCueByHint')}>
          {(p) => <input {...p} type="text" value={cueBy} onChange={(e) => setCueBy(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.cue.fTime')} hint={t('common.optional')}>
          {(p) => <input {...p} type="time" value={time} onChange={(e) => setTime(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!moment.trim()}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}

// -- W35 weather / outdoor contingency ------------------------------------
function ContingencyCard({
  me,
  items,
  events,
  eventLabel,
}: {
  me: string
  items: PlannerOf<'wed_contingency'>[]
  events: PlannerOf<'wed_event'>[]
  eventLabel: (id?: string) => string
}) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const summary = contingencySummary(items)

  return (
    <Card
      title={t('wedding2.cont.title')}
      icon="shield"
      hint={t('wedding2.cont.hint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('wedding2.cont.add')}
        </button>
      }
    >
      <p className="banner">
        <Icon name="info" size={16} /> {t('wedding2.cont.noForecast')}
      </p>
      {items.length === 0 ? (
        <EmptyState icon="shield" title={t('wedding2.cont.empty')} hint={t('wedding2.cont.emptyHint')} />
      ) : (
        <>
          <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
            <span className="chip chip--blue">{t('wedding2.cont.planned', { n: summary.planned, total: summary.total })}</span>
            <span className="chip chip--mint">{t('wedding2.cont.ready', { n: summary.ready })}</span>
            {summary.gapIds.length > 0 && (
              <span className="chip chip--yellow">{t('wedding2.cont.gaps', { n: summary.gapIds.length })}</span>
            )}
          </div>
          <ul className="list">
            {items
              .slice()
              .sort((a, b) => a.label.localeCompare(b.label))
              .map((c) => {
                const hasPlan = !!c.plan?.trim()
                return (
                  <li key={c.id} className="list__item">
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{c.label}</strong>
                      <span className="card__hint">
                        {eventLabel(c.eventId)}
                        {c.risk ? ` · ${t('wedding2.cont.risk', { risk: c.risk })}` : ''}
                      </span>
                      <span className="card__hint">{hasPlan ? c.plan : t('wedding2.cont.noPlan')}</span>
                      {c.note && <span className="card__hint">{c.note}</span>}
                    </span>
                    <button
                      className="btn btn--ghost btn--sm"
                      aria-pressed={!!c.ready}
                      aria-label={t('wedding2.cont.toggle', { name: c.label })}
                      disabled={!hasPlan}
                      onClick={() => patch('wedding', c.id, { ready: !c.ready })}
                    >
                      <span className={c.ready ? 'chip chip--mint' : 'chip'}>
                        {c.ready ? t('wedding2.cont.arranged') : t('wedding2.cont.notArranged')}
                      </span>
                    </button>
                    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', c.id, me)}>
                      <Icon name="close" size={16} label={t('common.deleteX', { name: c.label })} />
                    </button>
                  </li>
                )
              })}
          </ul>
        </>
      )}
      <ContingencySheet open={open} onClose={() => setOpen(false)} me={me} events={events} />
    </Card>
  )
}

function ContingencySheet({
  open,
  onClose,
  me,
  events,
}: {
  open: boolean
  onClose: () => void
  me: string
  events: PlannerOf<'wed_event'>[]
}) {
  const { t } = useI18n()
  const [label, setLabel] = useState('')
  const [eventId, setEventId] = useState('')
  const [risk, setRisk] = useState('')
  const [plan, setPlan] = useState('')

  useEffect(() => {
    if (open) {
      setLabel('')
      setRisk('')
      setPlan('')
    }
  }, [open])

  async function save() {
    if (!label.trim()) return
    await db.wedding.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'wed_contingency',
      label: label.trim(),
      ...(eventId ? { eventId } : {}),
      ...(risk.trim() ? { risk: risk.trim() } : {}),
      ...(plan.trim() ? { plan: plan.trim() } : {}),
    } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('wedding2.cont.add')}>
      <div className="stack">
        <Field label={t('wedding2.cont.fLabel')} hint={t('wedding2.cont.fLabelHint')}>
          {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.cont.fEvent')} hint={t('common.optional')}>
          {(p) => (
            <select {...p} value={eventId} onChange={(e) => setEventId(e.target.value)}>
              <option value="">{t('wedding2.log.allEvents')}</option>
              {events.map((e) => (
                <option key={e.id} value={e.id}>
                  {e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('wedding2.cont.fRisk')} hint={t('wedding2.cont.fRiskHint')}>
          {(p) => <input {...p} type="text" value={risk} onChange={(e) => setRisk(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.cont.fPlan')} hint={t('wedding2.cont.fPlanHint')}>
          {(p) => <textarea {...p} value={plan} onChange={(e) => setPlan(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!label.trim()}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
