import { addDays, format, parseISO } from 'date-fns'

/**
 * Event dependency rules (WED-07 / W02).
 *
 * An Indonesian wedding is a chain, not a single day: siraman sits the day
 * before the akad, ngunduh mantu a week or two after it, and when the akad moves
 * because the KUA gave you a different slot, all of them move with it.
 *
 * The rule here is that a dependent event's date is **derived, never stored**.
 * `resolveEventDates()` walks the chain on every read, so there is no cascade
 * write to get wrong, no partially-updated chain if the tab closes halfway, and
 * no stale date left behind when the parent moves. The store only ever holds the
 * dates a human actually typed.
 *
 * Pure module: structural inputs, no database, no user-facing copy — the UI
 * turns a `DepProblem` key into a sentence.
 */

export interface DepEventLike {
  id: string
  date?: string
  /** Id of the event this one hangs off. Undefined means "I set my own date". */
  dependsOn?: string
  /** Days from the parent's date. Negative is before it. */
  offsetDays?: number
}

/** Where a resolved date came from. `none` means there is nothing to show. */
export type DateSource = 'set' | 'derived' | 'none'

/** Why a dependent event has no date. Message keys, resolved by the component. */
export type DepProblem = 'cycle' | 'parentMissing' | 'parentUndated'

export interface ResolvedDate {
  date?: string
  source: DateSource
  problem?: DepProblem
}

const shift = (iso: string, days: number): string =>
  format(addDays(parseISO(iso), days), 'yyyy-MM-dd')

/** An offset that is not a finite number counts as 0 rather than poisoning the chain. */
const offsetOf = (e: DepEventLike): number =>
  Number.isFinite(e.offsetDays) ? Math.trunc(e.offsetDays as number) : 0

/**
 * The date every event actually falls on, following `dependsOn` chains of any
 * depth. A cycle resolves to no date rather than throwing: the couple typed it,
 * the screen has to keep rendering, and the UI already refuses to create one.
 */
export function resolveEventDates(events: readonly DepEventLike[]): Map<string, ResolvedDate> {
  const byId = new Map(events.map((e) => [e.id, e]))
  const done = new Map<string, ResolvedDate>()

  const visit = (id: string, ancestors: ReadonlySet<string>): ResolvedDate => {
    // Reached on the way up from a child: this node is its own ancestor.
    // Deliberately not cached under `ancestors` — the memo below stores the same
    // verdict for the node anyway, and a node inside a cycle is always in one.
    if (ancestors.has(id)) return { source: 'none', problem: 'cycle' }
    const cached = done.get(id)
    if (cached) return cached

    // Only ever called with ids taken from `events` or guarded by `byId.has`.
    const e = byId.get(id)!
    const res = ((): ResolvedDate => {
      if (!e.dependsOn) return e.date ? { date: e.date, source: 'set' } : { source: 'none' }
      if (!byId.has(e.dependsOn)) return { source: 'none', problem: 'parentMissing' }
      const parent = visit(e.dependsOn, new Set(ancestors).add(id))
      if (!parent.date) return { source: 'none', problem: parent.problem ?? 'parentUndated' }
      return { date: shift(parent.date, offsetOf(e)), source: 'derived' }
    })()

    done.set(id, res)
    return res
  }

  for (const e of events) visit(e.id, new Set())
  return done
}

/**
 * The same events with derived dates filled in, so every downstream reader
 * (`anchorDate`, the checklist, readiness, the guest table) sees the date the
 * event really falls on without knowing dependencies exist.
 */
export function withResolvedDates<T extends DepEventLike>(events: readonly T[]): T[] {
  const dates = resolveEventDates(events)
  // A stored `date` on a dependent event is ignored on purpose: the chain is the
  // single source of truth, so an old typed-in date must not resurface.
  return events.map((e) => (e.dependsOn ? ({ ...e, date: dates.get(e.id)?.date } as T) : e))
}

/** Every event that moves when `rootId` moves, nearest first. Excludes the root. */
export function dependents(events: readonly DepEventLike[], rootId: string): string[] {
  const out: string[] = []
  const seen = new Set([rootId])
  let frontier = [rootId]
  while (frontier.length > 0) {
    const next = events
      .filter((e) => e.dependsOn !== undefined && frontier.includes(e.dependsOn) && !seen.has(e.id))
      .map((e) => e.id)
    for (const id of next) seen.add(id)
    out.push(...next)
    frontier = next
  }
  return out
}

/**
 * Whether `childId` may hang off `parentId`. Guards the two ways a user can
 * break the graph from the picker: pointing an event at itself, or at something
 * already downstream of it.
 */
export function canDependOn(
  events: readonly DepEventLike[],
  childId: string,
  parentId: string,
): boolean {
  if (childId === parentId) return false
  if (!events.some((e) => e.id === parentId)) return false
  return !dependents(events, childId).includes(parentId)
}

export interface ShiftRow {
  id: string
  from?: string
  to?: string
}

/**
 * What actually moves if `rootId`'s date becomes `newDate` — the root plus every
 * event that follows it, with both dates, so the screen can say "3 acara ikut
 * pindah" before anybody taps save.
 */
export function shiftPreview(
  events: readonly DepEventLike[],
  rootId: string,
  newDate: string | undefined,
): ShiftRow[] {
  const before = resolveEventDates(events)
  const after = resolveEventDates(
    events.map((e) => (e.id === rootId ? { ...e, date: newDate, dependsOn: undefined } : e)),
  )
  return events
    .map((e) => ({ id: e.id, from: before.get(e.id)?.date, to: after.get(e.id)?.date }))
    .filter((r) => r.from !== r.to)
}
