/**
 * Minimal QR encoder (W19) — byte mode, error-correction level L, single block,
 * versions 1–4 (up to 78 bytes). Zero dependencies, so a check-in QR renders in
 * airplane mode with no server and no paid library (Rp0 forever).
 *
 * Scope is deliberately narrow: our payload is one short check-in token, and
 * level-L versions 1–4 are all *single* error-correction blocks, which drops the
 * interleaving step that causes most QR bugs. Anything longer than v4 throws
 * rather than silently producing an unscannable code.
 *
 * The Reed–Solomon core (rsMultiply / computeDivisor / computeRemainder) is the
 * well-known Nayuki reference algorithm; qr.test.ts pins it with the
 * codeword-divisibility property and the format-info spec vector.
 *
 * ponytail: byte mode + level L + v1–v4 only. Add more versions/levels only if a
 * real payload outgrows 78 bytes — a check-in token never will.
 */

interface VerInfo {
  /** Total data codewords for level L (single block). */
  data: number
  /** Error-correction codewords. */
  ecc: number
  /** Alignment-pattern centre coordinates (includes 6; finder corners skipped). */
  align: number[]
}

// Level-L, single-block figures straight from ISO/IEC 18004 Table 9 / Annex E.
const VERSIONS: readonly VerInfo[] = [
  { data: 19, ecc: 7, align: [] }, // v1
  { data: 34, ecc: 10, align: [6, 18] }, // v2
  { data: 55, ecc: 15, align: [6, 22] }, // v3
  { data: 80, ecc: 20, align: [6, 26] }, // v4
]

/** GF(256) multiply, primitive polynomial 0x11d. */
function rsMultiply(x: number, y: number): number {
  let z = 0
  for (let i = 7; i >= 0; i--) {
    z = (z << 1) ^ ((z >>> 7) * 0x11d)
    z ^= ((y >>> i) & 1) * x
  }
  return z & 0xff
}

/** Generator-polynomial coefficients (highest power first, leading 1 dropped). */
export function computeDivisor(degree: number): number[] {
  const result = new Array<number>(degree).fill(0)
  result[degree - 1] = 1
  let root = 1
  for (let i = 0; i < degree; i++) {
    for (let j = 0; j < result.length; j++) {
      result[j] = rsMultiply(result[j]!, root)
      if (j + 1 < result.length) result[j]! ^= result[j + 1]!
    }
    root = rsMultiply(root, 0x02)
  }
  return result
}

/** Reed–Solomon remainder = the ECC codewords for `data`. */
export function computeRemainder(data: readonly number[], divisor: readonly number[]): number[] {
  const result = divisor.map(() => 0)
  for (const b of data) {
    const factor = b ^ result.shift()!
    result.push(0)
    divisor.forEach((coef, i) => (result[i]! ^= rsMultiply(coef, factor)))
  }
  return result
}

/** 15-bit BCH format information for EC level L (0b01) and the given mask. */
export function formatBits(mask: number): number {
  const data = (0b01 << 3) | mask // EC level L
  let rem = data
  for (let i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537)
  return ((data << 10) | rem) ^ 0x5412
}

function pickVersion(len: number): number {
  for (let v = 0; v < VERSIONS.length; v++) {
    // 4 mode bits + 8 count bits + 8·len, rounded up to whole codewords.
    const need = Math.ceil((4 + 8 + 8 * len) / 8)
    if (need <= VERSIONS[v]!.data) return v
  }
  throw new Error('QR: token terlalu panjang untuk versi 1–4')
}

/** Data codewords: mode + count + payload, terminator, pad. */
function dataCodewords(bytes: Uint8Array, capacity: number): number[] {
  const bits: number[] = []
  const push = (val: number, n: number) => {
    for (let i = n - 1; i >= 0; i--) bits.push((val >>> i) & 1)
  }
  push(0b0100, 4) // byte mode
  push(bytes.length, 8) // count indicator (v1–9)
  for (const b of bytes) push(b, 8)
  const capBits = capacity * 8
  push(0, Math.min(4, capBits - bits.length)) // terminator
  while (bits.length % 8 !== 0) bits.push(0)

  const cw: number[] = []
  for (let i = 0; i < bits.length; i += 8) {
    let byte = 0
    for (let j = 0; j < 8; j++) byte = (byte << 1) | bits[i + j]!
    cw.push(byte)
  }
  for (let pad = 0xec; cw.length < capacity; pad ^= 0xec ^ 0x11) cw.push(pad)
  return cw
}

// Flat row-major grids. Uint8Array indexing is exempt from noUncheckedIndexedAccess.
type Grid = Uint8Array

function drawFinder(m: Grid, fn: Grid, size: number, r: number, c: number): void {
  for (let dr = -1; dr <= 7; dr++) {
    for (let dc = -1; dc <= 7; dc++) {
      const rr = r + dr
      const cc = c + dc
      if (rr < 0 || rr >= size || cc < 0 || cc >= size) continue
      fn[rr * size + cc] = 1
      const d = Math.max(Math.abs(dr - 3), Math.abs(dc - 3))
      m[rr * size + cc] = d !== 2 && d <= 3 ? 1 : 0
    }
  }
}

function drawAlignment(m: Grid, fn: Grid, size: number, r: number, c: number): void {
  for (let dr = -2; dr <= 2; dr++) {
    for (let dc = -2; dc <= 2; dc++) {
      fn[(r + dr) * size + (c + dc)] = 1
      m[(r + dr) * size + (c + dc)] = Math.max(Math.abs(dr), Math.abs(dc)) !== 1 ? 1 : 0
    }
  }
}

function functionPatterns(m: Grid, fn: Grid, size: number, versionIdx: number): void {
  drawFinder(m, fn, size, 0, 0)
  drawFinder(m, fn, size, 0, size - 7)
  drawFinder(m, fn, size, size - 7, 0)

  // Timing patterns.
  for (let i = 8; i < size - 8; i++) {
    const v = i % 2 === 0 ? 1 : 0
    m[6 * size + i] = v
    m[i * size + 6] = v
    fn[6 * size + i] = 1
    fn[i * size + 6] = 1
  }

  // Alignment patterns at every coordinate pair, minus the three finder corners.
  const pos = VERSIONS[versionIdx]!.align
  for (const r of pos) {
    for (const c of pos) {
      const corner =
        (r === 6 && c === 6) || (r === 6 && c === size - 7) || (r === size - 7 && c === 6)
      if (!corner) drawAlignment(m, fn, size, r, c)
    }
  }

  // Reserve the format-info strips; dark module.
  for (let i = 0; i < 9; i++) {
    fn[8 * size + i] = 1
    fn[i * size + 8] = 1
    if (i < 8) {
      fn[8 * size + (size - 1 - i)] = 1
      fn[(size - 1 - i) * size + 8] = 1
    }
  }
  m[(size - 8) * size + 8] = 1
  fn[(size - 8) * size + 8] = 1
}

function placeFormat(m: Grid, size: number, mask: number): void {
  const bits = formatBits(mask)
  const bit = (i: number) => (bits >>> i) & 1
  for (let i = 0; i <= 5; i++) m[8 * size + i] = bit(i)
  m[8 * size + 7] = bit(6)
  m[8 * size + 8] = bit(7)
  m[7 * size + 8] = bit(8)
  for (let i = 9; i < 15; i++) m[(14 - i) * size + 8] = bit(i)
  for (let i = 0; i < 8; i++) m[(size - 1 - i) * size + 8] = bit(i)
  for (let i = 8; i < 15; i++) m[8 * size + (size - 15 + i)] = bit(i)
}

function maskFn(mask: number, r: number, c: number): boolean {
  switch (mask) {
    case 0: return (r + c) % 2 === 0
    case 1: return r % 2 === 0
    case 2: return c % 3 === 0
    case 3: return (r + c) % 3 === 0
    case 4: return (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0
    case 5: return ((r * c) % 2) + ((r * c) % 3) === 0
    case 6: return (((r * c) % 2) + ((r * c) % 3)) % 2 === 0
    default: return (((r + c) % 2) + ((r * c) % 3)) % 2 === 0
  }
}

function placeCodewords(m: Grid, fn: Grid, size: number, all: number[]): void {
  let bitIdx = 0
  const total = all.length * 8
  for (let right = size - 1; right >= 1; right -= 2) {
    const col = right === 6 ? right - 1 : right // skip timing column 6
    for (let v = 0; v < size; v++) {
      const upward = ((size - 1 - right) & 2) === 0
      const row = upward ? size - 1 - v : v
      for (const c of [col, col - 1]) {
        if (fn[row * size + c]) continue
        if (bitIdx < total) {
          const byte = all[bitIdx >> 3] ?? 0
          m[row * size + c] = (byte >>> (7 - (bitIdx & 7))) & 1
        }
        bitIdx++
      }
    }
  }
}

function penalty(m: Grid, size: number): number {
  let score = 0
  const at = (r: number, c: number) => m[r * size + c]
  // Rule 1: runs of 5+ same-colour in rows and columns.
  for (let a = 0; a < size; a++) {
    for (const rowMode of [true, false]) {
      let run = 1
      for (let b = 1; b < size; b++) {
        const cur = rowMode ? at(a, b) : at(b, a)
        const prev = rowMode ? at(a, b - 1) : at(b - 1, a)
        if (cur === prev) {
          run++
          if (run === 5) score += 3
          else if (run > 5) score++
        } else run = 1
      }
    }
  }
  // Rule 2: 2×2 blocks of one colour.
  for (let r = 0; r < size - 1; r++) {
    for (let c = 0; c < size - 1; c++) {
      const v = at(r, c)
      if (v === at(r, c + 1) && v === at(r + 1, c) && v === at(r + 1, c + 1)) score += 3
    }
  }
  // Rule 4: overall dark proportion.
  let dark = 0
  for (let i = 0; i < size * size; i++) if (m[i]) dark++
  const pct = (dark * 100) / (size * size)
  score += Math.floor(Math.abs(pct - 50) / 5) * 10
  return score
}

/**
 * Encodes `text` (≤78 bytes) into a QR module matrix. `true` = dark module.
 * Picks the smallest fitting version and the lowest-penalty mask.
 */
export function qrMatrix(text: string): boolean[][] {
  const bytes = new TextEncoder().encode(text)
  const versionIdx = pickVersion(bytes.length)
  const info = VERSIONS[versionIdx]!
  const data = dataCodewords(bytes, info.data)
  const ecc = computeRemainder(data, computeDivisor(info.ecc))
  const all = data.concat(ecc)

  const size = (versionIdx + 1) * 4 + 17
  let best: Grid | null = null
  let bestScore = Infinity
  for (let mask = 0; mask < 8; mask++) {
    const m = new Uint8Array(size * size)
    const fn = new Uint8Array(size * size)
    functionPatterns(m, fn, size, versionIdx)
    placeCodewords(m, fn, size, all)
    for (let r = 0; r < size; r++)
      for (let c = 0; c < size; c++) {
        const i = r * size + c
        if (!fn[i] && maskFn(mask, r, c)) m[i] = m[i]! ^ 1
      }
    placeFormat(m, size, mask)
    const s = penalty(m, size)
    if (s < bestScore) {
      bestScore = s
      best = m
    }
  }

  const out: boolean[][] = []
  for (let r = 0; r < size; r++) {
    const row: boolean[] = []
    for (let c = 0; c < size; c++) row.push(best![r * size + c] === 1)
    out.push(row)
  }
  return out
}
