/**
 * Transport & logistics logic (W30).
 *
 * Seats against heads, per leg and in total. A shortfall is surfaced, never
 * solved for the couple — the app does not book anything. Structural in, numbers
 * and a level key out.
 */

export type LegLevel = 'unknown' | 'ok' | 'short'

export interface TransportLegLike {
  id: string
  capacity?: number
  needPax?: number
}

export interface LegStatus {
  id: string
  capacity: number
  needPax: number
  /** capacity − needPax. Negative once the leg is short. */
  spare: number
  level: LegLevel
}

export interface TransportSummary {
  legs: LegStatus[]
  totalCapacity: number
  totalNeed: number
  /** How many heads still have no seat across all legs. Zero when covered. */
  shortfall: number
}

/**
 * Per-leg and overall seat reconciliation (W30). A leg with neither a capacity
 * nor a need is `unknown` — half-filled data is not a shortage to alarm about.
 */
export function transportSummary(legs: readonly TransportLegLike[]): TransportSummary {
  let totalCapacity = 0
  let totalNeed = 0
  const rows = legs.map((l) => {
    const capacity = Math.max(0, l.capacity ?? 0)
    const needPax = Math.max(0, l.needPax ?? 0)
    totalCapacity += capacity
    totalNeed += needPax
    const spare = capacity - needPax
    const level: LegLevel =
      l.capacity === undefined && l.needPax === undefined ? 'unknown' : spare < 0 ? 'short' : 'ok'
    return { id: l.id, capacity, needPax, spare, level }
  })
  return { legs: rows, totalCapacity, totalNeed, shortfall: Math.max(0, totalNeed - totalCapacity) }
}
