/**
 * Legal / administrative requirements — STRUCTURE ONLY (W32).
 *
 * TemuDua does not know, and must never guess, what KUA or Dukcapil actually
 * require of any given couple: the papers, the fees, and the deadlines differ by
 * office, faith, and year, and inventing them would be a real-world-consequence
 * lie. So this file ships ZERO requirements and generates NO dates. It only
 * counts and groups the rows the couple typed in themselves.
 *
 * Structural counts in, keys/numbers out — no copy, no database.
 */

import { REQ_CATEGORIES, REQ_STATES, type ReqCategory, type ReqStatus } from './types'

export interface RequirementLike {
  category: ReqCategory
  status: ReqStatus
}

export interface RequirementProgress {
  total: number
  /** count per status (belum/proses/beres). */
  byStatus: Record<ReqStatus, number>
  /** count per institution bucket. */
  byCategory: Record<ReqCategory, number>
  doneCount: number
  /** Everything the couple listed is marked beres. False when the list is empty. */
  allDone: boolean
}

/**
 * Tally requirements by status and by institution (W32). Never adds a requirement
 * the couple did not enter; an empty list is `allDone: false`, because "nothing
 * listed" is not "nothing left to do" — the couple has simply not filled it in.
 */
export function requirementProgress(reqs: readonly RequirementLike[]): RequirementProgress {
  const byStatus = Object.fromEntries(REQ_STATES.map((s) => [s, 0])) as Record<ReqStatus, number>
  const byCategory = Object.fromEntries(REQ_CATEGORIES.map((c) => [c, 0])) as Record<ReqCategory, number>
  for (const r of reqs) {
    byStatus[r.status] += 1
    byCategory[r.category] += 1
  }
  const doneCount = byStatus.beres
  return {
    total: reqs.length,
    byStatus,
    byCategory,
    doneCount,
    allDone: reqs.length > 0 && doneCount === reqs.length,
  }
}
