import { addDays, format, parseISO } from 'date-fns'
import {
  CHECKLIST_MAX_OFFSET,
  CHECKLIST_MIN_OFFSET,
  buildChecklist,
  type CheckStatus,
  type ChecklistItem,
} from './checklist'
import type { EventScale, EventType, FamilyOwner, PartnerOwner } from './types'

/**
 * The countdown plan (W03/W04/W05) layered on top of `checklist.ts`.
 *
 * `buildChecklist()` already generates from the date and the events chosen. This
 * module adds the two things the brief asks for on top:
 *
 *  - **scale.** An intimate akad and a 700-guest resepsi are not the same job, so
 *    a few steps only exist at one scale. Nothing is invented for the couple:
 *    every extra step is a prompt to decide something, never a price, a vendor,
 *    or a rule someone else sets.
 *  - **buckets.** Countdown windows instead of one long scroll, so "what do we do
 *    this month" is answerable without reading 30 rows.
 *  - **ownership.** Two independent axes — which partner, and which family — with
 *    open-step counts. Counts describe who is carrying what. There is no score,
 *    no fairness verdict, and no comparison between the two people.
 *
 * Keys only; the screen calls `t()`.
 */

// --- scale ---------------------------------------------------------------

export interface ScaleTemplateItem {
  key: string
  offsetDays: number
  /** Scales this step exists at. Every extra step is gated; none is universal. */
  scales: readonly EventScale[]
  /** Only included when at least one of these events exists. Undefined = always. */
  needs?: readonly EventType[]
}

/**
 * Steps that only make sense at some sizes. Kept deliberately short: a generated
 * list earns trust by being the steps that apply, not by being long.
 */
export const SCALE_TEMPLATE = [
  { key: 'panitia', offsetDays: -180, scales: ['besar'] },
  { key: 'transportKeluarga', offsetDays: -100, scales: ['sedang', 'besar'] },
  { key: 'kabariLangsung', offsetDays: -50, scales: ['intim'] },
  { key: 'seating', offsetDays: -50, scales: ['besar'], needs: ['resepsi', 'ngunduh_mantu'] },
  { key: 'alurTamu', offsetDays: -28, scales: ['besar'], needs: ['resepsi'] },
  { key: 'siaranJauh', offsetDays: -20, scales: ['intim', 'sedang'] },
] as const satisfies readonly ScaleTemplateItem[]

export type ScaleKey = (typeof SCALE_TEMPLATE)[number]['key']
export type PlanKey = ChecklistItem['key'] | ScaleKey

// --- buckets -------------------------------------------------------------

/**
 * Countdown windows, farthest out first. `after` is not in the brief's list but
 * the template genuinely has post-wedding steps (returning hired items, final
 * settlements), and they have to live somewhere honest.
 */
export const BUCKETS = ['m12', 'm9', 'm6', 'm3', 'm1', 'w2', 'd7', 'd1', 'dday', 'after'] as const
export type Bucket = (typeof BUCKETS)[number]

/**
 * Lower edge of each window, in days before the wedding. A step lands in the
 * furthest-out window it still reaches, so `m9` holds 270–364 days and reads as
 * "9 bulan atau lebih, tapi belum setahun". The copy spells the range out rather
 * than pretending -300 is exactly twelve months.
 */
const BUCKET_FLOOR = [
  ['m12', 365],
  ['m9', 270],
  ['m6', 180],
  ['m3', 90],
  ['m1', 30],
  ['w2', 14],
  ['d7', 7],
  ['d1', 1],
] as const satisfies readonly (readonly [Bucket, number])[]

export function bucketOf(offsetDays: number): Bucket {
  if (offsetDays > 0) return 'after'
  const daysBefore = -offsetDays
  return BUCKET_FLOOR.find(([, floor]) => daysBefore >= floor)?.[0] ?? 'dday'
}

// --- plan ----------------------------------------------------------------

export interface PlanItem {
  key: PlanKey
  offsetDays: number
  dueDate?: string
  status: CheckStatus
  due: boolean
  overdue: boolean
  bucket: Bucket
  /** True for the steps that exist because of the chosen scale. */
  fromScale: boolean
  owner?: PartnerOwner
  family?: FamilyOwner
}

export interface OwnerAssignment {
  owner?: PartnerOwner
  family?: FamilyOwner
}

export interface PlanInput {
  anchorDate?: string
  eventTypes: readonly EventType[]
  scale: EventScale
  state: Readonly<Record<string, 'done' | 'skip'>>
  owners?: Readonly<Record<string, OwnerAssignment>>
  today?: string
}

export function planChecklist(input: PlanInput): PlanItem[] {
  const { anchorDate, eventTypes, scale, state } = input
  const today = input.today ?? format(new Date(), 'yyyy-MM-dd')
  const owners = input.owners ?? {}
  const present = new Set(eventTypes)

  const dress = (
    key: PlanKey,
    offsetDays: number,
    dueDate: string | undefined,
    fromScale: boolean,
  ): PlanItem => {
    const status: CheckStatus = state[key] ?? 'todo'
    const due = dueDate !== undefined && dueDate <= today
    const own = owners[key] ?? {}
    return {
      key,
      offsetDays,
      dueDate,
      status,
      due,
      overdue: due && status === 'todo',
      bucket: bucketOf(offsetDays),
      fromScale,
      ...(own.owner ? { owner: own.owner } : {}),
      ...(own.family ? { family: own.family } : {}),
    }
  }

  const base = buildChecklist({ anchorDate, eventTypes, state, today }).map((i) =>
    dress(i.key, i.offsetDays, i.dueDate, false),
  )

  const extra = SCALE_TEMPLATE.filter(
    (i) =>
      (i.scales as readonly EventScale[]).includes(scale) &&
      (!('needs' in i) || i.needs.some((n) => present.has(n))),
  ).map((i) =>
    dress(
      i.key,
      i.offsetDays,
      anchorDate ? format(addDays(parseISO(anchorDate), i.offsetDays), 'yyyy-MM-dd') : undefined,
      true,
    ),
  )

  return [...base, ...extra].sort((a, b) => a.offsetDays - b.offsetDays || a.key.localeCompare(b.key))
}

export interface BucketGroup {
  bucket: Bucket
  items: PlanItem[]
  /** Open steps in this window — what the heading badge counts. */
  open: number
}

/** Non-empty windows only, farthest out first. */
export function groupByBucket(items: readonly PlanItem[]): BucketGroup[] {
  return BUCKETS.map((bucket) => {
    const inBucket = items.filter((i) => i.bucket === bucket)
    return { bucket, items: inBucket, open: inBucket.filter((i) => i.status === 'todo').length }
  }).filter((g) => g.items.length > 0)
}

/**
 * The window the couple is living in right now, so the screen can open on it
 * instead of on work they finished a year ago. Undefined without a date.
 */
export function currentBucket(anchorDate: string | undefined, today?: string): Bucket | undefined {
  if (!anchorDate) return undefined
  const from = today ?? format(new Date(), 'yyyy-MM-dd')
  const days = Math.round((parseISO(anchorDate).getTime() - parseISO(from).getTime()) / 86_400_000)
  return bucketOf(Math.min(CHECKLIST_MAX_OFFSET, Math.max(CHECKLIST_MIN_OFFSET, -days)))
}

// --- ownership -----------------------------------------------------------

export interface Load<K extends string> {
  /** Open steps per owner, plus the ones nobody has taken. */
  open: Record<K | 'none', number>
  /** Steps handled (done or skipped) per owner. */
  handled: Record<K | 'none', number>
}

const tally = <K extends string>(
  keys: readonly K[],
  items: readonly PlanItem[],
  pick: (i: PlanItem) => K | undefined,
): Load<K> => {
  const zero = () =>
    Object.fromEntries([...keys, 'none'].map((k) => [k, 0])) as Record<K | 'none', number>
  const load: Load<K> = { open: zero(), handled: zero() }
  for (const i of items) load[i.status === 'todo' ? 'open' : 'handled'][pick(i) ?? 'none'] += 1
  return load
}

/**
 * Who is holding what, on both axes at once. A description of the split, not a
 * judgement of it: no ratio, no target, no "unfair" flag. The screen shows the
 * counts and leaves the conversation to the couple.
 */
export function ownerLoad(
  items: readonly PlanItem[],
  partnerOwners: readonly PartnerOwner[],
  familyOwners: readonly FamilyOwner[],
): { partner: Load<PartnerOwner>; family: Load<FamilyOwner> } {
  return {
    partner: tally(partnerOwners, items, (i) => i.owner),
    family: tally(familyOwners, items, (i) => i.family),
  }
}
