import { useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n } from '@/i18n'
import { fmtDate, formatRupiah } from '@/i18n/format'
import {
  budgetByEvent,
  budgetRollup,
  compareCategory,
  contractGaps,
  fundingBySource,
  paymentReminders,
  vendorCategories,
  vendorMoney,
} from './money'
import {
  FUND_SOURCES,
  PAY_MILESTONES,
  type FundSource,
  type PayMilestone,
  type PlannerOf,
  type PlannerRecord,
} from './types'

/**
 * Wedding money tab (W06–W10).
 *
 * Every number on this screen was typed in by the couple and is read back out of
 * IndexedDB through `useOwned()`. TemuDua holds no price list, no vendor
 * directory, and no opinion: it separates planned from committed from paid, keeps
 * each family's pot apart from the couple's, and puts the dates you entered in
 * front of you before they pass. It never says what to pay, book, or cancel.
 */
export function Money({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const rows = useOwned<PlannerRecord>('wedding', me)
  const [sheet, setSheet] = useState<SheetKind | null>(null)
  const [pickedVendor, setPickedVendor] = useState('')
  const [pickedCategory, setPickedCategory] = useState('')

  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is PlannerOf<K> => r.kind === kind)

  const events = of('wed_event')
  const lines = of('wed_budget2')
  const funds = of('wed_fund')
  const vendors = of('wed_vendor2')
  const pays = of('wed_pay')

  const rp = (n: number) => formatRupiah(n, locale)
  const rpOpt = (n: number | undefined) => (n === undefined ? t('wedding2.unknown') : rp(n))

  const nameOf = (e: PlannerOf<'wed_event'>) =>
    e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const)
  const eventLabel = (id: string | undefined) => {
    if (!id) return t('wedding2.mny.whole')
    const e = events.find((x) => x.id === id)
    return e ? nameOf(e) : t('wedding2.mny.eventGone')
  }
  const vendorName = (id: string) => vendors.find((v) => v.id === id)?.name ?? t('wedding2.mny.eventGone')

  const perEvent = budgetByEvent(lines, events.map((e) => e.id))
  const grand = budgetRollup(lines)
  const sources = fundingBySource(funds, lines)
  const reminders = paymentReminders(pays)
  const gaps = contractGaps(vendors, pays)
  const categories = vendorCategories(vendors)
  const activeCategory =
    pickedCategory && categories.includes(pickedCategory) ? pickedCategory : (categories[0] ?? '')
  const comparison = activeCategory ? compareCategory(vendors, pays, activeCategory) : undefined
  const activeVendor =
    vendors.find((v) => v.id === pickedVendor) ?? vendors[0]
  const activeMoney = activeVendor
    ? vendorMoney(activeVendor, pays.filter((p) => p.vendorId === activeVendor.id))
    : undefined

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.mny.intro')}</p>
      <p className="banner">{t('wedding2.mny.caveat')}</p>

      {/* W06 — planned / committed / paid, per event -------------------- */}
      <Card
        title={t('wedding2.mny.budget')}
        icon="money"
        hint={t('wedding2.mny.budgetHint')}
        action={
          <button className="btn btn--sm" onClick={() => setSheet('line')}>
            <Icon name="plus" size={16} /> {t('wedding2.mny.addLine')}
          </button>
        }
      >
        {lines.length === 0 ? (
          <EmptyState
            icon="money"
            title={t('wedding2.mny.noLines')}
            hint={t('wedding2.mny.noLinesHint')}
          />
        ) : (
          <>
            <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
              <span className="chip chip--yellow">{t('wedding2.mny.cPlanned', { amount: rp(grand.planned) })}</span>
              <span className="chip chip--blue">{t('wedding2.mny.cCommitted', { amount: rp(grand.committed) })}</span>
              <span className="chip chip--mint">{t('wedding2.mny.cPaid', { amount: rp(grand.paid) })}</span>
              <span className="chip">{t('wedding2.mny.cUnpaid', { amount: rp(grand.unpaid) })}</span>
              {grand.overPlan > 0 && (
                <span className="chip chip--yellow">{t('wedding2.mny.cOverPlan', { amount: rp(grand.overPlan) })}</span>
              )}
            </div>
            <p className="card__hint">{t('wedding2.mny.threeWays')}</p>

            {perEvent
              .filter((r) => r.roll.lines > 0)
              .map((r) => (
                <div key={r.eventId ?? 'all'} className="stack stack--tight" style={{ marginBottom: 'var(--space-3)' }}>
                  <strong style={{ fontSize: 13 }}>{eventLabel(r.eventId)}</strong>
                  <span className="card__hint">
                    {t('wedding2.mny.rollRow', {
                      planned: rp(r.roll.planned),
                      committed: rp(r.roll.committed),
                      paid: rp(r.roll.paid),
                    })}
                  </span>
                  <ul className="list">
                    {lines
                      .filter((b) => (b.eventId ?? undefined) === r.eventId)
                      .map((b) => (
                        <li key={b.id} className="list__item">
                          <span className="grow stack stack--tight">
                            <strong style={{ fontSize: 14 }}>{b.label}</strong>
                            <span className="card__hint">
                              {t('wedding2.mny.linePlanned', { amount: rp(b.planned) })} ·{' '}
                              {t(`wedding2.src.${b.source}` as const)}
                            </span>
                            <span className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
                              <MoneyInput
                                label={`${b.label} — ${t('wedding2.mny.fCommitted')}`}
                                value={b.committed}
                                onCommit={(n) => patch('wedding', b.id, { committed: n })}
                              />
                              <MoneyInput
                                label={`${b.label} — ${t('wedding2.mny.fPaid')}`}
                                value={b.paid}
                                onCommit={(n) => patch('wedding', b.id, { paid: n })}
                              />
                            </span>
                          </span>
                          <button
                            className="btn btn--ghost btn--sm btn--icon"
                            onClick={() => softDelete('wedding', b.id, me)}
                          >
                            <Icon name="close" size={16} label={t('common.deleteX', { name: b.label })} />
                          </button>
                        </li>
                      ))}
                  </ul>
                </div>
              ))}
          </>
        )}
      </Card>

      {/* W07 — where the money comes from ------------------------------- */}
      <Card
        title={t('wedding2.mny.funding')}
        icon="shared"
        hint={t('wedding2.mny.fundingHint')}
        action={
          <button className="btn btn--sm" onClick={() => setSheet('fund')}>
            <Icon name="plus" size={16} /> {t('wedding2.mny.addFund')}
          </button>
        }
      >
        <ul className="list">
          {sources.map((s) => (
            <li key={s.source} className="list__item">
              <Icon name="money" size={18} />
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14 }}>{t(`wedding2.src.${s.source}` as const)}</strong>
                <span className="card__hint">
                  {t('wedding2.mny.fundRow', {
                    pledged: rp(s.pledged),
                    received: rp(s.received),
                    paid: rp(s.spent.paid),
                  })}
                </span>
                {s.outstanding > 0 && (
                  <span className="card__hint">{t('wedding2.mny.fundOutstanding', { amount: rp(s.outstanding) })}</span>
                )}
              </span>
              {s.short > 0 ? (
                <span className="chip chip--yellow">{t('wedding2.mny.fundShort', { amount: rp(s.short) })}</span>
              ) : (
                <span className="chip">{t('wedding2.mny.fundLeft', { amount: rp(s.left) })}</span>
              )}
            </li>
          ))}
        </ul>
        {funds.length === 0 ? (
          <p className="card__hint">{t('wedding2.mny.noFundsHint')}</p>
        ) : (
          <ul className="list">
            {funds.map((f) => (
              <li key={f.id} className="list__item">
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{f.label?.trim() || t(`wedding2.src.${f.source}` as const)}</strong>
                  <span className="card__hint">
                    {t('wedding2.mny.pledgeRow', { pledged: rp(f.pledged), received: rp(f.received) })}
                  </span>
                </span>
                <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', f.id, me)}>
                  <Icon name="close" size={16} label={t('common.deleteX', { name: f.label ?? f.source })} />
                </button>
              </li>
            ))}
          </ul>
        )}
        <p className="disclaimer">{t('wedding2.mny.fundCaveat')}</p>
      </Card>

      {/* W08 — one vendor's quote, deposit, balance, schedule ----------- */}
      <Card title={t('wedding2.mny.vendorMoney')} icon="ring" hint={t('wedding2.mny.vendorHint')}>
        {vendors.length === 0 || !activeVendor || !activeMoney ? (
          <EmptyState
            icon="ring"
            title={t('wedding2.mny.noVendors')}
            hint={t('wedding2.mny.noVendorsHint')}
          />
        ) : (
          <>
            <Field label={t('wedding2.mny.pickVendor')}>
              {(p) => (
                <select {...p} value={activeVendor.id} onChange={(e) => setPickedVendor(e.target.value)}>
                  {vendors.map((v) => (
                    <option key={v.id} value={v.id}>
                      {v.name} — {v.category}
                    </option>
                  ))}
                </select>
              )}
            </Field>

            <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
              <span className="chip chip--yellow">{t('wedding2.mny.vQuote', { amount: rpOpt(activeMoney.quote) })}</span>
              <span className="chip">{t('wedding2.mny.vDeposit', { amount: rpOpt(activeMoney.deposit) })}</span>
              <span className="chip chip--blue">{t('wedding2.mny.vScheduled', { amount: rp(activeMoney.scheduled) })}</span>
              <span className="chip chip--mint">{t('wedding2.mny.vPaid', { amount: rp(activeMoney.paid) })}</span>
              <span className="chip">{t('wedding2.mny.vBalance', { amount: rpOpt(activeMoney.balance) })}</span>
            </div>
            {activeMoney.unscheduled !== undefined && activeMoney.unscheduled !== 0 && (
              <p className="card__hint">
                {t('wedding2.mny.vUnscheduled', { amount: rp(activeMoney.unscheduled) })}
              </p>
            )}
            {activeMoney.fromFlatFields && <p className="banner">{t('wedding2.mny.flatFallback')}</p>}

            <div className="row row--between">
              <strong style={{ fontSize: 13 }}>{t('wedding2.mny.schedule')}</strong>
              <button className="btn btn--ghost btn--sm" onClick={() => setSheet('pay')}>
                <Icon name="plus" size={16} /> {t('wedding2.mny.addPay')}
              </button>
            </div>
            {activeMoney.schedule.length === 0 ? (
              <p className="card__hint">{t('wedding2.mny.noPay')}</p>
            ) : (
              <ul className="list">
                {activeMoney.schedule.map((p) => (
                  <li key={p.id} className="list__item">
                    <span className="chip">{t(`wedding2.mny.ms.${p.milestone}` as const)}</span>
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{rp(p.amount)}</strong>
                      <span className="card__hint">
                        {p.dueDate ? fmtDate(p.dueDate, 'd MMM yyyy', locale) : t('wedding2.mny.noDue')}
                        {p.paidAt ? ` · ${t('wedding2.mny.settledOn', { date: fmtDate(p.paidAt, 'd MMM yyyy', locale) })}` : ''}
                      </span>
                    </span>
                    <button
                      className="btn btn--ghost btn--sm"
                      onClick={() =>
                        patch('wedding', p.id, {
                          paidAt: p.paidAt ? undefined : new Date().toISOString().slice(0, 10),
                        })
                      }
                    >
                      {p.paidAt ? t('wedding2.mny.undoSettled') : t('wedding2.mny.markSettled')}
                    </button>
                    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', p.id, me)}>
                      <Icon name="close" size={16} label={t('common.deleteX', { name: rp(p.amount) })} />
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </>
        )}
      </Card>

      {/* W09 — one category, side by side ------------------------------- */}
      {comparison && (
        <Card title={t('wedding2.mny.compare')} icon="ring" hint={t('wedding2.mny.compareHint')}>
          <Field label={t('wedding2.mny.pickCategory')}>
            {(p) => (
              <select {...p} value={activeCategory} onChange={(e) => setPickedCategory(e.target.value)}>
                {categories.map((c) => (
                  <option key={c} value={c}>
                    {c}
                  </option>
                ))}
              </select>
            )}
          </Field>
          <div className="table-scroll">
            <table>
              <thead>
                <tr>
                  <th scope="col">{t('wedding2.colVendor')}</th>
                  <th scope="col">{t('wedding2.mny.colQuote')}</th>
                  <th scope="col">{t('wedding2.mny.colDeposit')}</th>
                  <th scope="col">{t('wedding2.mny.colScheduled')}</th>
                  <th scope="col">{t('wedding2.mny.colPaid')}</th>
                  <th scope="col">{t('wedding2.mny.colBalance')}</th>
                  <th scope="col">{t('wedding2.mny.colTerms')}</th>
                </tr>
              </thead>
              <tbody>
                {comparison.rows.map((r) => (
                  <tr key={r.id}>
                    <th scope="row" style={{ textAlign: 'left', fontWeight: 600 }}>
                      {r.name}
                    </th>
                    <td>{rpOpt(r.money.quote)}</td>
                    <td>{rpOpt(r.money.deposit)}</td>
                    <td>{rp(r.money.scheduled)}</td>
                    <td>{rp(r.money.paid)}</td>
                    <td>{rpOpt(r.money.balance)}</td>
                    <td>{t('wedding2.mny.termsCount', { n: r.money.schedule.length })}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <p className="card__hint">
            {comparison.range
              ? t('wedding2.mny.range', {
                  min: rp(comparison.range.min),
                  max: rp(comparison.range.max),
                  spread: rp(comparison.range.spread),
                })
              : t('wedding2.mny.noRange')}
            {comparison.withoutQuote > 0
              ? ` ${t('wedding2.mny.missingQuote', { n: comparison.withoutQuote })}`
              : ''}
          </p>
          <p className="disclaimer">{t('wedding2.mny.noWinner')}</p>
        </Card>
      )}

      {/* W10 — contract and payment reminders --------------------------- */}
      <Card title={t('wedding2.mny.reminders')} icon="calendar" hint={t('wedding2.mny.remindersHint')}>
        {reminders.length === 0 && gaps.length === 0 ? (
          <p className="card__hint">{t('wedding2.mny.noReminders')}</p>
        ) : (
          <ul className="list">
            {reminders.map((r) => (
              <li key={r.payId} className="list__item">
                <Icon name={r.window === 'overdue' ? 'info' : 'calendar'} size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>
                    {vendorName(r.vendorId)} · {t(`wedding2.mny.ms.${r.milestone}` as const)}
                  </strong>
                  <span className="card__hint">
                    {r.amount > 0 ? `${rp(r.amount)} · ` : ''}
                    {r.dueDate ? fmtDate(r.dueDate, 'd MMM yyyy', locale) : t('wedding2.mny.noDue')}
                  </span>
                </span>
                <span className={r.window === 'overdue' ? 'chip chip--yellow' : 'chip'}>
                  {r.daysLeft === undefined
                    ? t('wedding2.mny.win.undated')
                    : r.daysLeft < 0
                      ? t('wedding2.mny.lateBy', { n: -r.daysLeft })
                      : r.daysLeft === 0
                        ? t('wedding2.mny.win.today')
                        : t('wedding2.mny.dueIn', { n: r.daysLeft })}
                </span>
              </li>
            ))}
            {gaps.map((g) => (
              <li key={g.vendorId} className="list__item">
                <Icon name="info" size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{vendorName(g.vendorId)}</strong>
                  <span className="card__hint">{t(`wedding2.mny.gap.${g.reason}` as const)}</span>
                </span>
              </li>
            ))}
          </ul>
        )}
        <p className="disclaimer">{t('wedding2.mny.reminderCaveat')}</p>
      </Card>

      <MoneySheet
        kind={sheet}
        onClose={() => setSheet(null)}
        me={me}
        events={events.map((e) => ({ id: e.id, name: nameOf(e) }))}
        vendorId={activeVendor?.id}
      />
    </div>
  )
}

/**
 * Inline rupiah box, committed on blur rather than on every keystroke — a live
 * query round-trip per digit would fight whoever is typing.
 *
 * ponytail: uncontrolled, so a change made in another tab does not refresh the
 * box until this screen remounts. One field, low stakes; make it controlled with
 * a keyed remount if the app ever gets two live editors on the same row.
 */
function MoneyInput({
  label,
  value,
  onCommit,
}: {
  label: string
  value: number | undefined
  onCommit: (n: number) => void
}) {
  return (
    <label className="row" style={{ gap: 4 }}>
      <span className="visually-hidden">{label}</span>
      <input
        type="number"
        min="0"
        inputMode="numeric"
        style={{ minHeight: 36, fontSize: 13, maxWidth: 140 }}
        defaultValue={value ?? ''}
        aria-label={label}
        onBlur={(e) => onCommit(Math.max(0, Number(e.target.value) || 0))}
      />
    </label>
  )
}

type SheetKind = 'line' | 'fund' | 'pay'

function MoneySheet({
  kind,
  onClose,
  me,
  events,
  vendorId,
}: {
  kind: SheetKind | null
  onClose: () => void
  me: string
  events: { id: string; name: string }[]
  vendorId: string | undefined
}) {
  const { t } = useI18n()
  const [label, setLabel] = useState('')
  const [eventId, setEventId] = useState('')
  const [planned, setPlanned] = useState('')
  const [committed, setCommitted] = useState('')
  const [paid, setPaid] = useState('')
  const [source, setSource] = useState<FundSource>('patungan')
  const [pledged, setPledged] = useState('')
  const [received, setReceived] = useState('')
  const [milestone, setMilestone] = useState<PayMilestone>('dp')
  const [amount, setAmount] = useState('')
  const [dueDate, setDueDate] = useState('')

  const num = (raw: string) => Math.max(0, Number(raw) || 0)

  function reset() {
    setLabel('')
    setEventId('')
    setPlanned('')
    setCommitted('')
    setPaid('')
    setPledged('')
    setReceived('')
    setAmount('')
    setDueDate('')
  }

  const add = (rec: Record<string, unknown>) =>
    db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), ...rec } as never)

  async function save() {
    if (kind === 'line') {
      if (!label.trim()) return
      await add({
        kind: 'wed_budget2',
        label: label.trim(),
        ...(eventId ? { eventId } : {}),
        planned: num(planned),
        committed: num(committed),
        paid: num(paid),
        source,
      })
    } else if (kind === 'fund') {
      await add({
        kind: 'wed_fund',
        source,
        ...(label.trim() ? { label: label.trim() } : {}),
        pledged: num(pledged),
        received: num(received),
      })
    } else if (kind === 'pay') {
      if (!vendorId) return
      await add({
        kind: 'wed_pay',
        vendorId,
        milestone,
        amount: num(amount),
        ...(dueDate ? { dueDate } : {}),
      })
    }
    reset()
    onClose()
  }

  const moneyField = (labelText: string, value: string, set: (v: string) => void, hint?: string) => (
    <Field label={labelText} hint={hint}>
      {(p) => (
        <input {...p} type="number" min="0" inputMode="numeric" value={value} onChange={(e) => set(e.target.value)} />
      )}
    </Field>
  )

  const sourceField = (
    <Field label={t('wedding2.fSource')}>
      {(p) => (
        <select {...p} value={source} onChange={(e) => setSource(e.target.value as FundSource)}>
          {FUND_SOURCES.map((s) => (
            <option key={s} value={s}>
              {t(`wedding2.src.${s}` as const)}
            </option>
          ))}
        </select>
      )}
    </Field>
  )

  return (
    <Sheet
      open={kind !== null}
      onClose={onClose}
      title={kind ? t(`wedding2.mny.sheet.${kind}` as const) : ''}
    >
      <div className="stack">
        {kind === 'line' && (
          <>
            <Field label={t('wedding2.fBudgetLabel')}>
              {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fEvent')} hint={t('common.optional')}>
              {(p) => (
                <select {...p} value={eventId} onChange={(e) => setEventId(e.target.value)}>
                  <option value="">{t('wedding2.mny.whole')}</option>
                  {events.map((e) => (
                    <option key={e.id} value={e.id}>
                      {e.name}
                    </option>
                  ))}
                </select>
              )}
            </Field>
            {moneyField(t('wedding2.mny.fPlanned'), planned, setPlanned, t('wedding2.mny.hPlanned'))}
            {moneyField(t('wedding2.mny.fCommitted'), committed, setCommitted, t('wedding2.mny.hCommitted'))}
            {moneyField(t('wedding2.mny.fPaid'), paid, setPaid, t('wedding2.mny.hPaid'))}
            {sourceField}
          </>
        )}

        {kind === 'fund' && (
          <>
            {sourceField}
            <Field label={t('wedding2.mny.fFundLabel')} hint={t('common.optional')}>
              {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
            </Field>
            {moneyField(t('wedding2.mny.fPledged'), pledged, setPledged, t('wedding2.mny.hPledged'))}
            {moneyField(t('wedding2.mny.fReceived'), received, setReceived, t('wedding2.mny.hReceived'))}
          </>
        )}

        {kind === 'pay' && (
          <>
            <Field label={t('wedding2.mny.fMilestone')} hint={t('wedding2.mny.hMilestone')}>
              {(p) => (
                <select {...p} value={milestone} onChange={(e) => setMilestone(e.target.value as PayMilestone)}>
                  {PAY_MILESTONES.map((m) => (
                    <option key={m} value={m}>
                      {t(`wedding2.mny.ms.${m}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
            {moneyField(t('wedding2.mny.fAmount'), amount, setAmount, t('wedding2.mny.hAmount'))}
            <Field label={t('wedding2.mny.fDue')} hint={t('common.optional')}>
              {(p) => <input {...p} type="date" value={dueDate} onChange={(e) => setDueDate(e.target.value)} />}
            </Field>
          </>
        )}

        <button className="btn btn--block" onClick={save}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
