/**
 * Post-wedding checklist (W36).
 *
 * The party is over; a handful of things are not. This is a plain checklist —
 * thank-yous, the last vendor balances, the name/document changes — grouped by
 * bucket and counted. It is never a score and never a verdict: an empty list is
 * `allDone: false`, because "nothing listed" is not "nothing left", the couple
 * has simply not written it down yet.
 *
 * Structural counts in, numbers out — no copy, no database.
 */

import { POST_CATEGORIES, type PostCategory } from './types'

export interface PostTaskLike {
  category: PostCategory
  done?: boolean
}

export interface PostProgress {
  total: number
  doneCount: number
  /** per-bucket total and done, so a section can show its own tally. */
  byCategory: Record<PostCategory, { total: number; done: number }>
  /** true only when there is at least one task and every one is done. */
  allDone: boolean
}

export function postProgress(tasks: readonly PostTaskLike[]): PostProgress {
  const byCategory = Object.fromEntries(
    POST_CATEGORIES.map((c) => [c, { total: 0, done: 0 }]),
  ) as Record<PostCategory, { total: number; done: number }>

  let doneCount = 0
  for (const t of tasks) {
    byCategory[t.category].total += 1
    if (t.done) {
      byCategory[t.category].done += 1
      doneCount += 1
    }
  }

  return {
    total: tasks.length,
    doneCount,
    byCategory,
    allDone: tasks.length > 0 && doneCount === tasks.length,
  }
}
