import { useEffect, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n, type TFunction } from '@/i18n'
import { fmtDate, formatRupiah } from '@/i18n/format'
import { buildChecklist, checklistProgress, type CheckKey } from './checklist'
import { withResolvedDates } from './deps'
import {
  anchorDate,
  budgetTotals,
  paxForEvent,
  quotaUsage,
  readiness,
  vendorTerms,
} from './plannerMath'
import {
  EVENT_TYPES,
  FUND_SOURCES,
  QUOTA_SIDES,
  RSVP_STATES,
  VENDOR_STATES,
  type EventType,
  type FundSource,
  type PlannerOf,
  type PlannerRecord,
  type QuotaSide,
  type Rsvp,
  type VendorState,
} from './types'

/**
 * Multi-event wedding planner (WED-06).
 *
 * Lives under the "siap acara" side of the module and never mixes with the
 * WED-02 readiness answers: blueprint 03 §7 keeps "siap hidup bareng" and "siap
 * acara" apart, so this screen owns logistics only and says so out loud.
 */

type SheetKind = 'event' | 'rundown' | 'guest' | 'vendor' | 'budget' | 'quota'

export function Planner({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [sheet, setSheet] = useState<{ kind: SheetKind; eventId?: string } | null>(null)
  const rows = useOwned<PlannerRecord>('wedding', me)

  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is PlannerOf<K> => r.kind === kind)

  // Undated events sort last — they are the ones still being decided.
  // `withResolvedDates` fills in the events whose date hangs off another one
  // (WED-07), so the anchor, the checklist, and the risks below all read the
  // date the event actually falls on rather than the empty field in the store.
  const events = withResolvedDates(of('wed_event')).sort((a, b) =>
    (a.date ?? '9999').localeCompare(b.date ?? '9999'),
  )
  const rundowns = of('wed_rundown')
  const guests = of('wed_guest2')
  const vendors = of('wed_vendor2')
  const budget = of('wed_budget2')
  const checks = of('wed_check')
  const quotaRecord = of('wed_quota').at(-1)

  const quota = quotaRecord
    ? { pasangan: quotaRecord.pasangan, ortu_a: quotaRecord.ortu_a, ortu_b: quotaRecord.ortu_b }
    : undefined
  const anchor = anchorDate(events)
  const checklist = buildChecklist({
    anchorDate: anchor,
    eventTypes: events.map((e) => e.eventType),
    state: Object.fromEntries(checks.map((c) => [c.checkKey, c.status] as const)),
  })
  const progress = checklistProgress(checklist)
  const money = budgetTotals(budget)
  const ready = readiness({
    events,
    rundownEventIds: rundowns.map((r) => r.eventId),
    guests,
    quota,
    vendors,
    budget,
    checklist,
  })

  const nameOf = (e: PlannerOf<'wed_event'>) =>
    e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const)
  const eventName = (id: string | undefined) => {
    const e = events.find((x) => x.id === id)
    return e ? nameOf(e) : t('wedding2.allEvents')
  }

  async function setCheck(key: CheckKey, next: 'done' | 'skip' | null) {
    const existing = checks.find((c) => c.checkKey === key)
    // Nothing stored means "todo", so clearing a step is a delete, not a third state.
    if (!existing) {
      if (next) await db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), kind: 'wed_check', checkKey: key, status: next } as never)
      return
    }
    if (!next) await softDelete('wedding', existing.id, me)
    else await patch('wedding', existing.id, { status: next })
  }

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.intro')}</p>
      <p className="banner">{t('wedding2.separate')}</p>

      <Card title={t('wedding2.dash')} icon="ring" hint={t('wedding2.checkpoints', { passed: ready.passed, total: ready.total })}>
        <div className="row row--between">
          <strong style={{ fontSize: 28 }}>{t('wedding2.pct', { pct: ready.pct })}</strong>
          <span className="chip">{t('wedding2.chkProgress', { handled: progress.handled, total: progress.total })}</span>
        </div>
        <span className="goal__bar" aria-hidden="true">
          <span style={{ width: `${ready.pct}%` }} />
        </span>
        <p className="card__hint">
          {anchor ? t('wedding2.anchorIs', { date: fmtDate(anchor, 'd MMMM yyyy', locale) }) : t('wedding2.anchorNone')}
        </p>

        <strong style={{ fontSize: 13 }}>{t('wedding2.risks')}</strong>
        {ready.risks.length === 0 ? (
          <p className="card__hint">{t('wedding2.noRisks')}</p>
        ) : (
          <ul className="list">
            {ready.risks.map((r) => (
              <li key={r.key} className="list__item">
                <Icon name="info" size={18} />
                <span className="grow">
                  {t(`wedding2.risk.${r.key}` as const, {
                    n: r.n ?? 0,
                    amount: formatRupiah(r.amount ?? 0, locale),
                  })}
                </span>
              </li>
            ))}
          </ul>
        )}
        <p className="disclaimer">{t('wedding2.caveat')}</p>
      </Card>

      {/* Events -------------------------------------------------------- */}
      <Card
        title={t('wedding2.events')}
        icon="calendar"
        action={
          <button className="btn btn--sm" onClick={() => setSheet({ kind: 'event' })}>
            <Icon name="plus" size={16} /> {t('wedding2.addEvent')}
          </button>
        }
      >
        {events.length === 0 ? (
          <EmptyState icon="calendar" title={t('wedding2.noEvents')} hint={t('wedding2.noEventsHint')} />
        ) : (
          events.map((e) => {
            const pax = paxForEvent(guests, e.id)
            const lines = rundowns
              .filter((r) => r.eventId === e.id)
              .sort((a, b) => a.time.localeCompare(b.time))
            return (
              <div key={e.id} className="stack stack--tight" style={{ marginBottom: 'var(--space-4)' }}>
                <div className="row row--between">
                  <strong style={{ fontSize: 15 }}>{nameOf(e)}</strong>
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', e.id, me)}>
                    <Icon name="close" size={16} label={t('common.deleteX', { name: nameOf(e) })} />
                  </button>
                </div>
                <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
                  <span className={e.date ? 'chip chip--blue' : 'chip'}>
                    {e.date ? fmtDate(e.date, 'd MMM yyyy', locale) : t('wedding2.missDate')}
                  </span>
                  <span className="chip">{e.venue || t('wedding2.missVenue')}</span>
                  <span className="chip">{e.pic || t('wedding2.missPic')}</span>
                  <span className="chip chip--mint">{t('wedding2.eventPax', { n: pax.ya })}</span>
                </div>
                {e.note && <p className="card__hint">{e.note}</p>}

                <div className="row row--between">
                  <strong style={{ fontSize: 13 }}>{t('wedding2.rundown')}</strong>
                  <button className="btn btn--ghost btn--sm" onClick={() => setSheet({ kind: 'rundown', eventId: e.id })}>
                    <Icon name="plus" size={16} /> {t('wedding2.addRundown')}
                  </button>
                </div>
                {lines.length === 0 ? (
                  <p className="card__hint">{t('wedding2.noRundown')}</p>
                ) : (
                  <ul className="list">
                    {lines.map((r) => (
                      <li key={r.id} className="list__item">
                        <span className="chip">{r.time}</span>
                        <span className="grow">{r.what}</span>
                        <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', r.id, me)}>
                          <Icon name="close" size={16} label={t('common.deleteX', { name: r.what })} />
                        </button>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            )
          })
        )}
      </Card>

      {/* Checklist ----------------------------------------------------- */}
      <Card title={t('wedding2.checklist')} icon="tasks" hint={t('wedding2.checklistHint')}>
        {!anchor && <p className="banner">{t('wedding2.checklistNoDate')}</p>}
        <ul className="list">
          {checklist.map((item) => (
            <li key={item.key} className="list__item">
              <span className="chip">{offsetLabel(item.offsetDays, t)}</span>
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14, opacity: item.status === 'todo' ? 1 : 0.55 }}>
                  {t(`wedding2.chk.${item.key}` as const)}
                </strong>
                <span className="card__hint">
                  {item.dueDate ? fmtDate(item.dueDate, 'd MMM yyyy', locale) : t('wedding2.unknown')}
                  {item.status !== 'todo' ? ` · ${t(`wedding2.stat.${item.status}` as const)}` : ''}
                </span>
              </span>
              {item.overdue && <span className="chip chip--yellow">{t('wedding2.overdueChip')}</span>}
              {item.status === 'todo' ? (
                <>
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => setCheck(item.key, 'done')}>
                    <Icon name="check" size={16} label={t('wedding2.markDone')} />
                  </button>
                  <button className="btn btn--ghost btn--sm" onClick={() => setCheck(item.key, 'skip')}>
                    {t('wedding2.markSkip')}
                  </button>
                </>
              ) : (
                <button className="btn btn--ghost btn--sm" onClick={() => setCheck(item.key, null)}>
                  {t('wedding2.reopen')}
                </button>
              )}
            </li>
          ))}
        </ul>
      </Card>

      {/* Guests -------------------------------------------------------- */}
      <Card
        title={t('wedding2.quotaCard')}
        icon="family"
        hint={t('wedding2.quotaHint')}
        action={
          <button className="btn btn--sm" onClick={() => setSheet({ kind: 'quota' })}>
            <Icon name="settings" size={16} /> {t('wedding2.editQuota')}
          </button>
        }
      >
        <ul className="list">
          {quotaUsage(guests, quota).map((row) => (
            <li key={row.side} className="list__item">
              <Icon name="shared" size={18} />
              <span className="grow">{t(`wedding2.quota.${row.side}` as const)}</span>
              <span className="chip">
                {row.limit > 0
                  ? t('wedding2.quotaRow', { used: row.used, limit: row.limit })
                  : t('wedding2.quotaNoLimit', { used: row.used })}
              </span>
              {row.over > 0 && <span className="chip chip--yellow">{t('wedding2.quotaOver', { n: row.over })}</span>}
            </li>
          ))}
        </ul>
      </Card>

      <Card
        title={t('wedding2.guests')}
        icon="family"
        hint={t('wedding2.rsvpHint')}
        action={
          <button className="btn btn--sm" onClick={() => setSheet({ kind: 'guest' })}>
            <Icon name="plus" size={16} /> {t('wedding2.addGuest')}
          </button>
        }
      >
        {guests.length === 0 ? (
          <EmptyState icon="family" title={t('wedding2.noGuests')} hint={t('wedding2.noGuestsHint')} />
        ) : (
          <>
            {events.map((e) => {
              const pax = paxForEvent(guests, e.id)
              return (
                <p key={e.id} className="card__hint">
                  <strong>{nameOf(e)}</strong> ·{' '}
                  {t('wedding2.paxLine', { ya: pax.ya, ragu: pax.ragu, belum: pax.belum })}
                </p>
              )
            })}
            <div className="table-scroll">
              <table>
                <thead>
                  <tr>
                    <th scope="col">{t('wedding2.colGuest')}</th>
                    <th scope="col">{t('wedding2.colPax')}</th>
                    {events.map((e) => (
                      <th key={e.id} scope="col">
                        {nameOf(e)}
                      </th>
                    ))}
                    <th scope="col">{t('wedding2.colAction')}</th>
                  </tr>
                </thead>
                <tbody>
                  {guests.map((g) => (
                    <tr key={g.id}>
                      <th scope="row" style={{ textAlign: 'left', fontWeight: 600 }}>
                        {g.name}
                        <span className="card__hint"> {t(`wedding2.quota.${g.quota}` as const)}</span>
                      </th>
                      <td>{g.pax}</td>
                      {events.map((e) => (
                        <td key={e.id}>
                          <label>
                            <span className="visually-hidden">{`${g.name} — ${nameOf(e)}`}</span>
                            <select
                              value={g.rsvp[e.id] ?? 'belum'}
                              style={{ minHeight: 36, fontSize: 13 }}
                              onChange={(ev) =>
                                patch('wedding', g.id, { rsvp: { ...g.rsvp, [e.id]: ev.target.value as Rsvp } })
                              }
                            >
                              {RSVP_STATES.map((s) => (
                                <option key={s} value={s}>
                                  {t(`wedding2.rsvp.${s}` as const)}
                                </option>
                              ))}
                            </select>
                          </label>
                        </td>
                      ))}
                      <td>
                        <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', g.id, me)}>
                          <Icon name="close" size={16} label={t('common.deleteX', { name: g.name })} />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
      </Card>

      {/* Vendors ------------------------------------------------------- */}
      <Card
        title={t('wedding2.vendors')}
        icon="ring"
        hint={t('wedding2.vendorHint')}
        action={
          <button className="btn btn--sm" onClick={() => setSheet({ kind: 'vendor' })}>
            <Icon name="plus" size={16} /> {t('wedding2.addVendor')}
          </button>
        }
      >
        {vendors.length === 0 ? (
          <EmptyState icon="ring" title={t('wedding2.noVendors')} hint={t('wedding2.noVendorsHint')} />
        ) : (
          <div className="table-scroll">
            <table>
              <thead>
                <tr>
                  <th scope="col">{t('wedding2.colVendor')}</th>
                  <th scope="col">{t('wedding2.colCategory')}</th>
                  <th scope="col">{t('wedding2.colEvent')}</th>
                  <th scope="col">{t('wedding2.colQuote')}</th>
                  <th scope="col">{t('wedding2.fBooking')}</th>
                  <th scope="col">{t('wedding2.fDp')}</th>
                  <th scope="col">{t('wedding2.fTermin')}</th>
                  <th scope="col">{t('wedding2.fPelunasan')}</th>
                  <th scope="col">{t('wedding2.colCommitted')}</th>
                  <th scope="col">{t('wedding2.colLeft')}</th>
                  <th scope="col">{t('wedding2.colStatus')}</th>
                  <th scope="col">{t('wedding2.colAction')}</th>
                </tr>
              </thead>
              <tbody>
                {[...vendors]
                  .sort((a, b) => a.category.localeCompare(b.category) || a.name.localeCompare(b.name))
                  .map((v) => {
                    const terms = vendorTerms(v)
                    const rp = (n: number | undefined) =>
                      n === undefined ? t('wedding2.unknown') : formatRupiah(n, locale)
                    return (
                      <tr key={v.id}>
                        <th scope="row" style={{ textAlign: 'left', fontWeight: 600 }}>
                          {v.name}
                        </th>
                        <td>{v.category}</td>
                        <td>{eventName(v.eventId)}</td>
                        <td>{rp(v.quote)}</td>
                        <td>{rp(v.bookingFee)}</td>
                        <td>{rp(v.dp)}</td>
                        <td>{rp(v.termin)}</td>
                        <td>{rp(v.pelunasan)}</td>
                        <td>{formatRupiah(terms.committed, locale)}</td>
                        <td>{rp(terms.outstanding)}</td>
                        <td>
                          <label>
                            <span className="visually-hidden">{`${v.name} — ${t('wedding2.colStatus')}`}</span>
                            <select
                              value={v.status}
                              style={{ minHeight: 36, fontSize: 13 }}
                              onChange={(ev) => patch('wedding', v.id, { status: ev.target.value as VendorState })}
                            >
                              {VENDOR_STATES.map((s) => (
                                <option key={s} value={s}>
                                  {t(`wedding2.vstat.${s}` as const)}
                                </option>
                              ))}
                            </select>
                          </label>
                        </td>
                        <td>
                          <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', v.id, me)}>
                            <Icon name="close" size={16} label={t('common.deleteX', { name: v.name })} />
                          </button>
                        </td>
                      </tr>
                    )
                  })}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      {/* Budget -------------------------------------------------------- */}
      <Card
        title={t('wedding2.budget')}
        icon="money"
        action={
          <button className="btn btn--sm" onClick={() => setSheet({ kind: 'budget' })}>
            <Icon name="plus" size={16} /> {t('wedding2.addBudget')}
          </button>
        }
      >
        {budget.length === 0 ? (
          <EmptyState icon="money" title={t('wedding2.noBudget')} hint={t('wedding2.noBudgetHint')} />
        ) : (
          <>
            <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
              <span className="chip chip--yellow">{t('wedding2.totPlanned', { amount: formatRupiah(money.planned, locale) })}</span>
              <span className="chip chip--mint">{t('wedding2.totPaid', { amount: formatRupiah(money.paid, locale) })}</span>
              <span className="chip">{t('wedding2.totLeft', { amount: formatRupiah(money.left, locale) })}</span>
            </div>

            <strong style={{ fontSize: 13 }}>{t('wedding2.bySource')}</strong>
            <ul className="list">
              {FUND_SOURCES.filter((s) => money.bySource[s].planned > 0 || money.bySource[s].paid > 0).map((s) => (
                <li key={s} className="list__item">
                  <Icon name="money" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{t(`wedding2.src.${s}` as const)}</strong>
                    <span className="card__hint">
                      {t('wedding2.sourceRow', {
                        planned: formatRupiah(money.bySource[s].planned, locale),
                        paid: formatRupiah(money.bySource[s].paid, locale),
                      })}
                    </span>
                  </span>
                </li>
              ))}
            </ul>

            <ul className="list">
              {budget.map((b) => (
                <li key={b.id} className="list__item">
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{b.label}</strong>
                    <span className="card__hint">
                      {eventName(b.eventId)} ·{' '}
                      {t('wedding2.sourceRow', {
                        planned: formatRupiah(b.planned, locale),
                        paid: formatRupiah(b.paid, locale),
                      })}
                    </span>
                  </span>
                  <span className="chip">{t(`wedding2.src.${b.source}` as const)}</span>
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', b.id, me)}>
                    <Icon name="close" size={16} label={t('common.deleteX', { name: b.label })} />
                  </button>
                </li>
              ))}
            </ul>
          </>
        )}
        <p className="disclaimer">{t('wedding2.budgetCaveat')}</p>
      </Card>

      <p className="disclaimer">{t('wedding2.notReplace')}</p>

      <PlannerSheet
        open={sheet}
        onClose={() => setSheet(null)}
        me={me}
        events={events.map((e) => ({ id: e.id, name: nameOf(e) }))}
        quotaRecord={quotaRecord}
      />
    </div>
  )
}

function offsetLabel(n: number, t: TFunction): string {
  if (n === 0) return t('wedding2.hDay')
  return n < 0 ? t('wedding2.hMinus', { n: -n }) : t('wedding2.hPlus', { n })
}

/** Optional numeric field: an empty box means "not known yet", never zero. */
function optionalNumber(raw: string): number | undefined {
  const n = Number(raw)
  return raw.trim() === '' || Number.isNaN(n) ? undefined : n
}

function PlannerSheet({
  open,
  onClose,
  me,
  events,
  quotaRecord,
}: {
  open: { kind: SheetKind; eventId?: string } | null
  onClose: () => void
  me: string
  events: { id: string; name: string }[]
  quotaRecord: PlannerOf<'wed_quota'> | undefined
}) {
  const { t } = useI18n()
  const [eventType, setEventType] = useState<EventType>('akad')
  const [name, setName] = useState('')
  const [label, setLabel] = useState('')
  const [date, setDate] = useState('')
  const [venue, setVenue] = useState('')
  const [pic, setPic] = useState('')
  const [note, setNote] = useState('')
  const [time, setTime] = useState('')
  const [what, setWhat] = useState('')
  const [pax, setPax] = useState('1')
  const [quotaSide, setQuotaSide] = useState<QuotaSide>('pasangan')
  const [category, setCategory] = useState('')
  const [eventId, setEventId] = useState('')
  const [quote, setQuote] = useState('')
  const [booking, setBooking] = useState('')
  const [dp, setDp] = useState('')
  const [termin, setTermin] = useState('')
  const [pelunasan, setPelunasan] = useState('')
  const [status, setStatus] = useState<VendorState>('dilirik')
  const [planned, setPlanned] = useState('')
  const [paid, setPaid] = useState('')
  const [source, setSource] = useState<FundSource>('patungan')
  const [limits, setLimits] = useState<Record<QuotaSide, string>>({ pasangan: '', ortu_a: '', ortu_b: '' })

  const kind = open?.kind ?? null

  // Seed the quota boxes from what is already stored, so editing one number
  // does not silently zero the other two. Deliberately keyed on `kind` alone:
  // the live query hands back a fresh object on every write to the store, and
  // depending on it would wipe what someone is halfway through typing.
  useEffect(() => {
    if (kind !== 'quota') return
    setLimits({
      pasangan: quotaRecord ? String(quotaRecord.pasangan) : '',
      ortu_a: quotaRecord ? String(quotaRecord.ortu_a) : '',
      ortu_b: quotaRecord ? String(quotaRecord.ortu_b) : '',
    })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [kind])

  function reset() {
    setName('')
    setLabel('')
    setDate('')
    setVenue('')
    setPic('')
    setNote('')
    setTime('')
    setWhat('')
    setPax('1')
    setCategory('')
    setEventId('')
    setQuote('')
    setBooking('')
    setDp('')
    setTermin('')
    setPelunasan('')
    setPlanned('')
    setPaid('')
  }

  const add = (rec: Record<string, unknown>) =>
    db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), ...rec } as never)

  async function save() {
    if (kind === 'event') {
      await add({
        kind: 'wed_event',
        eventType,
        ...(label.trim() ? { label: label.trim() } : {}),
        ...(date ? { date } : {}),
        ...(venue.trim() ? { venue: venue.trim() } : {}),
        ...(pic.trim() ? { pic: pic.trim() } : {}),
        ...(note.trim() ? { note: note.trim() } : {}),
      })
    } else if (kind === 'rundown') {
      if (!what.trim() || !time || !open?.eventId) return
      await add({ kind: 'wed_rundown', eventId: open.eventId, time, what: what.trim() })
    } else if (kind === 'guest') {
      if (!name.trim()) return
      await add({
        kind: 'wed_guest2',
        name: name.trim(),
        quota: quotaSide,
        pax: Math.max(1, Number(pax) || 1),
        rsvp: {},
      })
    } else if (kind === 'vendor') {
      if (!name.trim()) return
      await add({
        kind: 'wed_vendor2',
        name: name.trim(),
        category: category.trim() || t('wedding2.unknown'),
        ...(eventId ? { eventId } : {}),
        ...(optionalNumber(quote) === undefined ? {} : { quote: optionalNumber(quote) }),
        ...(optionalNumber(booking) === undefined ? {} : { bookingFee: optionalNumber(booking) }),
        ...(optionalNumber(dp) === undefined ? {} : { dp: optionalNumber(dp) }),
        ...(optionalNumber(termin) === undefined ? {} : { termin: optionalNumber(termin) }),
        ...(optionalNumber(pelunasan) === undefined ? {} : { pelunasan: optionalNumber(pelunasan) }),
        status,
      })
    } else if (kind === 'budget') {
      if (!label.trim() || !planned) return
      await add({
        kind: 'wed_budget2',
        label: label.trim(),
        ...(eventId ? { eventId } : {}),
        planned: Number(planned) || 0,
        paid: Number(paid) || 0,
        source,
      })
    } else if (kind === 'quota') {
      const next = {
        pasangan: Number(limits.pasangan) || 0,
        ortu_a: Number(limits.ortu_a) || 0,
        ortu_b: Number(limits.ortu_b) || 0,
      }
      // One quota record per couple; editing replaces the numbers in place so the
      // history does not fill up with near-identical rows.
      if (quotaRecord) await patch('wedding', quotaRecord.id, next)
      else await add({ kind: 'wed_quota', ...next })
    }
    reset()
    onClose()
  }

  const eventPicker = (
    <Field label={t('wedding2.fEvent')} hint={t('common.optional')}>
      {(p) => (
        <select {...p} value={eventId} onChange={(e) => setEventId(e.target.value)}>
          <option value="">{t('wedding2.allEvents')}</option>
          {events.map((e) => (
            <option key={e.id} value={e.id}>
              {e.name}
            </option>
          ))}
        </select>
      )}
    </Field>
  )

  const moneyField = (labelKey: Parameters<TFunction>[0], value: string, set: (v: string) => void) => (
    <Field label={t(labelKey)} hint={t('common.optional')}>
      {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={value} onChange={(e) => set(e.target.value)} />}
    </Field>
  )

  return (
    <Sheet open={kind !== null} onClose={onClose} title={kind ? t(`wedding2.sheet.${kind}` as const) : ''}>
      <div className="stack">
        {kind === 'event' && (
          <>
            <Field label={t('wedding2.fType')}>
              {(p) => (
                <select {...p} value={eventType} onChange={(e) => setEventType(e.target.value as EventType)}>
                  {EVENT_TYPES.map((x) => (
                    <option key={x} value={x}>
                      {t(`wedding2.evt.${x}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
            <Field label={t('wedding2.fLabel')} hint={t('wedding2.fLabelHint')}>
              {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fDate')} hint={t('common.optional')}>
              {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fVenue')} hint={t('common.optional')}>
              {(p) => <input {...p} type="text" value={venue} onChange={(e) => setVenue(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fPic')} hint={t('wedding2.fPicHint')}>
              {(p) => <input {...p} type="text" value={pic} onChange={(e) => setPic(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fNote')} hint={t('common.optional')}>
              {(p) => <textarea {...p} value={note} onChange={(e) => setNote(e.target.value)} />}
            </Field>
          </>
        )}

        {kind === 'rundown' && (
          <>
            <Field label={t('wedding2.fTime')}>
              {(p) => <input {...p} type="time" value={time} onChange={(e) => setTime(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fWhat')}>
              {(p) => <input {...p} type="text" value={what} onChange={(e) => setWhat(e.target.value)} />}
            </Field>
          </>
        )}

        {kind === 'guest' && (
          <>
            <Field label={t('wedding2.fName')}>
              {(p) => <input {...p} type="text" value={name} onChange={(e) => setName(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fPax')}>
              {(p) => <input {...p} type="number" min="1" inputMode="numeric" value={pax} onChange={(e) => setPax(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fQuota')}>
              {(p) => (
                <select {...p} value={quotaSide} onChange={(e) => setQuotaSide(e.target.value as QuotaSide)}>
                  {QUOTA_SIDES.map((s) => (
                    <option key={s} value={s}>
                      {t(`wedding2.quota.${s}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
          </>
        )}

        {kind === 'vendor' && (
          <>
            <Field label={t('wedding2.fVendorName')}>
              {(p) => <input {...p} type="text" value={name} onChange={(e) => setName(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fCategory')} hint={t('wedding2.fCategoryHint')}>
              {(p) => <input {...p} type="text" value={category} onChange={(e) => setCategory(e.target.value)} />}
            </Field>
            {eventPicker}
            {moneyField('wedding2.fQuote', quote, setQuote)}
            {moneyField('wedding2.fBooking', booking, setBooking)}
            {moneyField('wedding2.fDp', dp, setDp)}
            {moneyField('wedding2.fTermin', termin, setTermin)}
            {moneyField('wedding2.fPelunasan', pelunasan, setPelunasan)}
            <Field label={t('wedding2.fVendorStatus')}>
              {(p) => (
                <select {...p} value={status} onChange={(e) => setStatus(e.target.value as VendorState)}>
                  {VENDOR_STATES.map((s) => (
                    <option key={s} value={s}>
                      {t(`wedding2.vstat.${s}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
          </>
        )}

        {kind === 'budget' && (
          <>
            <Field label={t('wedding2.fBudgetLabel')}>
              {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
            </Field>
            {eventPicker}
            <Field label={t('wedding2.fPlanned')}>
              {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={planned} onChange={(e) => setPlanned(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fPaid')} hint={t('common.optional')}>
              {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={paid} onChange={(e) => setPaid(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fSource')}>
              {(p) => (
                <select {...p} value={source} onChange={(e) => setSource(e.target.value as FundSource)}>
                  {FUND_SOURCES.map((s) => (
                    <option key={s} value={s}>
                      {t(`wedding2.src.${s}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
          </>
        )}

        {kind === 'quota' && (
          <>
            <p className="card__hint">{t('wedding2.quotaHint')}</p>
            {QUOTA_SIDES.map((s) => (
              <Field key={s} label={t(`wedding2.quota.${s}` as const)}>
                {(p) => (
                  <input
                    {...p}
                    type="number"
                    min="0"
                    inputMode="numeric"
                    value={limits[s]}
                    onChange={(e) => setLimits((prev) => ({ ...prev, [s]: e.target.value }))}
                  />
                )}
              </Field>
            ))}
          </>
        )}

        <button className="btn btn--block" onClick={save}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
