import type { Owned } from '@/types/domain'

/**
 * Extra `wedding` store kinds for the multi-event planner (WED-06).
 *
 * These live here rather than in `types/domain.ts` because the shared file is
 * owned by another track. The store already discriminates on `kind` and the
 * Dexie schema (`wedding: 'id, ownerProfileId, kind, status, deletedAt'`) is
 * shape-agnostic, so new kinds need no migration — only new readers.
 *
 * Every kind below is prefixed `wed_` so it can never collide with the original
 * Phase 9 kinds (`readiness`, `wedding_task`, `vendor`, `guest`,
 * `wedding_budget`), which keep working untouched.
 */

/** Rangkaian acara pernikahan Indonesia. `lainnya` covers regional adat we do not name. */
export const EVENT_TYPES = [
  'lamaran',
  'sangjit',
  'pengajian',
  'siraman',
  'midodareni',
  'akad',
  'pemberkatan',
  'resepsi',
  'ngunduh_mantu',
  'lainnya',
] as const
export type EventType = (typeof EVENT_TYPES)[number]

/** Who a guest is counted against. Two parent sides, never named "his/hers". */
export const QUOTA_SIDES = ['pasangan', 'ortu_a', 'ortu_b'] as const
export type QuotaSide = (typeof QUOTA_SIDES)[number]

export const FUND_SOURCES = ['pasangan', 'ortu_a', 'ortu_b', 'patungan'] as const
export type FundSource = (typeof FUND_SOURCES)[number]

export const RSVP_STATES = ['belum', 'ya', 'ragu', 'nggak'] as const
export type Rsvp = (typeof RSVP_STATES)[number]

/**
 * Invitation delivery lifecycle (W14). Deliberately a different axis from `Rsvp`:
 * this is how far the invitation *got*, not whether they will come. `rsvp` here
 * means "they have replied" — the reply's content (headcount, diet) lives on the
 * guest's own `pax`/`diet`, so a reply never needs a second record.
 */
export const INVITE_STATES = ['belum', 'terkirim', 'dibuka', 'rsvp'] as const
export type InviteStatus = (typeof INVITE_STATES)[number]

export const VENDOR_STATES = ['dilirik', 'ditanya', 'deal', 'batal'] as const
export type VendorState = (typeof VENDOR_STATES)[number]

/**
 * Kinds of milestone on a vendor's payment schedule (W08/W10). `kontrak` carries
 * no money of its own — it is the signing date, which needs a reminder just as
 * much as a payment does.
 */
export const PAY_MILESTONES = ['kontrak', 'dp', 'termin', 'pelunasan', 'lainnya'] as const
export type PayMilestone = (typeof PAY_MILESTONES)[number]

/**
 * How big the party is. It changes *which* checklist steps exist (WED-07), not
 * how good the wedding is — there is no recommended scale and no verdict on the
 * one you pick.
 */
export const EVENT_SCALES = ['intim', 'sedang', 'besar'] as const
export type EventScale = (typeof EVENT_SCALES)[number]

/**
 * Who is holding a checklist step. Two independent axes on purpose: a step can
 * sit with one partner *and* with one family at the same time ("kamu urus
 * suratnya, keluarga sebelah yang bawa"). Neither axis is ever scored or
 * compared — `ownerLoad()` counts open steps so nobody silently carries
 * everything, and that is the whole of it.
 */
export const PARTNER_OWNERS = ['a', 'b', 'bareng'] as const
export type PartnerOwner = (typeof PARTNER_OWNERS)[number]

export const FAMILY_OWNERS = ['ortu_a', 'ortu_b', 'bareng'] as const
export type FamilyOwner = (typeof FAMILY_OWNERS)[number]

/**
 * Who a rundown line is on (W23). Not a job title to fill — it is "who must be
 * where at this minute", so `keluarga` (the families) sits next to `mc` and
 * `vendor`. `lainnya` keeps any adat role we do not name. The actual person is
 * free text in `who`, because on the day it is usually an uncle, not an app user.
 */
export const RUNDOWN_ROLES = ['mc', 'foto', 'rias', 'keluarga', 'vendor', 'lainnya'] as const
export type RundownRole = (typeof RUNDOWN_ROLES)[number]

/**
 * How loud a D-day issue is (W25). Deliberately calm words, not a red-alert
 * scale: a wedding-day log is for noticing, not for blame. `catatan` is just a
 * note, `kendala` is something to handle, `penting` is handle-now.
 */
export const ISSUE_SEVERITY = ['catatan', 'kendala', 'penting'] as const
export type IssueSeverity = (typeof ISSUE_SEVERITY)[number]

/**
 * How far a piece of attire has got (W28). A plain lifecycle, never a verdict on
 * anyone's look: `belum` not started, `diukur` measured, `proses` being made,
 * `siap` ready to wear.
 */
export const ATTIRE_STATES = ['belum', 'diukur', 'proses', 'siap'] as const
export type AttireStatus = (typeof ATTIRE_STATES)[number]

/**
 * Which authority a legal/administrative requirement sits with (W32). These are
 * *institutions*, not requirements — TemuDua never invents the actual list of
 * papers or dates KUA/Dukcapil ask for, it only gives you buckets to write your
 * own into. `lainnya` catches adat/agama steps we do not name.
 */
export const REQ_CATEGORIES = ['kua', 'sipil', 'agama', 'lainnya'] as const
export type ReqCategory = (typeof REQ_CATEGORIES)[number]

/** Plain lifecycle for a requirement (W32). Never a verdict, just how far it got. */
export const REQ_STATES = ['belum', 'proses', 'beres'] as const
export type ReqStatus = (typeof REQ_STATES)[number]

/**
 * How badly a shot is wanted (W33). Two buckets only: `wajib` is the must-haves
 * the couple would regret missing, `bonus` is if-there-is-time. Not a ranking of
 * anyone or anything — just what to shoot first when the light is going.
 */
export const SHOT_PRIORITY = ['wajib', 'bonus'] as const
export type ShotPriority = (typeof SHOT_PRIORITY)[number]

/**
 * Buckets for the after-the-party checklist (W36). Not a workflow and never a
 * verdict — just where a leftover task sorts. `terimakasih` is thank-yous,
 * `pelunasan` the last vendor balances, `administrasi` the name/document changes,
 * `lainnya` anything adat/regional we do not name. TemuDua ships ZERO of these
 * pre-filled: it never invents which papers your name change needs.
 */
export const POST_CATEGORIES = ['terimakasih', 'pelunasan', 'administrasi', 'lainnya'] as const
export type PostCategory = (typeof POST_CATEGORIES)[number]

export type PlannerRecord = Owned<
  | {
      kind: 'wed_event'
      eventType: EventType
      /** Free label for `lainnya`, or a nickname the couple actually uses. */
      label?: string
      /**
       * Only meaningful when `dependsOn` is unset. A dependent event's date is
       * derived every read by `resolveEventDates()` instead of copied, so moving
       * the akad can never leave a stale siraman date behind in the store.
       */
      date?: string
      venue?: string
      /** Penanggung jawab — free text, because it is often an uncle, not an app user. */
      pic?: string
      note?: string
      /** Id of the event this one hangs off (WED-07 dependency rules). */
      dependsOn?: string
      /** Days from `dependsOn`'s date. Negative is before it. Defaults to 0. */
      offsetDays?: number
    }
  /**
   * One line of an event's minute-by-minute rundown (W22). `time` is "HH:MM".
   * The extra fields are all optional so the Planner's quick-add (time + what)
   * and the D-day builder (which also sets duration, role, and who) write the
   * same kind. `done` lets the command center cross a line off on the day; the
   * live current/next item is still derived from the clock, never from `done`.
   */
  | {
      kind: 'wed_rundown'
      eventId: string
      time: string
      what: string
      /** Minutes this line is meant to take (W22). Absent = open-ended. */
      durationMin?: number
      /** Which role must be in place for this line (W23). */
      role?: RundownRole
      /** The actual person on it — free text, often not an app user. */
      who?: string
      /** Crossed off on the day. Does not move the clock-derived "current". */
      done?: boolean
    }
  /**
   * A single wedding-day issue (W25). Created `C2_shared_ops` — a shared ops log,
   * not a private one. `at` is when it was noted, `resolvedAt` absent means still
   * open. No blame field and no owner-to-point-at: it records what happened, not
   * who is at fault.
   */
  | {
      kind: 'wed_issue'
      eventId?: string
      at: string
      what: string
      severity: IssueSeverity
      resolvedAt?: string
      note?: string
    }
  /**
   * The catering headcount the couple actually ordered against (W21). One row,
   * replaced in place. Stored rather than derived because it is a separately
   * negotiated number with the caterer, not a function of the RSVP list — the
   * reconciliation compares the two instead of pretending they must match.
   */
  | { kind: 'wed_catering'; pax: number; note?: string }
  | {
      kind: 'wed_guest2'
      name: string
      quota: QuotaSide
      pax: number
      /** eventId → RSVP. Absent key means `belum`; we do not pre-write rows. */
      rsvp: Record<string, Rsvp>
      note?: string
      /** W11: how you know them — free text ("om dari Bandung", "teman kantor"). */
      relationship?: string
      /** W11: whose circle they came through — free text ("dari Pakde Bambang",
       *  "kolega Ibu"). Attribution so a side can see its own list, never a score. */
      origin?: string
      /** W14: how far the invitation got. Absent = `belum`; no row just to say so. */
      invite?: InviteStatus
      /** W15: dietary / halal notes — free text, only what the guest told you. */
      diet?: string
      /** W16: id of the `wed_table` this guest sits at. Absent = not seated yet. */
      table?: string
      /** W20: when this guest checked in at the door. Absent = not yet arrived. */
      checkedInAt?: string
    }
  | {
      kind: 'wed_vendor2'
      name: string
      category: string
      /** Undefined means the vendor serves every event. */
      eventId?: string
      quote?: number
      bookingFee?: number
      dp?: number
      termin?: number
      pelunasan?: number
      status: VendorState
      note?: string
    }
  | {
      kind: 'wed_budget2'
      label: string
      eventId?: string
      planned: number
      /**
       * Money already locked in by a signed quote or contract but not yet handed
       * over (W06). Optional: rows written before this field existed simply have
       * no commitment recorded, and `budgetRollup()` treats anything already paid
       * as committed, so the number never reads lower than reality.
       */
      committed?: number
      paid: number
      source: FundSource
    }
  /**
   * Where the money comes in from (W07). One row per pot per pledge, so "ortu_a
   * janji 50jt, baru masuk 20jt" and a later top-up are two rows, not an edit
   * that erases the first promise. Kept apart from `wed_budget2.source`, which
   * only says which pot an *expense* is drawn against.
   */
  | {
      kind: 'wed_fund'
      source: FundSource
      label?: string
      /** Promised. */
      pledged: number
      /** Actually in hand. Never assumed equal to `pledged`. */
      received: number
      note?: string
    }
  /**
   * One line of a vendor's payment schedule (W08), and the thing W10 reminds you
   * about. `amount` is 0 for a `kontrak` row. `paidAt` absent means outstanding —
   * there is no separate boolean to fall out of sync with the date.
   */
  | {
      kind: 'wed_pay'
      vendorId: string
      milestone: PayMilestone
      label?: string
      amount: number
      dueDate?: string
      paidAt?: string
      note?: string
    }
  | { kind: 'wed_quota'; pasangan: number; ortu_a: number; ortu_b: number }
  /**
   * Only the *state* of a generated checklist row is stored. The rows
   * themselves are recomputed from the wedding date every render, so moving the
   * date does not orphan a hundred stale records.
   */
  | { kind: 'wed_check'; checkKey: string; status: 'done' | 'skip' }
  /** Chosen party scale. One row per couple, replaced in place when it changes. */
  | { kind: 'wed_plan'; scale: EventScale }
  /**
   * Who holds a checklist step. Kept apart from `wed_check` so assigning a step
   * does not require also declaring it done or skipped — and so an unassigned
   * step costs no row at all.
   */
  | { kind: 'wed_own'; checkKey: string; owner?: PartnerOwner; family?: FamilyOwner }
  /**
   * A table at the reception (W16). `capacity` is seats; a guest is seated by
   * pointing their `wed_guest2.table` at this id, so a table holds no list of
   * its own to fall out of sync with the roster.
   */
  | { kind: 'wed_table'; label: string; capacity: number; eventId?: string; note?: string }
  /**
   * A souvenir / hantaran line (W17). `ordered` is how many you made; `perGuest`
   * (default 1) is how many each guest row gets; `received` is how many actually
   * arrived from the vendor. Reconciliation against the RSVP range is derived,
   * never stored.
   */
  | {
      kind: 'wed_souvenir'
      name: string
      ordered: number
      perGuest?: number
      received?: number
      eventId?: string
      note?: string
    }
  /**
   * An angpao / gift record (W18). Created `C1_personal` so it is private by
   * default and only the owner may widen it. `amount` for cash, `item` for a
   * non-cash gift; a row may carry both. `guestId` links it to a roster entry
   * when known, but a giver who is not on the list is just free text.
   */
  | {
      kind: 'wed_gift'
      giver: string
      guestId?: string
      amount?: number
      item?: string
      note?: string
    }
  /**
   * A document reference (W27). No scan is ever stored — only that the document
   * exists, an optional identifier, and where the physical/soft copy lives. Kept
   * `C2_shared_ops` like household docs: berkas nikah is a couple task, not a
   * secret. `docKind` is a free label the couple chooses, so the app never has to
   * invent a list of official form names it cannot keep correct.
   */
  | {
      kind: 'wed_doc'
      name: string
      docKind: string
      /** Optional identifier the couple typed. Carries a "don't store the scan" warning in the UI. */
      ref?: string
      /** Where it physically/digitally is ("map merah, lemari Ibu"; "folder Drive"). */
      where?: string
      expiresAt?: string
      note?: string
    }
  /**
   * One attire item, per person and optionally per event (W28). `person` and
   * `item` are free text — it is usually "Ibu", "penghulu", "seragam keluarga",
   * not an app user. `status` is a plain lifecycle, never scored.
   */
  | {
      kind: 'wed_attire'
      person: string
      eventId?: string
      item: string
      status: AttireStatus
      /** Who is making/renting it — free text. */
      vendor?: string
      note?: string
    }
  /**
   * One prep/beauty task on the D-day critical path (W29). `durationMin` is how
   * long it takes; `order` sequences a person's tasks (lower runs first). The
   * schedule back-solves start times from `wed_daySetup.readyBy`, so it is never
   * stored — moving the ready-by time moves every start with no stale row.
   */
  | {
      kind: 'wed_prep'
      person: string
      task: string
      durationMin: number
      /** Sequence within a person's chain. Absent sorts last, stably. */
      order?: number
      note?: string
    }
  /**
   * D-day timing config (W29). One row, replaced in place. `readyBy` is the "must
   * be fully ready by" time ("HH:MM") the prep chain is solved back from.
   */
  | { kind: 'wed_daySetup'; readyBy?: string }
  /**
   * One transport leg (W30). `capacity` seats vs `needPax` heads is compared, a
   * shortfall surfaced but never solved for you. `mode`, `from`, `to`, `depart`
   * ("HH:MM") are all free/optional so a becak, a bus, and a family car all fit.
   */
  | {
      kind: 'wed_transport'
      label: string
      eventId?: string
      mode?: string
      capacity?: number
      needPax?: number
      depart?: string
      from?: string
      to?: string
      note?: string
    }
  /**
   * A place out-of-town guests can stay (W31). Seats-against-heads shaped like a
   * transport leg: `capacity` beds vs `needPax` guests you plan to lodge here.
   * The reconciliation surfaces a shortfall, never books a room. `checkIn`/
   * `checkOut` are plain dates; everything but `label` is optional so a hotel
   * block and Grandma's spare room both fit.
   */
  | {
      kind: 'wed_lodging'
      label: string
      eventId?: string
      capacity?: number
      needPax?: number
      address?: string
      checkIn?: string
      checkOut?: string
      note?: string
    }
  /**
   * One legal/administrative requirement the couple typed themselves (W32).
   * TemuDua ships ZERO of these and invents no dates — `label` is always the
   * couple's own words, `category` only sorts it under an institution. `due` is a
   * date the couple entered from the real authority, never one the app guessed.
   */
  | {
      kind: 'wed_req'
      label: string
      category: ReqCategory
      status: ReqStatus
      /** A date the couple copied from KUA/Dukcapil. Never app-generated. */
      due?: string
      where?: string
      note?: string
    }
  /**
   * One line of the photo/video shot list (W33). `subjects` is who to gather
   * ("both mums", "college friends") — free text, usually not app users. `done`
   * crosses it off on the day.
   */
  | {
      kind: 'wed_shot'
      desc: string
      eventId?: string
      priority: ShotPriority
      subjects?: string
      done?: boolean
      note?: string
    }
  /**
   * A music / moment cue (W34). `moment` is what is happening ("pengantin masuk"),
   * `track` the song (free text), `cueBy` who triggers it or where it plays from.
   * `time` is "HH:MM" when known, so cues can sit on the same clock as the rundown.
   */
  | {
      kind: 'wed_cue'
      moment: string
      eventId?: string
      track?: string
      cueBy?: string
      time?: string
      note?: string
    }
  /**
   * One weather / outdoor contingency (W35). TemuDua forecasts NOTHING — it stores
   * no weather data and predicts no rain. `label` is what is exposed ("resepsi di
   * taman"), `risk` the couple's own worry, `plan` their own backup, `ready` true
   * once that backup is actually arranged. A risk with no `plan` is the whole point.
   */
  | {
      kind: 'wed_contingency'
      label: string
      eventId?: string
      risk?: string
      plan?: string
      ready?: boolean
      note?: string
    }
  /**
   * One post-wedding task (W36). A plain checklist — thank-yous, the last vendor
   * balance, the name/document changes — never a scored workflow. `done` crosses
   * it off; `due` is a date the couple typed, never one the app guessed.
   */
  | {
      kind: 'wed_post'
      task: string
      category: PostCategory
      done?: boolean
      due?: string
      note?: string
    }
>

export type PlannerOf<K extends PlannerRecord['kind']> = Extract<PlannerRecord, { kind: K }>
