import { useEffect, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n, type TFunction } from '@/i18n'
import { confirmedHeadcount, inviteFunnel, quotaWarnings, type QuotaWarning } from './guests'
import {
  INVITE_STATES,
  QUOTA_SIDES,
  type InviteStatus,
  type PlannerOf,
  type PlannerRecord,
  type QuotaSide,
} from './types'

/**
 * Guest list (W11–W15).
 *
 * A roster with relationship, side and family-of-origin attribution (W11); the
 * per-family quota the two families negotiate and can both see (W12); warnings
 * that name the *quota* and never a guest (W13); an invitation pipeline
 * belum → terkirim → dibuka → RSVP (W14); and the RSVP itself as headcount plus
 * dietary/halal notes (W15).
 *
 * It shares `wed_guest2`/`wed_quota` with the WED-06 planner, so the numbers on
 * both screens are the same record read twice, never two lists to reconcile.
 */

const sideLabel = (t: TFunction, s: QuotaSide) => t(`wedding2.gst.sideName.${s}` as const)

export function GuestsTab({ me }: { me: string }) {
  const { t } = useI18n()
  const [sheet, setSheet] = useState<'guest' | 'quota' | null>(null)
  const [editId, setEditId] = useState<string | null>(null)
  const rows = useOwned<PlannerRecord>('wedding', me)

  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is PlannerOf<K> => r.kind === kind)

  const guests = of('wed_guest2')
  const quotaRecord = of('wed_quota').at(-1)
  const quota = quotaRecord
    ? { pasangan: quotaRecord.pasangan, ortu_a: quotaRecord.ortu_a, ortu_b: quotaRecord.ortu_b }
    : undefined

  const warnings = quotaWarnings(guests, quota)
  const funnel = inviteFunnel(guests)
  const confirmed = confirmedHeadcount(guests)

  // Group by side so each family reads its own list at a glance (W11).
  const bySide = (side: QuotaSide) =>
    guests
      .filter((g) => g.quota === side)
      .sort((a, b) => a.name.localeCompare(b.name))

  const openEdit = (id: string) => {
    setEditId(id)
    setSheet('guest')
  }

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.gst.intro')}</p>

      {/* Quota (W12) + warnings (W13) --------------------------------- */}
      <Card
        title={t('wedding2.quotaCard')}
        icon="shared"
        hint={t('wedding2.quotaHint')}
        action={
          <button className="btn btn--sm" onClick={() => setSheet('quota')}>
            <Icon name="settings" size={16} /> {t('wedding2.editQuota')}
          </button>
        }
      >
        <ul className="list">
          {warnings.map((row) => (
            <li key={row.side} className="list__item">
              <Icon name="shared" size={18} />
              <span className="grow">{t(`wedding2.quota.${row.side}` as const)}</span>
              <span className="chip">
                {row.limit > 0
                  ? t('wedding2.quotaRow', { used: row.used, limit: row.limit })
                  : t('wedding2.quotaNoLimit', { used: row.used })}
              </span>
              {row.level === 'over' && <span className="chip chip--yellow">{t('wedding2.quotaOver', { n: -row.remaining })}</span>}
            </li>
          ))}
        </ul>
        {warnings.filter((w) => w.level !== 'ok').map((w) => (
          <p key={w.side} className="banner">
            <Icon name="info" size={16} /> {warnLine(t, w)}
          </p>
        ))}
        <p className="disclaimer">{t('wedding2.gst.caveat')}</p>
      </Card>

      {/* Invitation status (W14) + confirmed headcount (W15) ---------- */}
      <Card title={t('wedding2.gst.inviteCard')} icon="consent" hint={t('wedding2.gst.inviteHint')}>
        <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
          {INVITE_STATES.map((s) => (
            <span key={s} className="chip">
              {t(`wedding2.gst.inv.${s}` as const)} · {funnel[s]}
            </span>
          ))}
        </div>
        <p className="card__hint">
          <Icon name="check" size={16} /> {t('wedding2.gst.confirmed', { n: confirmed })}
        </p>
        <p className="card__hint">{t('wedding2.gst.confirmedHint')}</p>
      </Card>

      {/* Roster (W11 / W14 / W15) ------------------------------------- */}
      <Card
        title={t('wedding2.gst.roster')}
        icon="family"
        action={
          <button className="btn btn--sm" onClick={() => { setEditId(null); setSheet('guest') }}>
            <Icon name="plus" size={16} /> {t('wedding2.addGuest')}
          </button>
        }
      >
        {guests.length === 0 ? (
          <EmptyState icon="family" title={t('wedding2.noGuests')} hint={t('wedding2.noGuestsHint')} />
        ) : (
          QUOTA_SIDES.map((side) => {
            const list = bySide(side)
            if (list.length === 0) return null
            return (
              <div key={side} className="stack stack--tight" style={{ marginBottom: 'var(--space-3)' }}>
                <strong style={{ fontSize: 13 }}>{t(`wedding2.quota.${side}` as const)}</strong>
                <ul className="list">
                  {list.map((g) => (
                    <li key={g.id} className="list__item">
                      <span className="grow stack stack--tight">
                        <button
                          className="btn btn--ghost btn--sm"
                          style={{ justifyContent: 'flex-start', padding: 0, fontWeight: 600, fontSize: 14 }}
                          onClick={() => openEdit(g.id)}
                        >
                          {g.name}
                        </button>
                        <span className="row" style={{ flexWrap: 'wrap', gap: 4 }}>
                          <span className="chip">{t('wedding2.fPax')}: {g.pax}</span>
                          {g.relationship && <span className="chip">{g.relationship}</span>}
                          {g.origin && <span className="card__hint">{t('wedding2.gst.originLine', { who: g.origin })}</span>}
                        </span>
                        {g.diet && <span className="card__hint">{t('wedding2.gst.dietLine', { note: g.diet })}</span>}
                      </span>
                      <label>
                        <span className="visually-hidden">{`${g.name} — ${t('wedding2.gst.fInvite')}`}</span>
                        <select
                          value={g.invite ?? 'belum'}
                          style={{ minHeight: 36, fontSize: 13 }}
                          onChange={(ev) => patch('wedding', g.id, { invite: ev.target.value as InviteStatus })}
                        >
                          {INVITE_STATES.map((s) => (
                            <option key={s} value={s}>
                              {t(`wedding2.gst.inv.${s}` as const)}
                            </option>
                          ))}
                        </select>
                      </label>
                      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', g.id, me)}>
                        <Icon name="close" size={16} label={t('common.deleteX', { name: g.name })} />
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )
          })
        )}
      </Card>

      <GuestSheet
        open={sheet}
        editing={editId ? guests.find((g) => g.id === editId) : undefined}
        onClose={() => { setSheet(null); setEditId(null) }}
        me={me}
        quotaRecord={quotaRecord}
      />
    </div>
  )
}

function warnLine(t: TFunction, w: QuotaWarning): string {
  const side = sideLabel(t, w.side)
  if (w.level === 'over') return t('wedding2.gst.warnOver', { side, n: -w.remaining })
  if (w.level === 'full') return t('wedding2.gst.warnFull', { side })
  return t('wedding2.gst.warnNear', { side, n: w.remaining })
}

function GuestSheet({
  open,
  editing,
  onClose,
  me,
  quotaRecord,
}: {
  open: 'guest' | 'quota' | null
  editing?: PlannerOf<'wed_guest2'>
  onClose: () => void
  me: string
  quotaRecord: PlannerOf<'wed_quota'> | undefined
}) {
  const { t } = useI18n()
  const [name, setName] = useState('')
  const [quotaSide, setQuotaSide] = useState<QuotaSide>('pasangan')
  const [relationship, setRelationship] = useState('')
  const [origin, setOrigin] = useState('')
  const [pax, setPax] = useState('1')
  const [invite, setInvite] = useState<InviteStatus>('belum')
  const [diet, setDiet] = useState('')
  const [limits, setLimits] = useState<Record<QuotaSide, string>>({ pasangan: '', ortu_a: '', ortu_b: '' })

  // Seed the form when a sheet opens. Keyed on the record id (or 'new'/'quota')
  // so a live-query refresh mid-typing does not wipe the fields.
  const seedKey = open === 'quota' ? 'quota' : (editing?.id ?? 'new')
  useEffect(() => {
    if (open === 'quota') {
      setLimits({
        pasangan: quotaRecord ? String(quotaRecord.pasangan) : '',
        ortu_a: quotaRecord ? String(quotaRecord.ortu_a) : '',
        ortu_b: quotaRecord ? String(quotaRecord.ortu_b) : '',
      })
      return
    }
    if (open === 'guest') {
      setName(editing?.name ?? '')
      setQuotaSide(editing?.quota ?? 'pasangan')
      setRelationship(editing?.relationship ?? '')
      setOrigin(editing?.origin ?? '')
      setPax(String(editing?.pax ?? 1))
      setInvite(editing?.invite ?? 'belum')
      setDiet(editing?.diet ?? '')
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seedKey, open])

  async function save() {
    if (open === 'guest') {
      if (!name.trim()) return
      const fields = {
        name: name.trim(),
        quota: quotaSide,
        pax: Math.max(1, Number(pax) || 1),
        invite,
        ...(relationship.trim() ? { relationship: relationship.trim() } : {}),
        ...(origin.trim() ? { origin: origin.trim() } : {}),
        ...(diet.trim() ? { diet: diet.trim() } : {}),
      }
      if (editing) {
        // Clear fields emptied in the edit rather than leaving a stale value behind.
        await patch('wedding', editing.id, {
          ...fields,
          relationship: relationship.trim() || undefined,
          origin: origin.trim() || undefined,
          diet: diet.trim() || undefined,
        })
      } else {
        await db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), kind: 'wed_guest2', rsvp: {}, ...fields } as never)
      }
    } else if (open === 'quota') {
      const next = {
        pasangan: Number(limits.pasangan) || 0,
        ortu_a: Number(limits.ortu_a) || 0,
        ortu_b: Number(limits.ortu_b) || 0,
      }
      if (quotaRecord) await patch('wedding', quotaRecord.id, next)
      else await db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), kind: 'wed_quota', ...next } as never)
    }
    onClose()
  }

  const title =
    open === 'quota'
      ? t('wedding2.sheet.quota')
      : editing
        ? t('wedding2.gst.sheet.edit')
        : t('wedding2.gst.sheet.guest')

  return (
    <Sheet open={open !== null} onClose={onClose} title={title}>
      <div className="stack">
        {open === 'guest' && (
          <>
            <Field label={t('wedding2.fName')}>
              {(p) => <input {...p} type="text" value={name} onChange={(e) => setName(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fQuota')}>
              {(p) => (
                <select {...p} value={quotaSide} onChange={(e) => setQuotaSide(e.target.value as QuotaSide)}>
                  {QUOTA_SIDES.map((s) => (
                    <option key={s} value={s}>
                      {t(`wedding2.quota.${s}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
            <Field label={t('wedding2.gst.fRelationship')} hint={t('wedding2.gst.fRelationshipHint')}>
              {(p) => <input {...p} type="text" value={relationship} onChange={(e) => setRelationship(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.gst.fOrigin')} hint={t('wedding2.gst.fOriginHint')}>
              {(p) => <input {...p} type="text" value={origin} onChange={(e) => setOrigin(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fPax')}>
              {(p) => <input {...p} type="number" min="1" inputMode="numeric" value={pax} onChange={(e) => setPax(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.gst.fInvite')}>
              {(p) => (
                <select {...p} value={invite} onChange={(e) => setInvite(e.target.value as InviteStatus)}>
                  {INVITE_STATES.map((s) => (
                    <option key={s} value={s}>
                      {t(`wedding2.gst.inv.${s}` as const)}
                    </option>
                  ))}
                </select>
              )}
            </Field>
            <Field label={t('wedding2.gst.fDiet')} hint={t('wedding2.gst.fDietHint')}>
              {(p) => <input {...p} type="text" value={diet} onChange={(e) => setDiet(e.target.value)} />}
            </Field>
          </>
        )}

        {open === 'quota' && (
          <>
            <p className="card__hint">{t('wedding2.quotaHint')}</p>
            {QUOTA_SIDES.map((s) => (
              <Field key={s} label={t(`wedding2.quota.${s}` as const)}>
                {(p) => (
                  <input
                    {...p}
                    type="number"
                    min="0"
                    inputMode="numeric"
                    value={limits[s]}
                    onChange={(e) => setLimits((prev) => ({ ...prev, [s]: e.target.value }))}
                  />
                )}
              </Field>
            ))}
          </>
        )}

        <button className="btn btn--block" onClick={save}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
