import { useEffect, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n } from '@/i18n'
import { confirmedHeadcount } from './guests'
import { seatingPlan, type SeatLevel } from './seating'
import { QUOTA_SIDES, type PlannerOf, type PlannerRecord } from './types'

/**
 * Seating & table assignment (W16).
 *
 * Tables carry a capacity; a guest is seated by pointing at a table, so there is
 * one source of truth (the roster) and a table never keeps a stale list. The
 * summary reconciles total capacity against the confirmed-RSVP floor — never a
 * guess dressed up as the real number.
 */

const LEVEL_CHIP: Record<SeatLevel, string> = {
  empty: 'chip',
  ok: 'chip chip--mint',
  full: 'chip chip--blue',
  over: 'chip chip--yellow',
}

export function SeatingTab({ me }: { me: string }) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const [editId, setEditId] = useState<string | null>(null)
  const rows = useOwned<PlannerRecord>('wedding', me)

  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is PlannerOf<K> => r.kind === kind)

  const tables = of('wed_table')
  const guests = of('wed_guest2')
  const plan = seatingPlan(tables, guests)
  const confirmed = confirmedHeadcount(guests)
  const occ = (id: string) => plan.tables.find((tb) => tb.tableId === id)!

  const tableName = (id: string) => tables.find((tb) => tb.id === id)?.label ?? ''
  const unseated = guests
    .filter((g) => !g.table || !tables.some((tb) => tb.id === g.table))
    .sort((a, b) => a.name.localeCompare(b.name))

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.seat.intro')}</p>

      {/* Reconciliation vs RSVP -------------------------------------- */}
      <Card title={t('wedding2.seat.summary')} icon="shared">
        <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
          <span className="chip">{t('wedding2.seat.capacity', { n: plan.totalCapacity })}</span>
          <span className="chip chip--mint">{t('wedding2.seat.seated', { n: plan.seatedPax })}</span>
          {plan.unassignedGuests > 0 && (
            <span className="chip chip--yellow">
              {t('wedding2.seat.unassigned', { g: plan.unassignedGuests, p: plan.unassignedPax })}
            </span>
          )}
        </div>
        <p className="card__hint">{t('wedding2.seat.vsConfirmed', { n: confirmed })}</p>
        {plan.totalCapacity < confirmed && (
          <p className="banner">
            <Icon name="info" size={16} /> {t('wedding2.seat.shortCapacity', { n: confirmed - plan.totalCapacity })}
          </p>
        )}
        <p className="disclaimer">{t('wedding2.seat.caveat')}</p>
      </Card>

      {/* Tables ------------------------------------------------------- */}
      <Card
        title={t('wedding2.seat.tables')}
        icon="family"
        action={
          <button className="btn btn--sm" onClick={() => { setEditId(null); setOpen(true) }}>
            <Icon name="plus" size={16} /> {t('wedding2.seat.addTable')}
          </button>
        }
      >
        {tables.length === 0 ? (
          <EmptyState icon="family" title={t('wedding2.seat.noTables')} hint={t('wedding2.seat.noTablesHint')} />
        ) : (
          <ul className="list">
            {tables.map((tb) => {
              const o = occ(tb.id)
              const seatedHere = guests.filter((g) => g.table === tb.id)
              return (
                <li key={tb.id} className="list__item">
                  <span className="grow stack stack--tight">
                    <button
                      className="btn btn--ghost btn--sm"
                      style={{ justifyContent: 'flex-start', padding: 0, fontWeight: 600, fontSize: 14 }}
                      onClick={() => { setEditId(tb.id); setOpen(true) }}
                    >
                      {tb.label}
                    </button>
                    <span className="row" style={{ flexWrap: 'wrap', gap: 4 }}>
                      <span className={LEVEL_CHIP[o.level]}>
                        {t('wedding2.seat.occ', { seated: o.seated, cap: o.capacity })}
                      </span>
                      <span className="chip">{t('wedding2.seat.tableGuests', { n: o.guestCount })}</span>
                      {o.level === 'over' && <span className="chip chip--yellow">{t('wedding2.seat.over', { n: o.seated - o.capacity })}</span>}
                    </span>
                    {seatedHere.length > 0 && (
                      <span className="card__hint">
                        {seatedHere.map((g) => g.name).join(', ')}
                      </span>
                    )}
                    {tb.note && <span className="card__hint">{tb.note}</span>}
                  </span>
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', tb.id, me)}>
                    <Icon name="close" size={16} label={t('common.deleteX', { name: tb.label })} />
                  </button>
                </li>
              )
            })}
          </ul>
        )}
      </Card>

      {/* Assign guests ----------------------------------------------- */}
      {guests.length > 0 && (
        <Card title={t('wedding2.seat.assign')} icon="shared" hint={t('wedding2.seat.assignHint')}>
          {tables.length === 0 ? (
            <p className="card__hint">{t('wedding2.seat.needTableFirst')}</p>
          ) : unseated.length === 0 ? (
            <p className="card__hint">
              <Icon name="check" size={16} /> {t('wedding2.seat.allSeated')}
            </p>
          ) : (
            QUOTA_SIDES.map((side) => {
              const list = unseated.filter((g) => g.quota === side)
              if (list.length === 0) return null
              return (
                <div key={side} className="stack stack--tight" style={{ marginBottom: 'var(--space-3)' }}>
                  <strong style={{ fontSize: 13 }}>{t(`wedding2.quota.${side}` as const)}</strong>
                  <ul className="list">
                    {list.map((g) => (
                      <li key={g.id} className="list__item">
                        <span className="grow">{g.name} <span className="chip">{t('wedding2.fPax')}: {g.pax}</span></span>
                        <label>
                          <span className="visually-hidden">{`${g.name} — ${t('wedding2.seat.pickTable')}`}</span>
                          <select
                            value={g.table && tables.some((tb) => tb.id === g.table) ? g.table : ''}
                            style={{ minHeight: 36, fontSize: 13 }}
                            onChange={(ev) => patch('wedding', g.id, { table: ev.target.value || undefined })}
                          >
                            <option value="">{t('wedding2.seat.pickTable')}</option>
                            {tables.map((tb) => (
                              <option key={tb.id} value={tb.id}>{tb.label}</option>
                            ))}
                          </select>
                        </label>
                      </li>
                    ))}
                  </ul>
                </div>
              )
            })
          )}
        </Card>
      )}

      {/* Move a seated guest ----------------------------------------- */}
      {tables.length > 0 && guests.some((g) => g.table && tables.some((tb) => tb.id === g.table)) && (
        <Card title={t('wedding2.seat.seatedList')} icon="check">
          <ul className="list">
            {guests
              .filter((g) => g.table && tables.some((tb) => tb.id === g.table))
              .sort((a, b) => a.name.localeCompare(b.name))
              .map((g) => (
                <li key={g.id} className="list__item">
                  <span className="grow">{g.name}</span>
                  <span className="chip">{tableName(g.table!)}</span>
                  <button
                    className="btn btn--ghost btn--sm"
                    onClick={() => patch('wedding', g.id, { table: undefined })}
                  >
                    {t('wedding2.seat.unseat')}
                  </button>
                </li>
              ))}
          </ul>
        </Card>
      )}

      <TableSheet
        open={open}
        editing={editId ? tables.find((tb) => tb.id === editId) : undefined}
        onClose={() => { setOpen(false); setEditId(null) }}
        me={me}
      />
    </div>
  )
}

function TableSheet({
  open,
  editing,
  onClose,
  me,
}: {
  open: boolean
  editing?: PlannerOf<'wed_table'>
  onClose: () => void
  me: string
}) {
  const { t } = useI18n()
  const [label, setLabel] = useState('')
  const [capacity, setCapacity] = useState('8')
  const [note, setNote] = useState('')

  const seedKey = editing?.id ?? 'new'
  useEffect(() => {
    setLabel(editing?.label ?? '')
    setCapacity(String(editing?.capacity ?? 8))
    setNote(editing?.note ?? '')
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seedKey, open])

  async function save() {
    if (!label.trim()) return
    const fields = {
      label: label.trim(),
      capacity: Math.max(0, Number(capacity) || 0),
      note: note.trim() || undefined,
    }
    if (editing) await patch('wedding', editing.id, fields)
    else await db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), kind: 'wed_table', ...fields } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={editing ? t('wedding2.seat.editTable') : t('wedding2.seat.addTable')}>
      <div className="stack">
        <Field label={t('wedding2.seat.fLabel')} hint={t('wedding2.seat.fLabelHint')}>
          {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.seat.fCapacity')}>
          {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={capacity} onChange={(e) => setCapacity(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.fNote')} hint={t('common.optional')}>
          {(p) => <input {...p} type="text" value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save}>{t('common.save')}</button>
      </div>
    </Sheet>
  )
}
