import { useEffect, useRef, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { patch } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n } from '@/i18n'
import { whenLabel } from '@/i18n/format'
import { checkinCounts, makeToken, verifyCheckin, type CheckinResult } from './checkin'
import { qrMatrix } from './qr'
import type { PlannerOf, PlannerRecord } from './types'

/**
 * Guest QR codes (W19) and the door scanner (W20).
 *
 * A guest's QR encodes only a local token; verifying it is a lookup in the
 * couple's own roster, so the whole flow runs in airplane mode with no server.
 * The scanner always offers a typed/pasted fallback (works in every browser and
 * with no camera); the camera path is a progressive enhancement layered on the
 * native BarcodeDetector when the browser has it.
 */

type GuestRow = PlannerOf<'wed_guest2'>

/** QR module matrix → an inline, high-contrast SVG. Forced dark-on-light so it
 *  scans in either app theme; a theme-inverted QR would not read. */
function QrSvg({ text, size = 176 }: { text: string; size?: number }) {
  const m = qrMatrix(text)
  const n = m.length
  const quiet = 4
  const dim = n + quiet * 2
  const rects: React.ReactNode[] = []
  m.forEach((row, r) =>
    row.forEach((cell, c) => {
      if (cell) rects.push(<rect key={`${r}-${c}`} x={c + quiet} y={r + quiet} width={1} height={1} />)
    }),
  )
  return (
    <svg
      width={size}
      height={size}
      viewBox={`0 0 ${dim} ${dim}`}
      shapeRendering="crispEdges"
      role="img"
      style={{ display: 'block' }}
    >
      <rect x={0} y={0} width={dim} height={dim} fill="#fff" />
      <g fill="#000">{rects}</g>
    </svg>
  )
}

export function CheckinTab({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [qrFor, setQrFor] = useState<string | null>(null)
  const rows = useOwned<PlannerRecord>('wedding', me)
  const guests = (rows ?? []).filter((r): r is GuestRow => r.kind === 'wed_guest2')

  const counts = checkinCounts(guests)
  const qrGuest = qrFor ? guests.find((g) => g.id === qrFor) : undefined

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.chk.intro')}</p>

      {/* Live count -------------------------------------------------- */}
      <Card title={t('wedding2.chk.count')} icon="checkin">
        <p className="card__hint">
          <Icon name="check" size={16} /> {t('wedding2.chk.arrived', { n: counts.checkedIn, total: counts.total })}
        </p>
        <p className="disclaimer">{t('wedding2.chk.offline')}</p>
      </Card>

      {/* Scanner (W20) ----------------------------------------------- */}
      <Scanner guests={guests} />

      {/* QR per guest (W19) ------------------------------------------ */}
      <Card title={t('wedding2.chk.codes')} icon="consent" hint={t('wedding2.chk.codesHint')}>
        {guests.length === 0 ? (
          <EmptyState icon="family" title={t('wedding2.chk.noGuests')} hint={t('wedding2.chk.noGuestsHint')} />
        ) : (
          <ul className="list">
            {guests
              .slice()
              .sort((a, b) => a.name.localeCompare(b.name))
              .map((g) => (
                <li key={g.id} className="list__item">
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{g.name}</strong>
                    {g.checkedInAt && (
                      <span className="chip chip--mint">
                        <Icon name="check" size={14} /> {t('wedding2.chk.here')}
                      </span>
                    )}
                  </span>
                  <button className="btn btn--sm" onClick={() => setQrFor(g.id)}>
                    <Icon name="consent" size={16} /> {t('wedding2.chk.showQr')}
                  </button>
                </li>
              ))}
          </ul>
        )}
      </Card>

      <Sheet open={qrGuest != null} onClose={() => setQrFor(null)} title={qrGuest?.name ?? ''}>
        {qrGuest && (
          <div className="stack" style={{ alignItems: 'center', textAlign: 'center' }}>
            <div style={{ padding: 8, background: '#fff', borderRadius: 8 }}>
              <QrSvg text={makeToken(qrGuest.id)} />
            </div>
            <p className="card__hint">{t('wedding2.chk.qrHint')}</p>
            <code style={{ fontSize: 11, wordBreak: 'break-all', userSelect: 'all' }}>{makeToken(qrGuest.id)}</code>
            {qrGuest.checkedInAt && (
              <p className="chip chip--mint">
                {t('wedding2.chk.checkedAt', { when: whenLabel(qrGuest.checkedInAt, t, locale) })}
              </p>
            )}
          </div>
        )}
      </Sheet>
    </div>
  )
}

function Scanner({ guests }: { guests: readonly GuestRow[] }) {
  const { t } = useI18n()
  const [entry, setEntry] = useState('')
  const [result, setResult] = useState<CheckinResult<GuestRow> | null>(null)
  const [camera, setCamera] = useState(false)
  const hasCamera = typeof window !== 'undefined' && 'BarcodeDetector' in window

  async function doCheckin(g: GuestRow) {
    const at = new Date().toISOString()
    await patch('wedding', g.id, { checkedInAt: at })
    setResult({ status: 'already', guest: { ...g, checkedInAt: at } })
  }

  function handleToken(raw: string, auto = false) {
    const r = verifyCheckin(raw, guests)
    setResult(r)
    if (auto && r.status === 'ok' && r.guest) void doCheckin(r.guest)
  }

  return (
    <Card title={t('wedding2.chk.scanner')} icon="checkin" hint={t('wedding2.chk.scannerHint')}>
      {hasCamera && (
        <button className="btn btn--sm" onClick={() => setCamera((c) => !c)}>
          <Icon name="checkin" size={16} /> {camera ? t('wedding2.chk.stopCamera') : t('wedding2.chk.useCamera')}
        </button>
      )}
      {camera && <CameraScan onScan={(v) => handleToken(v, true)} />}

      <Field label={t('wedding2.chk.manual')} hint={t('wedding2.chk.manualHint')}>
        {(p) => (
          <input
            {...p}
            type="text"
            value={entry}
            onChange={(e) => setEntry(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') handleToken(entry) }}
          />
        )}
      </Field>
      <button className="btn btn--block btn--sm" onClick={() => handleToken(entry)}>
        {t('wedding2.chk.verify')}
      </button>

      {result && <ResultBanner result={result} onCheckin={doCheckin} />}
    </Card>
  )
}

function ResultBanner({
  result,
  onCheckin,
}: {
  result: CheckinResult<GuestRow>
  onCheckin: (g: GuestRow) => void
}) {
  const { t, locale } = useI18n()
  if (result.status === 'bad') return <p className="banner"><Icon name="info" size={16} /> {t('wedding2.chk.resBad')}</p>
  if (result.status === 'unknown') return <p className="banner"><Icon name="info" size={16} /> {t('wedding2.chk.resUnknown')}</p>
  if (result.status === 'already' && result.guest)
    return (
      <p className="banner">
        <Icon name="check" size={16} />{' '}
        {t('wedding2.chk.resAlready', {
          name: result.guest.name,
          when: result.guest.checkedInAt ? whenLabel(result.guest.checkedInAt, t, locale) : '',
        })}
      </p>
    )
  if (result.status === 'ok' && result.guest)
    return (
      <div className="banner stack stack--tight">
        <span><Icon name="check" size={16} /> {t('wedding2.chk.resOk', { name: result.guest.name, pax: result.guest.pax })}</span>
        <button className="btn btn--sm" onClick={() => onCheckin(result.guest!)}>{t('wedding2.chk.doCheckin')}</button>
      </div>
    )
  return null
}

/**
 * Camera path — a progressive enhancement. Uses the native BarcodeDetector; if
 * anything is unavailable it silently yields to the manual field above. No
 * network, no library.
 */
function CameraScan({ onScan }: { onScan: (value: string) => void }) {
  const { t } = useI18n()
  const videoRef = useRef<HTMLVideoElement>(null)
  const [error, setError] = useState(false)

  useEffect(() => {
    let stream: MediaStream | null = null
    let timer: number | undefined
    let stopped = false
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const Detector = (window as any).BarcodeDetector
    const detector = new Detector({ formats: ['qr_code'] })

    ;(async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
        if (stopped) return
        const v = videoRef.current
        if (!v) return
        v.srcObject = stream
        await v.play()
        const tick = async () => {
          if (stopped || !videoRef.current) return
          try {
            const codes = await detector.detect(videoRef.current)
            if (codes[0]?.rawValue) onScan(codes[0].rawValue)
          } catch {
            /* transient decode miss — keep scanning */
          }
          timer = window.setTimeout(tick, 400)
        }
        void tick()
      } catch {
        setError(true)
      }
    })()

    return () => {
      stopped = true
      if (timer) clearTimeout(timer)
      stream?.getTracks().forEach((tr) => tr.stop())
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  if (error) return <p className="card__hint">{t('wedding2.chk.cameraFail')}</p>
  return (
    <video
      ref={videoRef}
      muted
      playsInline
      style={{ width: '100%', maxWidth: 320, borderRadius: 8, background: '#000' }}
    />
  )
}
