/**
 * Progress summary that reports state, never a score (W38).
 *
 * This is the deliberate opposite of a "you are 72% ready" gauge. It reports what
 * exists — how many events have dates, how many guests replied, what the budget
 * rolls up to, how many after-party tasks are left — as plain counts, per area,
 * with no aggregate percentage and no verdict on the couple. Every number is a
 * fact the couple entered, not a grade.
 *
 * Structural in, numbers out — no copy, no database. Reuses the already-tested
 * `budgetRollup` and `confirmedHeadcount` rather than re-deriving them.
 */

import { budgetRollup, type BudgetLine } from './money'
import { confirmedHeadcount, type HeadcountLike } from './guests'
import type { PlannerOf, PlannerRecord } from './types'

export interface WeddingSummary {
  events: { total: number; dated: number }
  guests: { total: number; replied: number; confirmedPax: number }
  vendors: { total: number; deal: number }
  budget: { planned: number; committed: number; paid: number; lines: number }
  post: { total: number; done: number }
}

/**
 * Fold the raw planner rows into per-area tallies. Reads only stored fields; the
 * dependency-derived event date is out of scope here, so "dated" counts events
 * that carry their own `date` (the standalone anchors), which is the honest
 * lower bound the couple can act on.
 */
export function weddingSummary(rows: readonly PlannerRecord[]): WeddingSummary {
  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    rows.filter((r): r is PlannerOf<K> => r.kind === kind)

  const events = of('wed_event')
  const guests = of('wed_guest2')
  const vendors = of('wed_vendor2')
  const budgetLines = of('wed_budget2')
  const post = of('wed_post')

  const roll = budgetRollup(budgetLines as unknown as BudgetLine[])

  return {
    events: {
      total: events.length,
      dated: events.filter((e) => !!e.date || !!e.dependsOn).length,
    },
    guests: {
      total: guests.length,
      replied: guests.filter((g) => g.invite === 'rsvp').length,
      confirmedPax: confirmedHeadcount(guests as unknown as HeadcountLike[]),
    },
    vendors: {
      total: vendors.length,
      deal: vendors.filter((v) => v.status === 'deal').length,
    },
    budget: { planned: roll.planned, committed: roll.committed, paid: roll.paid, lines: roll.lines },
    post: {
      total: post.length,
      done: post.filter((p) => p.done).length,
    },
  }
}
