/**
 * Weather & outdoor contingency (W35).
 *
 * TemuDua stores no weather data and predicts no rain — no free forecast API,
 * nothing to be wrong about on the day. It only tracks the couple's own list of
 * exposed things and whether each has a backup plan that is actually arranged.
 * A risk with no plan is surfaced; the app never invents the plan.
 *
 * Structural in, numbers out — no copy, no database.
 */

export interface ContingencyLike {
  id: string
  plan?: string
  ready?: boolean
}

export interface ContingencySummary {
  total: number
  /** how many have a written backup plan. */
  planned: number
  /** how many backups are actually arranged (`ready`). */
  ready: number
  /** ids with no plan written at all — the open gaps to close. */
  gapIds: string[]
}

export function contingencySummary(items: readonly ContingencyLike[]): ContingencySummary {
  let planned = 0
  let ready = 0
  const gapIds: string[] = []
  for (const c of items) {
    const hasPlan = (c.plan ?? '').trim() !== ''
    if (hasPlan) planned += 1
    else gapIds.push(c.id)
    if (c.ready) ready += 1
  }
  return { total: items.length, planned, ready, gapIds }
}
