/**
 * Export the whole wedding plan for sharing with family (W39).
 *
 * Builds a copy-free, structured model of the plan — events with their real
 * (dependency-resolved) dates, the rundown, guest headcounts, vendors, the
 * budget roll-up, and the after-party list — that the screen renders to plain
 * text the couple can paste into a family chat. It is copy-free on purpose: the
 * only text it carries is what the couple typed, plus event names resolved by an
 * injected labeller the component owns. Business logic holds no Indonesian.
 *
 * Private angpao/gift records (W18, `C1_personal`) are never included and their
 * count is reported so the screen can say what was withheld — a family copy of
 * the plan must not leak who gave how much.
 */

import { withResolvedDates } from './deps'
import { budgetRollup, type BudgetLine } from './money'
import type { PlannerOf, PlannerRecord, PostCategory, QuotaSide, VendorState } from './types'

export interface PlanEventLine {
  name: string
  date?: string
  venue?: string
  pic?: string
}

export interface PlanRundownLine {
  eventName: string
  time: string
  what: string
  who?: string
}

export interface PlanGuestGroup {
  quota: QuotaSide
  count: number
  pax: number
}

export interface PlanVendorLine {
  name: string
  category: string
  status: VendorState
  eventName: string
}

export interface PlanPostLine {
  task: string
  category: PostCategory
  done: boolean
}

export interface PlanExportModel {
  events: PlanEventLine[]
  rundown: PlanRundownLine[]
  guestGroups: PlanGuestGroup[]
  guestTotal: { count: number; pax: number }
  vendors: PlanVendorLine[]
  budget: { planned: number; committed: number; paid: number; lines: number }
  post: PlanPostLine[]
  /** Records deliberately withheld from a family copy, so the screen can disclose it. */
  omitted: { gifts: number }
}

/**
 * Fold the planner rows into the export model. `eventName` resolves an event id
 * to a display name (the component supplies it via `t()`), keeping this module
 * free of copy. Events are ordered by resolved date, undated last.
 */
export function buildPlanExport(
  rows: readonly PlannerRecord[],
  eventName: (id?: string) => string,
): PlanExportModel {
  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    rows.filter((r): r is PlannerOf<K> => r.kind === kind)

  const resolved = withResolvedDates(of('wed_event'))
  const events: PlanEventLine[] = resolved
    .slice()
    .sort((a, b) => (a.date ?? '~').localeCompare(b.date ?? '~'))
    .map((e) => ({
      name: eventName(e.id),
      ...(e.date ? { date: e.date } : {}),
      ...(e.venue?.trim() ? { venue: e.venue.trim() } : {}),
      ...(e.pic?.trim() ? { pic: e.pic.trim() } : {}),
    }))

  const rundown: PlanRundownLine[] = of('wed_rundown')
    .slice()
    .sort((a, b) => a.time.localeCompare(b.time))
    .map((r) => ({
      eventName: eventName(r.eventId),
      time: r.time,
      what: r.what,
      ...(r.who?.trim() ? { who: r.who.trim() } : {}),
    }))

  const guests = of('wed_guest2')
  const quotas: QuotaSide[] = ['pasangan', 'ortu_a', 'ortu_b']
  const guestGroups: PlanGuestGroup[] = quotas
    .map((quota) => {
      const list = guests.filter((g) => g.quota === quota)
      return { quota, count: list.length, pax: list.reduce((s, g) => s + Math.max(0, g.pax), 0) }
    })
    .filter((g) => g.count > 0)
  const guestTotal = {
    count: guests.length,
    pax: guests.reduce((s, g) => s + Math.max(0, g.pax), 0),
  }

  const vendors: PlanVendorLine[] = of('wed_vendor2')
    .filter((v) => v.status !== 'batal')
    .slice()
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((v) => ({
      name: v.name,
      category: v.category,
      status: v.status,
      eventName: eventName(v.eventId),
    }))

  const roll = budgetRollup(of('wed_budget2') as unknown as BudgetLine[])

  const post: PlanPostLine[] = of('wed_post').map((p) => ({
    task: p.task,
    category: p.category,
    done: !!p.done,
  }))

  return {
    events,
    rundown,
    guestGroups,
    guestTotal,
    vendors,
    budget: { planned: roll.planned, committed: roll.committed, paid: roll.paid, lines: roll.lines },
    post,
    omitted: { gifts: of('wed_gift').length },
  }
}
