/**
 * Offline readiness for the whole wedding domain (W26).
 *
 * The app already runs entirely on IndexedDB — no feature calls the network — so
 * "offline mode" is not a switch to flip but a fact to make visible and to nudge
 * the couple to prepare for. The venue has no signal; anything you might need to
 * *look up* on the day must already be on this phone. This reports which day-of
 * essentials have been captured, so the gap is visible before the signal is gone.
 *
 * Structural counts in, keys/numbers out — no copy, no database. `key` is a
 * message key the screen resolves.
 */

/** The record kinds that must exist locally for a no-signal day-of. */
export const OFFLINE_ESSENTIALS = ['guests', 'rundown', 'prep', 'transport', 'docs', 'tables'] as const
export type OfflineEssentialKey = (typeof OFFLINE_ESSENTIALS)[number]

export interface OfflineEssential {
  key: OfflineEssentialKey
  count: number
  present: boolean
}

export interface OfflineReadiness {
  essentials: OfflineEssential[]
  readyCount: number
  total: number
  /** Every essential captured — nothing left to fetch on the day. */
  allReady: boolean
}

/**
 * Which day-of essentials are on the device (W26). An essential is `present` once
 * at least one row exists — the guarantee is that whatever is entered is offline,
 * and the checklist shows what is still worth entering while you still have signal.
 */
export function offlineReadiness(counts: Record<OfflineEssentialKey, number>): OfflineReadiness {
  const essentials = OFFLINE_ESSENTIALS.map((key) => {
    const count = Math.max(0, counts[key] ?? 0)
    return { key, count, present: count > 0 }
  })
  const readyCount = essentials.filter((e) => e.present).length
  return {
    essentials,
    readyCount,
    total: essentials.length,
    allReady: readyCount === essentials.length,
  }
}
