import { useEffect, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n } from '@/i18n'
import { whenLabel } from '@/i18n/format'
import { docStatus, docVaultSummary, type DocStatus } from './docs'
import type { PlannerOf, PlannerRecord } from './types'

/**
 * Document vault references (W27).
 *
 * The vault stores that a document exists and where it is — never the scan. A
 * photo of a KTP or buku nikah sitting in a shared-phone database is a liability
 * the app cannot protect, so it does not accept one. `where` points you at the
 * real copy; `ref` is an optional number the couple chooses to jot, with a plain
 * warning next to it.
 */

const STATUS_CHIP: Record<Exclude<DocStatus, 'none'>, string> = {
  ok: 'chip chip--mint',
  soon: 'chip chip--yellow',
  expired: 'chip chip--primary',
}

export function DocsTab({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState(false)
  const [editId, setEditId] = useState<string | null>(null)
  const rows = useOwned<PlannerRecord>('wedding', me)

  const docs = (rows ?? []).filter((r): r is PlannerOf<'wed_doc'> => r.kind === 'wed_doc')
  const now = Date.now()
  const summary = docVaultSummary(docs, now)
  const sorted = docs
    .slice()
    .sort((a, b) => (a.expiresAt ?? '9999').localeCompare(b.expiresAt ?? '9999') || a.name.localeCompare(b.name))

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.doc.intro')}</p>
      <p className="banner">
        <Icon name="private" size={16} /> {t('wedding2.doc.noScan')}
      </p>

      <Card title={t('wedding2.doc.summary')} icon="shield">
        <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
          <span className="chip">{t('wedding2.doc.total', { n: summary.total })}</span>
          <span className="chip chip--mint">{t('wedding2.doc.located', { n: summary.located })}</span>
          {summary.expiringSoon > 0 && (
            <span className="chip chip--yellow">{t('wedding2.doc.soon', { n: summary.expiringSoon })}</span>
          )}
          {summary.expired > 0 && (
            <span className="chip chip--primary">{t('wedding2.doc.expired', { n: summary.expired })}</span>
          )}
        </div>
        {summary.total > summary.located && (
          <p className="card__hint">{t('wedding2.doc.locateHint', { n: summary.total - summary.located })}</p>
        )}
      </Card>

      <Card
        title={t('wedding2.doc.vault')}
        icon="private"
        action={
          <button className="btn btn--sm" onClick={() => { setEditId(null); setOpen(true) }}>
            <Icon name="plus" size={16} /> {t('wedding2.doc.add')}
          </button>
        }
      >
        {docs.length === 0 ? (
          <EmptyState icon="private" title={t('wedding2.doc.empty')} hint={t('wedding2.doc.emptyHint')} />
        ) : (
          <ul className="list">
            {sorted.map((d) => {
              const s = docStatus(d.expiresAt, now)
              return (
                <li key={d.id} className="list__item">
                  <Icon name="private" size={18} />
                  <span className="grow stack stack--tight">
                    <button
                      className="btn btn--ghost btn--sm"
                      style={{ justifyContent: 'flex-start', padding: 0, fontWeight: 600, fontSize: 14 }}
                      onClick={() => { setEditId(d.id); setOpen(true) }}
                    >
                      {d.name}
                    </button>
                    <span className="card__hint">
                      {d.docKind}
                      {d.where ? ` · ${t('wedding2.doc.at', { where: d.where })}` : ` · ${t('wedding2.doc.noWhere')}`}
                      {d.ref ? ` · ${d.ref}` : ''}
                      {d.expiresAt ? ` · ${whenLabel(d.expiresAt, t, locale)}` : ''}
                    </span>
                    {d.note && <span className="card__hint">{d.note}</span>}
                  </span>
                  {s !== 'none' && <span className={STATUS_CHIP[s]}>{t(`wedding2.doc.st.${s}` as const)}</span>}
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', d.id, me)}>
                    <Icon name="close" size={16} label={t('common.deleteX', { name: d.name })} />
                  </button>
                </li>
              )
            })}
          </ul>
        )}
      </Card>

      <DocSheet
        open={open}
        editing={editId ? docs.find((d) => d.id === editId) : undefined}
        onClose={() => { setOpen(false); setEditId(null) }}
        me={me}
      />
    </div>
  )
}

function DocSheet({
  open,
  editing,
  onClose,
  me,
}: {
  open: boolean
  editing?: PlannerOf<'wed_doc'>
  onClose: () => void
  me: string
}) {
  const { t } = useI18n()
  const [name, setName] = useState('')
  const [docKind, setDocKind] = useState('')
  const [where, setWhere] = useState('')
  const [ref, setRef] = useState('')
  const [expires, setExpires] = useState('')
  const [note, setNote] = useState('')

  const seedKey = editing?.id ?? 'new'
  useEffect(() => {
    setName(editing?.name ?? '')
    setDocKind(editing?.docKind ?? '')
    setWhere(editing?.where ?? '')
    setRef(editing?.ref ?? '')
    setExpires(editing?.expiresAt ?? '')
    setNote(editing?.note ?? '')
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seedKey, open])

  async function save() {
    if (!name.trim()) return
    const fields = {
      name: name.trim(),
      docKind: docKind.trim() || t('wedding2.doc.kindDefault'),
      where: where.trim() || undefined,
      ref: ref.trim() || undefined,
      expiresAt: expires || undefined,
      note: note.trim() || undefined,
    }
    if (editing) await patch('wedding', editing.id, fields)
    else await db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), kind: 'wed_doc', ...fields } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={editing ? t('wedding2.doc.edit') : t('wedding2.doc.add')}>
      <div className="stack">
        <Field label={t('wedding2.doc.fName')} hint={t('wedding2.doc.fNameHint')}>
          {(p) => <input {...p} type="text" value={name} onChange={(e) => setName(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.doc.fKind')} hint={t('wedding2.doc.fKindHint')}>
          {(p) => <input {...p} type="text" value={docKind} onChange={(e) => setDocKind(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.doc.fWhere')} hint={t('wedding2.doc.fWhereHint')}>
          {(p) => <input {...p} type="text" value={where} onChange={(e) => setWhere(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.doc.fRef')} hint={t('wedding2.doc.fRefHint')}>
          {(p) => <input {...p} type="text" value={ref} onChange={(e) => setRef(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.doc.fExpires')} hint={t('common.optional')}>
          {(p) => <input {...p} type="date" value={expires} onChange={(e) => setExpires(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.fNote')} hint={t('common.optional')}>
          {(p) => <input {...p} type="text" value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!name.trim()}>{t('common.save')}</button>
      </div>
    </Sheet>
  )
}
