import { useEffect, useMemo, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n, baseLocale } from '@/i18n'
import { formatRupiah } from '@/i18n/format'
import { searchWedding } from './search'
import { weddingSummary } from './summary'
import { postProgress } from './postwedding'
import { buildPlanExport, type PlanExportModel } from './planExport'
import { POST_CATEGORIES, type PlannerOf, type PlannerRecord, type PostCategory } from './types'

/**
 * The wedding domain summary screen (W40), tying the last five items together:
 * one search box across the whole plan (W37), a progress summary that reports
 * state without scoring the couple (W38), the after-party checklist (W36), a
 * share-to-family export (W39), and a note on where the offline backup lives
 * (W40). Everything renders from IndexedDB via useOwned() and writes through
 * newEnvelope/patch/softDelete — no network is touched.
 */
export function SummaryTab({ me }: { me: string }) {
  const { t } = useI18n()
  const rows = useOwned<PlannerRecord>('wedding', me)
  const list = rows ?? []
  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    list.filter((r): r is PlannerOf<K> => r.kind === kind)

  const events = of('wed_event')
  const eventLabel = (id?: string) => {
    if (!id) return t('wedding2.log.allEvents')
    const e = events.find((x) => x.id === id)
    return e ? e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const) : t('wedding2.log.eventGone')
  }

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.sum.intro')}</p>
      <SearchCard rows={list} eventLabel={eventLabel} />
      <StateCard rows={list} />
      <PostCard me={me} tasks={of('wed_post')} />
      <ExportCard rows={list} eventLabel={eventLabel} />
      <BackupCard />
    </div>
  )
}

// -- W37 search ------------------------------------------------------------
function SearchCard({
  rows,
  eventLabel,
}: {
  rows: readonly PlannerRecord[]
  eventLabel: (id?: string) => string
}) {
  const { t } = useI18n()
  const [q, setQ] = useState('')
  const hits = useMemo(() => searchWedding(rows, q), [rows, q])

  return (
    <Card title={t('wedding2.srch.title')} icon="shared" hint={t('wedding2.srch.hint')}>
      <Field label={t('wedding2.srch.label')}>
        {(p) => (
          <input
            {...p}
            type="search"
            value={q}
            placeholder={t('wedding2.srch.placeholder')}
            onChange={(e) => setQ(e.target.value)}
          />
        )}
      </Field>
      {q.trim() === '' ? null : hits.length === 0 ? (
        <p className="card__hint">{t('wedding2.srch.none', { q: q.trim() })}</p>
      ) : (
        <>
          <span className="chip chip--blue">{t('wedding2.srch.results', { n: hits.length })}</span>
          <ul className="list">
            {hits.map((h) => (
              <li key={h.id} className="list__item">
                <span className="chip">{t(`wedding2.srch.kind.${h.kind}` as const)}</span>
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{h.label.trim() || t('wedding2.srch.noLabel')}</strong>
                  {h.eventId !== undefined && <span className="card__hint">{eventLabel(h.eventId)}</span>}
                </span>
              </li>
            ))}
          </ul>
        </>
      )}
    </Card>
  )
}

// -- W38 progress summary (state, not a score) -----------------------------
function StateCard({ rows }: { rows: readonly PlannerRecord[] }) {
  const { t, locale } = useI18n()
  const s = weddingSummary(rows)
  const anything =
    s.events.total + s.guests.total + s.vendors.total + s.budget.lines + s.post.total > 0

  const line = (label: string, value: string) => (
    <li className="list__item">
      <span className="grow"><strong style={{ fontSize: 14 }}>{label}</strong></span>
      <span className="card__hint" style={{ textAlign: 'right' }}>{value}</span>
    </li>
  )

  return (
    <Card title={t('wedding2.sum.stateTitle')} icon="checkin" hint={t('wedding2.sum.stateHint')}>
      {!anything ? (
        <EmptyState icon="checkin" title={t('wedding2.sum.empty')} />
      ) : (
        <ul className="list">
          {line(t('wedding2.sum.lblEvents'), t('wedding2.sum.events', { dated: s.events.dated, total: s.events.total }))}
          {line(
            t('wedding2.sum.lblGuests'),
            t('wedding2.sum.guests', { replied: s.guests.replied, total: s.guests.total, pax: s.guests.confirmedPax }),
          )}
          {line(t('wedding2.sum.lblVendors'), t('wedding2.sum.vendors', { deal: s.vendors.deal, total: s.vendors.total }))}
          {line(
            t('wedding2.sum.lblBudget'),
            t('wedding2.sum.budget', {
              planned: formatRupiah(s.budget.planned, locale),
              committed: formatRupiah(s.budget.committed, locale),
              paid: formatRupiah(s.budget.paid, locale),
            }),
          )}
          {line(t('wedding2.sum.lblPost'), t('wedding2.sum.post', { done: s.post.done, total: s.post.total }))}
        </ul>
      )}
      <p className="disclaimer">{t('wedding2.sum.notScore')}</p>
    </Card>
  )
}

// -- W36 post-wedding checklist --------------------------------------------
const POST_CHIP: Record<'done' | 'open', string> = { done: 'chip chip--mint', open: 'chip' }

function PostCard({ me, tasks }: { me: string; tasks: PlannerOf<'wed_post'>[] }) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)
  const progress = postProgress(tasks)

  return (
    <Card
      title={t('wedding2.post.title')}
      icon="tasks"
      hint={t('wedding2.post.hint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('wedding2.post.add')}
        </button>
      }
    >
      <p className="banner">
        <Icon name="info" size={16} /> {t('wedding2.post.disclaimer')}
      </p>
      {tasks.length === 0 ? (
        <EmptyState icon="tasks" title={t('wedding2.post.empty')} hint={t('wedding2.post.emptyHint')} />
      ) : (
        <>
          <span className="chip chip--blue">{t('wedding2.post.done', { done: progress.doneCount, total: progress.total })}</span>
          {POST_CATEGORIES.map((cat) => {
            const bucket = tasks.filter((x) => x.category === cat).sort((a, b) => a.task.localeCompare(b.task))
            if (bucket.length === 0) return null
            return (
              <div key={cat} className="stack stack--tight" style={{ marginBottom: 'var(--space-3)' }}>
                <strong style={{ fontSize: 13 }}>{t(`wedding2.post.cat.${cat}` as const)}</strong>
                <ul className="list">
                  {bucket.map((x) => (
                    <li key={x.id} className="list__item">
                      <button
                        className="btn btn--ghost btn--sm"
                        aria-pressed={!!x.done}
                        aria-label={t('wedding2.post.toggle', { name: x.task })}
                        onClick={() => patch('wedding', x.id, { done: !x.done })}
                      >
                        <span className={POST_CHIP[x.done ? 'done' : 'open']}>
                          <Icon name="check" size={16} />
                        </span>
                      </button>
                      <span className="grow stack stack--tight">
                        <strong style={{ fontSize: 14, opacity: x.done ? 0.55 : 1 }}>{x.task}</strong>
                        {(x.due || x.note) && (
                          <span className="card__hint">
                            {x.due ? t('wedding2.post.due', { date: x.due }) : ''}
                            {x.note ? `${x.due ? ' · ' : ''}${x.note}` : ''}
                          </span>
                        )}
                      </span>
                      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', x.id, me)}>
                        <Icon name="close" size={16} label={t('common.deleteX', { name: x.task })} />
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )
          })}
        </>
      )}
      <PostSheet open={open} onClose={() => setOpen(false)} me={me} />
    </Card>
  )
}

function PostSheet({ open, onClose, me }: { open: boolean; onClose: () => void; me: string }) {
  const { t } = useI18n()
  const [task, setTask] = useState('')
  const [category, setCategory] = useState<PostCategory>('terimakasih')
  const [due, setDue] = useState('')

  useEffect(() => {
    if (open) {
      setTask('')
      setCategory('terimakasih')
      setDue('')
    }
  }, [open])

  async function save() {
    if (!task.trim()) return
    await db.wedding.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'wed_post',
      task: task.trim(),
      category,
      ...(due ? { due } : {}),
    } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('wedding2.post.add')}>
      <div className="stack">
        <p className="card__hint">{t('wedding2.post.disclaimer')}</p>
        <Field label={t('wedding2.post.fTask')} hint={t('wedding2.post.fTaskHint')}>
          {(p) => <input {...p} type="text" value={task} onChange={(e) => setTask(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.post.fCategory')}>
          {(p) => (
            <select {...p} value={category} onChange={(e) => setCategory(e.target.value as PostCategory)}>
              {POST_CATEGORIES.map((c) => (
                <option key={c} value={c}>
                  {t(`wedding2.post.cat.${c}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('wedding2.post.fDue')} hint={t('wedding2.post.fDueHint')}>
          {(p) => <input {...p} type="date" value={due} onChange={(e) => setDue(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!task.trim()}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}

// -- W39 export for family -------------------------------------------------
/** Render the copy-free export model to shareable plain text using the dictionary. */
function renderExport(model: PlanExportModel, t: ReturnType<typeof useI18n>['t'], locale: 'id' | 'en'): string {
  const out: string[] = [`# ${t('wedding2.exp.docTitle')}`, '']

  if (model.events.length) {
    out.push(`## ${t('wedding2.exp.secEvents')}`)
    for (const e of model.events) {
      const bits = [e.date ?? t('wedding2.exp.noDate'), e.venue, e.pic].filter(Boolean)
      out.push(`- ${e.name} — ${bits.join(' · ')}`)
    }
    out.push('')
  }
  if (model.rundown.length) {
    out.push(`## ${t('wedding2.exp.secRundown')}`)
    for (const r of model.rundown) out.push(`- ${r.time} ${r.what}${r.who ? ` (${r.who})` : ''} — ${r.eventName}`)
    out.push('')
  }
  if (model.guestTotal.count) {
    out.push(`## ${t('wedding2.exp.secGuests')}`)
    for (const g of model.guestGroups) {
      out.push(`- ${t(`wedding2.gst.sideName.${g.quota}` as const)}: ${g.count} · ${g.pax} pax`)
    }
    out.push(`- ${t('wedding2.exp.guestTotal', { count: model.guestTotal.count, pax: model.guestTotal.pax })}`)
    out.push('')
  }
  if (model.vendors.length) {
    out.push(`## ${t('wedding2.exp.secVendors')}`)
    for (const v of model.vendors) {
      out.push(`- ${v.name} (${v.category}) — ${t(`wedding2.vstat.${v.status}` as const)} · ${v.eventName}`)
    }
    out.push('')
  }
  if (model.budget.lines) {
    out.push(`## ${t('wedding2.exp.secBudget')}`)
    out.push(
      `- ${t('wedding2.sum.budget', {
        planned: formatRupiah(model.budget.planned, locale),
        committed: formatRupiah(model.budget.committed, locale),
        paid: formatRupiah(model.budget.paid, locale),
      })}`,
    )
    out.push('')
  }
  if (model.post.length) {
    out.push(`## ${t('wedding2.exp.secPost')}`)
    for (const p of model.post) out.push(`- [${p.done ? 'x' : ' '}] ${p.task}`)
    out.push('')
  }
  return out.join('\n').trim() + '\n'
}

function ExportCard({
  rows,
  eventLabel,
}: {
  rows: readonly PlannerRecord[]
  eventLabel: (id?: string) => string
}) {
  const { t, locale: uiLocale } = useI18n()
  // `dwi` is a display mode, not a language — formatters and data tables
  // take the real one.
  const locale = baseLocale(uiLocale)
  const [copied, setCopied] = useState(false)
  const model = useMemo(() => buildPlanExport(rows, eventLabel), [rows, eventLabel])
  const text = useMemo(() => renderExport(model, t, locale), [model, t, locale])
  const hasContent =
    model.events.length + model.rundown.length + model.guestTotal.count + model.vendors.length + model.budget.lines + model.post.length > 0

  async function copy() {
    try {
      await navigator.clipboard.writeText(text)
      setCopied(true)
      setTimeout(() => setCopied(false), 1800)
    } catch {
      /* clipboard blocked (e.g. insecure context) — download stays available */
    }
  }

  function download() {
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = 'rencana-pernikahan.txt'
    a.click()
    URL.revokeObjectURL(url)
  }

  return (
    <Card title={t('wedding2.exp.title')} icon="export" hint={t('wedding2.exp.hint')}>
      {!hasContent ? (
        <EmptyState icon="export" title={t('wedding2.exp.empty')} />
      ) : (
        <>
          <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
            <button className="btn btn--sm" onClick={copy}>
              <Icon name={copied ? 'check' : 'export'} size={16} /> {copied ? t('wedding2.exp.copied') : t('wedding2.exp.btn')}
            </button>
            <button className="btn btn--sm btn--ghost" onClick={download}>
              <Icon name="backup" size={16} /> {t('wedding2.exp.download')}
            </button>
          </div>
          {model.omitted.gifts > 0 && (
            <p className="disclaimer">{t('wedding2.exp.omitGifts', { n: model.omitted.gifts })}</p>
          )}
          <pre
            className="card__hint"
            style={{ whiteSpace: 'pre-wrap', overflowX: 'auto', maxWidth: '100%', fontSize: 13, marginTop: 'var(--space-2)' }}
          >
            {text}
          </pre>
        </>
      )}
    </Card>
  )
}

// -- W40 backup / offline note ---------------------------------------------
function BackupCard() {
  const { t } = useI18n()
  return (
    <Card title={t('wedding2.bak.title')} icon="backup">
      <p className="card__hint">{t('wedding2.bak.body')}</p>
      <p className="card__hint">{t('wedding2.bak.where')}</p>
    </Card>
  )
}
