import { differenceInCalendarDays, format, parseISO } from 'date-fns'
import { vendorTerms, type VendorLike } from './plannerMath'
import { FUND_SOURCES, type FundSource, type PayMilestone } from './types'

/**
 * Wedding money (W06–W10).
 *
 * Three separate questions that a single "budget" number usually blurs:
 *
 *  - **planned / committed / paid** (W06). Planned is a guess, committed is a
 *    signature, paid is money gone. Collapsing them is how couples find out in
 *    week 40 that the plan was fine and the commitments were not.
 *  - **where the money comes in from** (W07). Both families and the couple keep
 *    their own pot, pledged and received tracked apart, because a promise is not
 *    a transfer and pretending otherwise is how a family gets quietly blamed.
 *  - **what a vendor actually costs** (W08–W10). Quote, deposit, schedule,
 *    balance — entered by the couple. TemuDua ships no vendor directory, no price
 *    reference, and no opinion on who to book.
 *
 * Everything here is pure and returns numbers and keys only. Nothing in this
 * module recommends an action: it describes what the couple typed, and the
 * screen says so out loud.
 */

const atLeast0 = (n: number | undefined): number =>
  Number.isFinite(n) && (n as number) > 0 ? (n as number) : 0

// --- W06: planned / committed / paid --------------------------------------

export interface BudgetLine {
  /** Undefined means the line covers the whole wedding, not one event. */
  eventId?: string
  planned: number
  committed?: number
  paid: number
  source: FundSource
}

export interface BudgetRoll {
  planned: number
  committed: number
  paid: number
  /** Committed but not yet handed over. Never negative. */
  unpaid: number
  /** Planned and not yet committed to anybody. Negative when commitments ran past the plan. */
  uncommitted: number
  /** How far commitments run past the plan; 0 when they do not. */
  overPlan: number
  lines: number
}

/**
 * Money already paid counts as committed even when nobody filled the commitment
 * box in — you cannot un-commit money that has left the account. So the roll-up
 * never reports a commitment lower than what was actually spent.
 */
export const committedOf = (b: BudgetLine): number =>
  Math.max(atLeast0(b.committed), atLeast0(b.paid))

export function budgetRollup(lines: readonly BudgetLine[]): BudgetRoll {
  let planned = 0
  let committed = 0
  let paid = 0
  for (const b of lines) {
    planned += atLeast0(b.planned)
    committed += committedOf(b)
    paid += atLeast0(b.paid)
  }
  return {
    planned,
    committed,
    paid,
    unpaid: Math.max(0, committed - paid),
    uncommitted: planned - committed,
    overPlan: Math.max(0, committed - planned),
    lines: lines.length,
  }
}

export interface EventBudget {
  /** Undefined is the "whole wedding" bucket, kept as its own row rather than
   *  spread across events — nobody can say which event the rings belong to. */
  eventId?: string
  roll: BudgetRoll
}

/**
 * Per-event roll-up (W06). `eventIds` fixes the order and keeps an event with no
 * budget line visible as a row of zeros; a missing event id still gets a row so
 * money attached to a deleted event never disappears silently.
 */
export function budgetByEvent(
  lines: readonly BudgetLine[],
  eventIds: readonly string[] = [],
): EventBudget[] {
  const seen: (string | undefined)[] = [undefined, ...eventIds]
  for (const b of lines) if (b.eventId && !seen.includes(b.eventId)) seen.push(b.eventId)
  return seen.map((eventId) => ({
    eventId,
    roll: budgetRollup(lines.filter((b) => b.eventId === eventId)),
  }))
}

// --- W07: contribution sources --------------------------------------------

export interface FundLike {
  source: FundSource
  pledged: number
  received: number
}

export interface SourceRow {
  source: FundSource
  pledged: number
  received: number
  /** Promised and not yet handed over. */
  outstanding: number
  /** Spending drawn against this pot, from the budget lines. */
  spent: { planned: number; committed: number; paid: number }
  /** Received minus paid out. Negative means the pot paid more than came in. */
  left: number
  /** The negative part of `left`, so a screen can name it without doing maths. */
  short: number
  /** Committed spending this pot has no money in hand for yet. */
  notCoveredYet: number
}

/**
 * Every source always gets a row, including the ones at zero: a family that has
 * pledged nothing is a fact worth seeing, and dropping the row would hide it.
 * The two parent sides stay separate rows and are never summed into "keluarga".
 */
export function fundingBySource(
  funds: readonly FundLike[],
  lines: readonly BudgetLine[],
): SourceRow[] {
  return FUND_SOURCES.map((source) => {
    const mine = funds.filter((f) => f.source === source)
    const pledged = mine.reduce((s, f) => s + atLeast0(f.pledged), 0)
    const received = mine.reduce((s, f) => s + atLeast0(f.received), 0)
    const spent = budgetRollup(lines.filter((b) => b.source === source))
    const left = received - spent.paid
    return {
      source,
      pledged,
      received,
      outstanding: Math.max(0, pledged - received),
      spent: { planned: spent.planned, committed: spent.committed, paid: spent.paid },
      left,
      short: Math.max(0, -left),
      notCoveredYet: Math.max(0, spent.committed - received),
    }
  })
}

// --- W08: vendor money and payment schedule -------------------------------

export interface PayLike {
  id: string
  vendorId: string
  milestone: PayMilestone
  amount: number
  dueDate?: string
  /** For a `kontrak` row this is the day it was signed. */
  paidAt?: string
}

export interface VendorMoney {
  quote?: number
  /** Sum of the `dp` rows, or the flat deposit field when there is no schedule. */
  deposit?: number
  /** Everything the schedule adds up to. */
  scheduled: number
  paid: number
  /** Scheduled and still owed. */
  outstanding: number
  /** Quote minus what has been paid. Undefined without a quote — an unknown
   *  balance has to read as unknown, never as nothing-owed. */
  balance?: number
  /** Quote minus what the schedule covers. Undefined without a quote. */
  unscheduled?: number
  /** The schedule was empty, so the numbers came from the flat DP/termin fields
   *  on the vendor record. Those carry no dates and no paid state. */
  fromFlatFields: boolean
  /** Soonest first; undated last. */
  schedule: PayLike[]
}

const MILESTONE_ORDER: readonly PayMilestone[] = ['kontrak', 'dp', 'termin', 'pelunasan', 'lainnya']

const byDueThenMilestone = (a: PayLike, b: PayLike): number =>
  (a.dueDate ?? '9999-12-31').localeCompare(b.dueDate ?? '9999-12-31') ||
  MILESTONE_ORDER.indexOf(a.milestone) - MILESTONE_ORDER.indexOf(b.milestone)

/**
 * What one vendor costs and what is left to pay. Falls back to the flat
 * booking/DP/termin fields the planner tab writes when no schedule rows exist,
 * so the two screens never disagree — and flags that it did, because those flat
 * fields say nothing about *when* or whether the money has actually moved.
 */
export function vendorMoney(v: VendorLike, pays: readonly PayLike[]): VendorMoney {
  const schedule = [...pays].sort(byDueThenMilestone)
  const flat = vendorTerms(v).committed
  const fromFlatFields = schedule.length === 0 && flat > 0

  const scheduled = fromFlatFields
    ? flat
    : schedule.reduce((s, p) => s + atLeast0(p.amount), 0)
  const paid = schedule
    .filter((p) => p.paidAt)
    .reduce((s, p) => s + atLeast0(p.amount), 0)
  const dpRows = schedule.filter((p) => p.milestone === 'dp')
  const deposit = fromFlatFields
    ? v.dp
    : dpRows.length > 0
      ? dpRows.reduce((s, p) => s + atLeast0(p.amount), 0)
      : undefined

  return {
    ...(v.quote === undefined ? {} : { quote: v.quote }),
    ...(deposit === undefined ? {} : { deposit }),
    scheduled,
    paid,
    outstanding: Math.max(0, scheduled - paid),
    ...(v.quote === undefined
      ? {}
      : { balance: v.quote - paid, unscheduled: v.quote - scheduled }),
    fromFlatFields,
    schedule,
  }
}

// --- W09: comparing one category ------------------------------------------

export interface VendorRowLike extends VendorLike {
  id: string
  name: string
  category: string
}

export interface CompareRow {
  id: string
  name: string
  money: VendorMoney
}

export interface Comparison {
  category: string
  rows: CompareRow[]
  withQuote: number
  withoutQuote: number
  /** Spread of the quotes actually entered. Only when at least two exist —
   *  a range over one number is not a range. */
  range?: { min: number; max: number; spread: number }
}

const norm = (s: string): string => s.trim().toLowerCase()

/** The categories the couple has actually typed, first spelling wins. */
export function vendorCategories(vendors: readonly VendorRowLike[]): string[] {
  const out = new Map<string, string>()
  for (const v of vendors) {
    const k = norm(v.category)
    if (k && !out.has(k)) out.set(k, v.category.trim())
  }
  return [...out.values()].sort((a, b) => a.localeCompare(b))
}

/**
 * One category, side by side (W09). Cheapest quote first purely so the columns
 * line up in a readable order — there is no score, no "best value", and no
 * recommendation. TemuDua has no idea whether the expensive one is worth it, and
 * says so on the screen rather than guessing.
 */
export function compareCategory(
  vendors: readonly VendorRowLike[],
  pays: readonly PayLike[],
  category: string,
): Comparison {
  const key = norm(category)
  const rows = vendors
    .filter((v) => norm(v.category) === key)
    .map((v) => ({
      id: v.id,
      name: v.name,
      money: vendorMoney(
        v,
        pays.filter((p) => p.vendorId === v.id),
      ),
    }))
    .sort(
      (a, b) =>
        (a.money.quote ?? Number.POSITIVE_INFINITY) - (b.money.quote ?? Number.POSITIVE_INFINITY) ||
        a.name.localeCompare(b.name),
    )

  const quotes = rows.map((r) => r.money.quote).filter((q): q is number => q !== undefined)
  const min = Math.min(...quotes)
  const max = Math.max(...quotes)
  return {
    category,
    rows,
    withQuote: quotes.length,
    withoutQuote: rows.length - quotes.length,
    ...(quotes.length >= 2 ? { range: { min, max, spread: max - min } } : {}),
  }
}

// --- W10: contract and payment reminders ----------------------------------

export const REMINDER_WINDOWS = ['overdue', 'today', 'soon', 'later', 'undated'] as const
export type ReminderWindow = (typeof REMINDER_WINDOWS)[number]

export interface Reminder {
  payId: string
  vendorId: string
  milestone: PayMilestone
  amount: number
  dueDate?: string
  /** Negative when the date has passed. Undefined when the row has no date. */
  daysLeft?: number
  window: ReminderWindow
}

const WINDOW_ORDER: readonly ReminderWindow[] = REMINDER_WINDOWS

/**
 * Unpaid milestones, soonest trouble first (W10). A `kontrak` row rides the same
 * path as a payment: signing has a date you can miss too.
 *
 * The reminder states a date and a number. It never tells anyone to pay, chase,
 * or cancel — that is a real-world money decision and it is not the app's.
 */
export function paymentReminders(
  pays: readonly PayLike[],
  opts: { today?: string; soonDays?: number } = {},
): Reminder[] {
  const today = opts.today ?? format(new Date(), 'yyyy-MM-dd')
  const soonDays = opts.soonDays ?? 14
  const now = parseISO(today)

  return pays
    .filter((p) => !p.paidAt)
    .map((p): Reminder => {
      const daysLeft = p.dueDate ? differenceInCalendarDays(parseISO(p.dueDate), now) : undefined
      const window: ReminderWindow =
        daysLeft === undefined
          ? 'undated'
          : daysLeft < 0
            ? 'overdue'
            : daysLeft === 0
              ? 'today'
              : daysLeft <= soonDays
                ? 'soon'
                : 'later'
      return {
        payId: p.id,
        vendorId: p.vendorId,
        milestone: p.milestone,
        amount: atLeast0(p.amount),
        ...(p.dueDate === undefined ? {} : { dueDate: p.dueDate }),
        ...(daysLeft === undefined ? {} : { daysLeft }),
        window,
      }
    })
    .sort(
      (a, b) =>
        WINDOW_ORDER.indexOf(a.window) - WINDOW_ORDER.indexOf(b.window) ||
        (a.dueDate ?? '9999-12-31').localeCompare(b.dueDate ?? '9999-12-31') ||
        MILESTONE_ORDER.indexOf(a.milestone) - MILESTONE_ORDER.indexOf(b.milestone),
    )
}

/** Why a booked vendor has no usable contract record. Message keys, not copy. */
export type ContractGapReason = 'noContractRow' | 'contractUnsigned'

export interface ContractGap {
  vendorId: string
  reason: ContractGapReason
}

/**
 * Booked vendors whose contract is not recorded as signed. Only `deal` vendors:
 * a shortlisted one is not supposed to have a contract, and flagging it would
 * train people to ignore the list.
 */
export function contractGaps(
  vendors: readonly { id: string; status: VendorRowLike['status'] }[],
  pays: readonly PayLike[],
): ContractGap[] {
  const out: ContractGap[] = []
  for (const v of vendors) {
    if (v.status !== 'deal') continue
    const rows = pays.filter((p) => p.vendorId === v.id && p.milestone === 'kontrak')
    if (rows.length === 0) out.push({ vendorId: v.id, reason: 'noContractRow' })
    else if (!rows.some((r) => r.paidAt)) out.push({ vendorId: v.id, reason: 'contractUnsigned' })
  }
  return out
}
