/**
 * Wedding-wide search (W37).
 *
 * One box that looks across the four things people actually hunt for — tasks,
 * guests, vendors, and budget lines — plus events and rundown lines, which are
 * where the free text usually lives. It matches on the couple's own words only
 * (a case-insensitive substring), returns a typed hit the component labels, and
 * invents nothing. A blank query returns nothing rather than everything.
 *
 * Structural in, structural out — no copy, no database, no ranking of people.
 */

import type { PlannerRecord } from './types'

/** The kinds this box looks across — tasks, guests, vendors, budget, plus the
 *  two other places free text lives (events, rundown). The component has a label
 *  key for each of exactly these, so the type stays narrow on purpose. */
export type SearchableKind =
  | 'wed_event'
  | 'wed_guest2'
  | 'wed_vendor2'
  | 'wed_budget2'
  | 'wed_post'
  | 'wed_rundown'

/** Kinds worth searching, and the fields on each that hold free text. */
const SEARCHABLE: Record<SearchableKind, readonly string[]> = {
  wed_event: ['label', 'venue', 'pic', 'note'],
  wed_guest2: ['name', 'relationship', 'origin', 'diet', 'note'],
  wed_vendor2: ['name', 'category', 'note'],
  wed_budget2: ['label'],
  wed_post: ['task', 'note'],
  wed_rundown: ['what', 'who', 'note'],
}

/** The field taken as the hit's headline, per kind. */
const PRIMARY: Record<SearchableKind, string> = {
  wed_event: 'label',
  wed_guest2: 'name',
  wed_vendor2: 'name',
  wed_budget2: 'label',
  wed_post: 'task',
  wed_rundown: 'what',
}

export interface SearchHit {
  id: string
  kind: SearchableKind
  /** The user's own headline text for the row. Empty when the primary field is blank. */
  label: string
  /** Which event it belongs to, when the record carries one. */
  eventId?: string
}

function textOf(row: Record<string, unknown>, field: string): string {
  const v = row[field]
  return typeof v === 'string' ? v : ''
}

/**
 * Return every searchable row whose free text contains `query`, in the row order
 * given. Trimmed-empty query short-circuits to `[]` — an empty box is not a
 * request to list the whole wedding.
 */
export function searchWedding(rows: readonly PlannerRecord[], query: string): SearchHit[] {
  const q = query.trim().toLowerCase()
  if (!q) return []

  const hits: SearchHit[] = []
  for (const row of rows as readonly (PlannerRecord & Record<string, unknown>)[]) {
    if (!(row.kind in SEARCHABLE)) continue
    const kind = row.kind as SearchableKind
    const matched = SEARCHABLE[kind].some((f) => textOf(row, f).toLowerCase().includes(q))
    if (!matched) continue
    hits.push({
      id: row.id,
      kind,
      label: textOf(row, PRIMARY[kind]),
      ...(typeof row.eventId === 'string' ? { eventId: row.eventId } : {}),
    })
  }
  return hits
}
