import type { QuotaSide } from './types'

/**
 * Table assignment logic (W16).
 *
 * Structural inputs, numeric outputs. A guest sits at one table; occupancy is
 * summed pax, not head count, because a "guest" row can carry a family. A guest
 * pointing at a table that no longer exists counts as unassigned rather than
 * vanishing. No user-facing copy — the screen turns a level into a message key.
 */

export interface TableLike {
  id: string
  capacity: number
}

export interface SeatGuestLike {
  id: string
  pax: number
  /** Table id, or absent for not-yet-seated. */
  table?: string
  quota?: QuotaSide
}

export type SeatLevel = 'empty' | 'ok' | 'full' | 'over'

export interface TableOccupancy {
  tableId: string
  capacity: number
  seated: number
  free: number
  guestCount: number
  level: SeatLevel
}

export interface SeatingPlan {
  tables: TableOccupancy[]
  totalCapacity: number
  seatedPax: number
  unassignedGuests: number
  unassignedPax: number
}

function level(seated: number, capacity: number): SeatLevel {
  if (seated === 0) return 'empty'
  if (capacity > 0 && seated > capacity) return 'over'
  if (capacity > 0 && seated === capacity) return 'full'
  return 'ok'
}

export function seatingPlan(
  tables: readonly TableLike[],
  guests: readonly SeatGuestLike[],
): SeatingPlan {
  const ids = new Set(tables.map((t) => t.id))
  const rows = tables.map((t) => {
    const seatedGuests = guests.filter((g) => g.table === t.id)
    const seated = seatedGuests.reduce((s, g) => s + Math.max(0, g.pax), 0)
    const capacity = Math.max(0, t.capacity)
    return {
      tableId: t.id,
      capacity,
      seated,
      free: capacity - seated,
      guestCount: seatedGuests.length,
      level: level(seated, capacity),
    }
  })

  const unassigned = guests.filter((g) => !g.table || !ids.has(g.table))
  return {
    tables: rows,
    totalCapacity: rows.reduce((s, r) => s + r.capacity, 0),
    seatedPax: rows.reduce((s, r) => s + r.seated, 0),
    unassignedGuests: unassigned.length,
    unassignedPax: unassigned.reduce((s, g) => s + Math.max(0, g.pax), 0),
  }
}
