/**
 * Souvenir / hantaran reconciliation against the guest list (W17).
 *
 * How many you ordered vs how many you'll hand out. The "need" is a *range*, not
 * a single number: at least the confirmed-RSVP pax (the floor everyone agrees
 * is coming) and at most every invited pax (the ceiling if all say yes). The
 * screen shows both — TemuDua never presents a headcount guess as a fact.
 *
 * Numeric outputs and level keys only; no copy, no database.
 */

export interface SouvenirLike {
  id: string
  /** How many made/bought. */
  ordered: number
  /** How many per guest row. Defaults to 1. */
  perGuest?: number
  /** How many physically received from the vendor, if tracked. */
  received?: number
}

export type StockLevel = 'unknown' | 'short' | 'tight' | 'enough'

export interface SouvenirRow {
  id: string
  ordered: number
  received: number
  perGuest: number
  /** confirmed pax × perGuest — the floor you definitely need. */
  neededMin: number
  /** invited pax × perGuest — the ceiling if everyone comes. */
  neededMax: number
  level: StockLevel
}

/**
 * `confirmedPax` = pax who have replied yes; `invitedPax` = all pax on the list.
 * `short` = won't even cover the confirmed floor; `tight` = covers confirmed but
 * not the full invited list; `enough` = covers everyone invited; `unknown` = no
 * guests entered yet, so there is nothing to reconcile against.
 */
export function souvenirReconcile(
  items: readonly SouvenirLike[],
  confirmedPax: number,
  invitedPax: number,
): SouvenirRow[] {
  return items.map((it) => {
    const perGuest = it.perGuest && it.perGuest > 0 ? it.perGuest : 1
    const ordered = Math.max(0, it.ordered)
    const neededMin = Math.max(0, confirmedPax) * perGuest
    const neededMax = Math.max(0, invitedPax) * perGuest
    let lvl: StockLevel
    if (invitedPax <= 0 && confirmedPax <= 0) lvl = 'unknown'
    else if (ordered < neededMin) lvl = 'short'
    else if (ordered < neededMax) lvl = 'tight'
    else lvl = 'enough'
    return {
      id: it.id,
      ordered,
      received: Math.max(0, it.received ?? 0),
      perGuest,
      neededMin,
      neededMax,
      level: lvl,
    }
  })
}
