import { addDays, format, parseISO } from 'date-fns'
import type { EventType } from './types'

/**
 * Smart checklist (WED-06).
 *
 * The list is a pure function of (wedding date, which events exist, what the
 * couple already ticked). Nothing is materialised into the database, so moving
 * the akad by two weeks moves every row with it and deleting an event removes
 * its steps instead of leaving orphans behind.
 *
 * Copy lives in `messages.ts` under `wedding2.chk.<key>` — this module returns
 * keys only, per the "business logic returns keys, never copy" rule.
 */

export const CHECKLIST_MIN_OFFSET = -365
export const CHECKLIST_MAX_OFFSET = 30

export interface ChecklistTemplateItem {
  key: string
  /** Days relative to the wedding date. Negative is before, positive is after. */
  offsetDays: number
  /** Only included when at least one of these events exists. Undefined = always. */
  needs?: readonly EventType[]
}

/**
 * Generic planning steps only. Nothing here asserts a legal requirement, a
 * price, a vendor, or a date set by anyone but the couple — the app has no way
 * to know a given region's rules, so it prompts and never prescribes.
 */
export const CHECKLIST_TEMPLATE = [
  { key: 'sepakat', offsetDays: -365 },
  { key: 'pagu', offsetDays: -330 },
  { key: 'tamuKasar', offsetDays: -300 },
  { key: 'surveiTempat', offsetDays: -270, needs: ['resepsi', 'akad', 'pemberkatan'] },
  { key: 'bookingTempat', offsetDays: -240, needs: ['resepsi', 'akad', 'pemberkatan'] },
  { key: 'berkas', offsetDays: -210 },
  { key: 'rundownLamaran', offsetDays: -200, needs: ['lamaran'] },
  { key: 'fotoVideo', offsetDays: -180 },
  { key: 'seserahan', offsetDays: -160, needs: ['lamaran', 'sangjit'] },
  { key: 'katering', offsetDays: -150, needs: ['resepsi', 'ngunduh_mantu'] },
  { key: 'busana', offsetDays: -120 },
  { key: 'undanganDesain', offsetDays: -90 },
  { key: 'kuotaTamu', offsetDays: -75 },
  { key: 'sebarUndangan', offsetDays: -60 },
  { key: 'fitting', offsetDays: -45 },
  { key: 'rundownPengajian', offsetDays: -40, needs: ['pengajian'] },
  { key: 'rundownSiraman', offsetDays: -35, needs: ['siraman', 'midodareni'] },
  { key: 'pelunasanTermin', offsetDays: -30 },
  { key: 'techMeeting', offsetDays: -21 },
  { key: 'konfirmasiRsvp', offsetDays: -14 },
  { key: 'rundownAkad', offsetDays: -10, needs: ['akad', 'pemberkatan'] },
  { key: 'gladi', offsetDays: -7 },
  { key: 'packing', offsetDays: -3 },
  { key: 'istirahat', offsetDays: -1 },
  { key: 'kembalikanSewaan', offsetDays: 1 },
  { key: 'terimaKasih', offsetDays: 7 },
  { key: 'sisaPelunasan', offsetDays: 14 },
  { key: 'ngunduhMantu', offsetDays: 21, needs: ['ngunduh_mantu'] },
  { key: 'arsip', offsetDays: 30 },
] as const satisfies readonly ChecklistTemplateItem[]

/** Literal union, so `t('wedding2.chk.' + key)` stays a compile-time check. */
export type CheckKey = (typeof CHECKLIST_TEMPLATE)[number]['key']

export type CheckStatus = 'todo' | 'done' | 'skip'

export interface ChecklistItem {
  key: CheckKey
  offsetDays: number
  /** Undefined until a wedding date exists — the steps still show, undated. */
  dueDate?: string
  status: CheckStatus
  /** Its date has arrived or passed. */
  due: boolean
  /** Due and still untouched. */
  overdue: boolean
}

export function buildChecklist(opts: {
  anchorDate?: string
  eventTypes: readonly EventType[]
  state: Readonly<Record<string, 'done' | 'skip'>>
  today?: string
}): ChecklistItem[] {
  const { anchorDate, eventTypes, state } = opts
  const today = opts.today ?? format(new Date(), 'yyyy-MM-dd')
  const present = new Set(eventTypes)

  // `as const` on the template makes `needs` absent (not optional) on the rows
  // that never had it, so it has to be read through an `in` check.
  const needsOf = (item: (typeof CHECKLIST_TEMPLATE)[number]): readonly EventType[] | undefined =>
    'needs' in item ? item.needs : undefined

  return CHECKLIST_TEMPLATE.filter((item) => {
    const needs = needsOf(item)
    return !needs || needs.some((n) => present.has(n))
  })
    .map((item) => {
      const dueDate = anchorDate
        ? format(addDays(parseISO(anchorDate), item.offsetDays), 'yyyy-MM-dd')
        : undefined
      const status: CheckStatus = state[item.key] ?? 'todo'
      const due = dueDate !== undefined && dueDate <= today
      return { key: item.key, offsetDays: item.offsetDays, dueDate, status, due, overdue: due && status === 'todo' }
    })
    .sort((a, b) => a.offsetDays - b.offsetDays)
}

/** Progress over the steps that are actually relevant, for the dashboard. */
export function checklistProgress(items: readonly ChecklistItem[]): {
  handled: number
  total: number
  overdue: number
} {
  return {
    handled: items.filter((i) => i.status !== 'todo').length,
    total: items.length,
    overdue: items.filter((i) => i.overdue).length,
  }
}
