/**
 * Shot list (W33) and music/moment cues (W34).
 *
 * Two small "how ready is this list" tallies. Shots track what has been captured;
 * cues track which moments actually have a song picked. Both are the couple's own
 * lists — nothing is generated, nothing is scored.
 *
 * Structural in, numbers out — no copy, no database.
 */

import type { ShotPriority } from './types'

// -- W33 shot list ---------------------------------------------------------

export interface ShotLike {
  priority: ShotPriority
  done?: boolean
}

export interface ShotProgress {
  total: number
  doneCount: number
  /** must-have shots (`wajib`). */
  mustTotal: number
  mustDone: number
  /** must-haves not yet captured. The thing to chase before the light goes. */
  mustOutstanding: number
}

export function shotProgress(shots: readonly ShotLike[]): ShotProgress {
  let doneCount = 0
  let mustTotal = 0
  let mustDone = 0
  for (const s of shots) {
    if (s.done) doneCount += 1
    if (s.priority === 'wajib') {
      mustTotal += 1
      if (s.done) mustDone += 1
    }
  }
  return {
    total: shots.length,
    doneCount,
    mustTotal,
    mustDone,
    mustOutstanding: mustTotal - mustDone,
  }
}

// -- W34 music / moment cues ----------------------------------------------

export interface CueLike {
  track?: string
}

export interface CueProgress {
  total: number
  /** cues with a song actually chosen. */
  withTrack: number
  /** cues still missing a song. */
  missingTrack: number
}

export function cueProgress(cues: readonly CueLike[]): CueProgress {
  const withTrack = cues.filter((c) => (c.track ?? '').trim() !== '').length
  return { total: cues.length, withTrack, missingTrack: cues.length - withTrack }
}
