import { useEffect, useMemo, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n } from '@/i18n'
import { fmtDate, whenLabel } from '@/i18n/format'
import { anchorDate } from './plannerMath'
import { withResolvedDates } from './deps'
import { checkinReconcile, issueSummary, liveRundown } from './dday'
import {
  ISSUE_SEVERITY,
  RUNDOWN_ROLES,
  type IssueSeverity,
  type PlannerOf,
  type PlannerRecord,
  type RundownRole,
} from './types'

/**
 * D-day command center (W21–W25).
 *
 * One surface for the day itself: the live rundown with its current and next
 * item (W24), the minute-by-minute builder that feeds it (W22) with roles (W23),
 * the check-in reconciliation against catering (W21), and a calm issue log (W25).
 * Everything reads from IndexedDB via useOwned() and writes via newEnvelope/patch;
 * it all works with no signal, because the whole day often runs in a hall basement.
 */

const ROLE_CHIP: Record<RundownRole, string> = {
  mc: 'chip chip--blue',
  foto: 'chip chip--mint',
  rias: 'chip chip--yellow',
  keluarga: 'chip',
  vendor: 'chip',
  lainnya: 'chip',
}

const SEV_CHIP: Record<IssueSeverity, string> = {
  catatan: 'chip',
  kendala: 'chip chip--yellow',
  penting: 'chip chip--blue',
}

export function DdayTab({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const rows = useOwned<PlannerRecord>('wedding', me)
  const [eventId, setEventId] = useState<string | null>(null)
  const [rundownOpen, setRundownOpen] = useState(false)
  const [editLine, setEditLine] = useState<string | null>(null)
  const [issueOpen, setIssueOpen] = useState(false)

  // A ticking clock so the current/next item follows the day without a refresh.
  const [now, setNow] = useState(() => new Date())
  useEffect(() => {
    const id = window.setInterval(() => setNow(new Date()), 30_000)
    return () => clearInterval(id)
  }, [])
  const nowMin = now.getHours() * 60 + now.getMinutes()

  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is PlannerOf<K> => r.kind === kind)

  const events = withResolvedDates(of('wed_event')).sort((a, b) =>
    (a.date ?? '9999').localeCompare(b.date ?? '9999'),
  )
  const rundowns = of('wed_rundown')
  const guests = of('wed_guest2')
  const issues = of('wed_issue')
  const catering = of('wed_catering').at(-1)

  const nameOf = (e: PlannerOf<'wed_event'>) => e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const)

  // Default the focus to the anchor event (the one the countdown hangs off).
  const anchor = anchorDate(events)
  const defaultEventId =
    events.find((e) => e.date && e.date === anchor)?.id ?? events[0]?.id ?? null
  const focusId = eventId && events.some((e) => e.id === eventId) ? eventId : defaultEventId
  const focus = events.find((e) => e.id === focusId)

  const lines = useMemo(
    () =>
      rundowns
        .filter((r) => r.eventId === focusId)
        .sort((a, b) => a.time.localeCompare(b.time)),
    [rundowns, focusId],
  )
  const pos = liveRundown(lines, nowMin)
  const current = lines.find((l) => l.id === pos.currentId)
  const next = lines.find((l) => l.id === pos.nextId)

  const recon = checkinReconcile(guests, catering?.pax)
  const issueStat = issueSummary(issues)

  const roleLabel = (r?: RundownRole) => (r ? t(`wedding2.dday.role.${r}` as const) : '')
  const lineWho = (l?: PlannerOf<'wed_rundown'>) =>
    l ? [roleLabel(l.role), l.who?.trim()].filter(Boolean).join(' · ') : ''

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.dday.intro')}</p>

      {events.length === 0 ? (
        <EmptyState icon="calendar" title={t('wedding2.dday.noEvents')} hint={t('wedding2.dday.noEventsHint')} />
      ) : (
        <>
          {/* Event focus + clock -------------------------------------- */}
          <Card title={t('wedding2.dday.center')} icon="ring">
            <Field label={t('wedding2.dday.pickEvent')}>
              {(p) => (
                <select {...p} value={focusId ?? ''} onChange={(e) => setEventId(e.target.value)}>
                  {events.map((e) => (
                    <option key={e.id} value={e.id}>
                      {nameOf(e)}
                      {e.date ? ` — ${fmtDate(e.date, 'd MMM', locale)}` : ''}
                    </option>
                  ))}
                </select>
              )}
            </Field>
            <p className="card__hint">
              <Icon name="calendar" size={16} />{' '}
              {focus?.date
                ? t('wedding2.dday.eventDate', { date: fmtDate(focus.date, 'EEEE, d MMM yyyy', locale) })
                : t('wedding2.dday.noDate')}{' '}
              · {t('wedding2.dday.clock', { time: fmtDate(now.toISOString(), 'HH:mm', locale) })}
            </p>

            {/* W24: current + next --------------------------------- */}
            <div className="stack stack--tight" style={{ marginTop: 'var(--space-2)' }}>
              <span className="chip chip--mint">{t('wedding2.dday.nowLabel')}</span>
              {current ? (
                <div className="row" style={{ gap: 8, alignItems: 'baseline' }}>
                  <span className="chip chip--blue">{current.time}</span>
                  <strong className="grow" style={{ fontSize: 15 }}>{current.what}</strong>
                </div>
              ) : (
                <p className="card__hint">{lines.length === 0 ? t('wedding2.dday.noRundown') : t('wedding2.dday.beforeStart')}</p>
              )}
              {current && lineWho(current) && <p className="card__hint">{t('wedding2.dday.onIt', { who: lineWho(current) })}</p>}

              <span className="chip" style={{ marginTop: 'var(--space-2)' }}>{t('wedding2.dday.nextLabel')}</span>
              {next ? (
                <div className="row" style={{ gap: 8, alignItems: 'baseline' }}>
                  <span className="chip">{next.time}</span>
                  <span className="grow">{next.what}</span>
                </div>
              ) : (
                <p className="card__hint">{lines.length === 0 ? '—' : t('wedding2.dday.done')}</p>
              )}
              {next && lineWho(next) && <p className="card__hint">{t('wedding2.dday.onIt', { who: lineWho(next) })}</p>}
            </div>

            {/* W23: who to call — everyone with a name on the day --- */}
            {(() => {
              const called = lines.filter((l) => l.who?.trim())
              if (called.length === 0) return null
              return (
                <div className="stack stack--tight" style={{ marginTop: 'var(--space-3)' }}>
                  <strong style={{ fontSize: 13 }}>{t('wedding2.dday.whoToCall')}</strong>
                  <ul className="list">
                    {called.map((l) => (
                      <li key={l.id} className="list__item">
                        <span className={ROLE_CHIP[l.role ?? 'lainnya']}>{roleLabel(l.role) || t('wedding2.dday.role.lainnya')}</span>
                        <span className="grow">{l.who}</span>
                        <span className="chip">{l.time}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )
            })()}
            <p className="disclaimer">{t('wedding2.dday.centerCaveat')}</p>
          </Card>

          {/* W22/W23: rundown builder --------------------------------- */}
          <Card
            title={t('wedding2.dday.rundownFor', { name: focus ? nameOf(focus) : '' })}
            icon="tasks"
            hint={t('wedding2.dday.rundownHint')}
            action={
              <button className="btn btn--sm" onClick={() => { setEditLine(null); setRundownOpen(true) }}>
                <Icon name="plus" size={16} /> {t('wedding2.dday.addLine')}
              </button>
            }
          >
            {lines.length === 0 ? (
              <EmptyState icon="tasks" title={t('wedding2.dday.noRundown')} hint={t('wedding2.dday.noRundownHint')} />
            ) : (
              <ul className="list">
                {lines.map((l) => {
                  const isNow = l.id === pos.currentId
                  const badTime = pos.badTimeIds.includes(l.id)
                  return (
                    <li key={l.id} className="list__item" style={isNow ? { background: 'var(--surface-2, transparent)' } : undefined}>
                      <button
                        className="btn btn--ghost btn--sm btn--icon"
                        onClick={() => patch('wedding', l.id, { done: !l.done })}
                        aria-label={l.done ? t('wedding2.dday.reopen') : t('wedding2.dday.markDone')}
                      >
                        <Icon name="check" size={16} />
                      </button>
                      <span className="grow stack stack--tight">
                        <span className="row" style={{ gap: 6, flexWrap: 'wrap', alignItems: 'baseline' }}>
                          <span className={badTime ? 'chip chip--yellow' : isNow ? 'chip chip--blue' : 'chip'}>{l.time}</span>
                          {l.durationMin ? <span className="chip">{t('wedding2.dday.dur', { n: l.durationMin })}</span> : null}
                          <strong style={{ fontSize: 14, opacity: l.done ? 0.55 : 1 }}>{l.what}</strong>
                        </span>
                        {(l.role || l.who) && (
                          <span className="row" style={{ gap: 6, flexWrap: 'wrap' }}>
                            {l.role && <span className={ROLE_CHIP[l.role]}>{roleLabel(l.role)}</span>}
                            {l.who && <span className="card__hint">{l.who}</span>}
                          </span>
                        )}
                        {badTime && <span className="card__hint">{t('wedding2.dday.badTime')}</span>}
                      </span>
                      <button className="btn btn--ghost btn--sm" onClick={() => { setEditLine(l.id); setRundownOpen(true) }}>
                        {t('wedding2.dday.edit')}
                      </button>
                      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', l.id, me)}>
                        <Icon name="close" size={16} label={t('common.deleteX', { name: l.what })} />
                      </button>
                    </li>
                  )
                })}
              </ul>
            )}
          </Card>

          {/* W21: check-in reconciliation ----------------------------- */}
          <Card title={t('wedding2.dday.recon')} icon="checkin" hint={t('wedding2.dday.reconHint')}>
            <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
              <span className="chip chip--mint">{t('wedding2.dday.arrived', { g: recon.arrivedGuests, p: recon.arrivedPax })}</span>
              <span className="chip">{t('wedding2.dday.expected', { n: recon.expectedPax })}</span>
              {recon.noShowGuests > 0 && (
                <span className="chip chip--yellow">{t('wedding2.dday.noShow', { g: recon.noShowGuests, p: recon.noShowPax })}</span>
              )}
              {recon.walkInGuests > 0 && (
                <span className="chip chip--blue">{t('wedding2.dday.walkIn', { g: recon.walkInGuests, p: recon.walkInPax })}</span>
              )}
            </div>

            <div style={{ marginTop: 'var(--space-3)' }}>
              <CateringField me={me} existing={catering} />
            </div>
            {recon.cateringLevel === 'unknown' ? (
              <p className="card__hint">{t('wedding2.dday.cateringNone')}</p>
            ) : recon.cateringLevel === 'exact' ? (
              <p className="card__hint"><Icon name="check" size={16} /> {t('wedding2.dday.cateringExact', { n: recon.cateringPax ?? 0 })}</p>
            ) : recon.cateringLevel === 'under' ? (
              <p className="card__hint">{t('wedding2.dday.cateringUnder', { n: Math.abs(recon.cateringDiff ?? 0), cat: recon.cateringPax ?? 0 })}</p>
            ) : (
              <p className="banner"><Icon name="info" size={16} /> {t('wedding2.dday.cateringOver', { n: recon.cateringDiff ?? 0, cat: recon.cateringPax ?? 0 })}</p>
            )}
            <p className="disclaimer">{t('wedding2.dday.reconCaveat')}</p>
          </Card>

          {/* W25: issue log ------------------------------------------- */}
          <Card
            title={t('wedding2.dday.issues')}
            icon="info"
            hint={t('wedding2.dday.issuesHint')}
            action={
              <button className="btn btn--sm" onClick={() => setIssueOpen(true)}>
                <Icon name="plus" size={16} /> {t('wedding2.dday.addIssue')}
              </button>
            }
          >
            {issues.length === 0 ? (
              <EmptyState icon="check" title={t('wedding2.dday.noIssues')} hint={t('wedding2.dday.noIssuesHint')} />
            ) : (
              <>
                <div className="row" style={{ flexWrap: 'wrap', gap: 6, marginBottom: 'var(--space-2)' }}>
                  <span className="chip">{t('wedding2.dday.issOpen', { n: issueStat.open })}</span>
                  <span className="chip chip--mint">{t('wedding2.dday.issDone', { n: issueStat.resolved })}</span>
                </div>
                <ul className="list">
                  {issues
                    .slice()
                    .sort((a, b) => b.at.localeCompare(a.at))
                    .map((iss) => (
                      <li key={iss.id} className="list__item">
                        <span className="grow stack stack--tight">
                          <span className="row" style={{ gap: 6, flexWrap: 'wrap', alignItems: 'baseline' }}>
                            <span className={SEV_CHIP[iss.severity]}>{t(`wedding2.dday.sev.${iss.severity}` as const)}</span>
                            <strong style={{ fontSize: 14, opacity: iss.resolvedAt ? 0.55 : 1 }}>{iss.what}</strong>
                          </span>
                          <span className="card__hint">
                            {whenLabel(iss.at, t, locale)}
                            {iss.resolvedAt ? ` · ${t('wedding2.dday.resolvedAt', { when: whenLabel(iss.resolvedAt, t, locale) })}` : ''}
                          </span>
                          {iss.note && <span className="card__hint">{iss.note}</span>}
                        </span>
                        <button
                          className="btn btn--ghost btn--sm"
                          onClick={() => patch('wedding', iss.id, { resolvedAt: iss.resolvedAt ? undefined : new Date().toISOString() })}
                        >
                          {iss.resolvedAt ? t('wedding2.dday.reopen') : t('wedding2.dday.resolve')}
                        </button>
                        <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', iss.id, me)}>
                          <Icon name="close" size={16} label={t('common.deleteX', { name: iss.what })} />
                        </button>
                      </li>
                    ))}
                </ul>
              </>
            )}
          </Card>
        </>
      )}

      <RundownSheet
        open={rundownOpen}
        eventId={focusId ?? ''}
        editing={editLine ? rundowns.find((r) => r.id === editLine) : undefined}
        onClose={() => { setRundownOpen(false); setEditLine(null) }}
        me={me}
      />
      <IssueSheet open={issueOpen} onClose={() => setIssueOpen(false)} me={me} />
    </div>
  )
}

function CateringField({ me, existing }: { me: string; existing?: PlannerOf<'wed_catering'> }) {
  const { t } = useI18n()
  const [val, setVal] = useState('')
  useEffect(() => { setVal(existing ? String(existing.pax) : '') }, [existing?.id, existing?.pax])

  async function commit() {
    const n = Math.max(0, Number(val) || 0)
    if (existing) await patch('wedding', existing.id, { pax: n })
    else if (n > 0) await db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), kind: 'wed_catering', pax: n } as never)
  }

  return (
    <Field label={t('wedding2.dday.cateringPax')} hint={t('wedding2.dday.cateringPaxHint')}>
      {(p) => (
        <input
          {...p}
          type="number"
          min="0"
          inputMode="numeric"
          value={val}
          onChange={(e) => setVal(e.target.value)}
          onBlur={commit}
        />
      )}
    </Field>
  )
}

function RundownSheet({
  open,
  eventId,
  editing,
  onClose,
  me,
}: {
  open: boolean
  eventId: string
  editing?: PlannerOf<'wed_rundown'>
  onClose: () => void
  me: string
}) {
  const { t } = useI18n()
  const [time, setTime] = useState('')
  const [what, setWhat] = useState('')
  const [dur, setDur] = useState('')
  const [role, setRole] = useState<RundownRole | ''>('')
  const [who, setWho] = useState('')

  const seed = editing?.id ?? 'new'
  useEffect(() => {
    setTime(editing?.time ?? '')
    setWhat(editing?.what ?? '')
    setDur(editing?.durationMin ? String(editing.durationMin) : '')
    setRole(editing?.role ?? '')
    setWho(editing?.who ?? '')
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seed, open])

  async function save() {
    if (!time.trim() || !what.trim()) return
    const fields = {
      time: time.trim(),
      what: what.trim(),
      durationMin: dur ? Math.max(0, Number(dur) || 0) : undefined,
      role: role || undefined,
      who: who.trim() || undefined,
    }
    if (editing) await patch('wedding', editing.id, fields)
    else await db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), kind: 'wed_rundown', eventId, ...fields } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={editing ? t('wedding2.dday.editLine') : t('wedding2.dday.addLine')}>
      <div className="stack">
        <Field label={t('wedding2.dday.fTime')}>
          {(p) => <input {...p} type="time" value={time} onChange={(e) => setTime(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.dday.fWhat')}>
          {(p) => <input {...p} type="text" value={what} onChange={(e) => setWhat(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.dday.fDur')} hint={t('common.optional')}>
          {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={dur} onChange={(e) => setDur(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.dday.fRole')} hint={t('common.optional')}>
          {(p) => (
            <select {...p} value={role} onChange={(e) => setRole(e.target.value as RundownRole | '')}>
              <option value="">{t('wedding2.dday.role.none')}</option>
              {RUNDOWN_ROLES.map((r) => (
                <option key={r} value={r}>{t(`wedding2.dday.role.${r}` as const)}</option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('wedding2.dday.fWho')} hint={t('wedding2.dday.fWhoHint')}>
          {(p) => <input {...p} type="text" value={who} onChange={(e) => setWho(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save}>{t('common.save')}</button>
      </div>
    </Sheet>
  )
}

function IssueSheet({ open, onClose, me }: { open: boolean; onClose: () => void; me: string }) {
  const { t } = useI18n()
  const [what, setWhat] = useState('')
  const [severity, setSeverity] = useState<IssueSeverity>('kendala')
  const [note, setNote] = useState('')

  useEffect(() => { if (open) { setWhat(''); setSeverity('kendala'); setNote('') } }, [open])

  async function save() {
    if (!what.trim()) return
    await db.wedding.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'wed_issue',
      at: new Date().toISOString(),
      what: what.trim(),
      severity,
      note: note.trim() || undefined,
    } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('wedding2.dday.addIssue')}>
      <div className="stack">
        <Field label={t('wedding2.dday.fIssue')} hint={t('wedding2.dday.fIssueHint')}>
          {(p) => <input {...p} type="text" value={what} onChange={(e) => setWhat(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.dday.fSeverity')}>
          {(p) => (
            <select {...p} value={severity} onChange={(e) => setSeverity(e.target.value as IssueSeverity)}>
              {ISSUE_SEVERITY.map((s) => (
                <option key={s} value={s}>{t(`wedding2.dday.sev.${s}` as const)}</option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('wedding2.fNote')} hint={t('common.optional')}>
          {(p) => <textarea {...p} value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save}>{t('common.save')}</button>
      </div>
    </Sheet>
  )
}
