/**
 * Day-of logistics (W26 offline, W28 attire, W29 prep critical path, W30 transport).
 *
 * All four live together because they are the "getting bodies, clothes, and cars
 * to the right place with no signal" side of the day. Everything renders from
 * IndexedDB via useOwned() and writes through newEnvelope/patch — no network is
 * touched anywhere, which is the whole point of the offline card up top.
 */

// -- live online/offline status (W26) --------------------------------------
function subscribeOnline(cb: () => void) {
  window.addEventListener('online', cb)
  window.addEventListener('offline', cb)
  return () => {
    window.removeEventListener('online', cb)
    window.removeEventListener('offline', cb)
  }
}
function useOnline(): boolean {
  return useSyncExternalStore(
    subscribeOnline,
    () => navigator.onLine,
    () => true,
  )
}

/** minutes-since-midnight → "HH:MM". Clamps a below-midnight time to a "-" prefix day-before read. */
function hm(min: number): string {
  const wrapped = ((min % 1440) + 1440) % 1440
  const h = Math.floor(wrapped / 60)
  const m = wrapped % 60
  const s = `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`
  return min < 0 ? `−${s}` : s
}

export function LogisticsTab({ me }: { me: string }) {
  const { t } = useI18n()
  const rows = useOwned<PlannerRecord>('wedding', me)
  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is PlannerOf<K> => r.kind === kind)

  const events = of('wed_event')
  const eventLabel = (id?: string) => {
    if (!id) return t('wedding2.log.allEvents')
    const e = events.find((x) => x.id === id)
    return e ? (e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const)) : t('wedding2.log.eventGone')
  }

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.log.intro')}</p>
      <OfflineCard rows={rows} />
      <PrepCard me={me} prep={of('wed_prep')} setup={of('wed_daySetup')[0]} />
      <AttireCard me={me} items={of('wed_attire')} events={events} eventLabel={eventLabel} />
      <TransportCard me={me} legs={of('wed_transport')} events={events} eventLabel={eventLabel} />
    </div>
  )
}

// -- W26 offline -----------------------------------------------------------
function OfflineCard({ rows }: { rows: PlannerRecord[] | undefined }) {
  const { t } = useI18n()
  const online = useOnline()
  const count = (k: PlannerRecord['kind']) => (rows ?? []).filter((r) => r.kind === k).length
  const ready = offlineReadiness({
    guests: count('wed_guest2'),
    rundown: count('wed_rundown'),
    prep: count('wed_prep'),
    transport: count('wed_transport'),
    docs: count('wed_doc'),
    tables: count('wed_table'),
  })

  return (
    <Card title={t('wedding2.off.title')} icon="shield" hint={t('wedding2.off.hint')}>
      <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
        <span className={online ? 'chip' : 'chip chip--mint'}>
          <Icon name={online ? 'info' : 'check'} size={14} />{' '}
          {online ? t('wedding2.off.online') : t('wedding2.off.offline')}
        </span>
        <span className="chip chip--blue">{t('wedding2.off.ready', { n: ready.readyCount, total: ready.total })}</span>
      </div>
      <p className="card__hint">{t('wedding2.off.guarantee')}</p>
      <ul className="list">
        {ready.essentials.map((e) => (
          <li key={e.key} className="list__item">
            <Icon name={e.present ? 'check' : 'info'} size={16} />
            <span className="grow">{t(`wedding2.off.ess.${e.key}` as const)}</span>
            <span className={e.present ? 'chip chip--mint' : 'chip chip--yellow'}>
              {e.present ? t('wedding2.off.have', { n: e.count }) : t('wedding2.off.missing')}
            </span>
          </li>
        ))}
      </ul>
      {!ready.allReady && <p className="card__hint">{t('wedding2.off.captureHint')}</p>}
    </Card>
  )
}

// -- W29 prep critical path ------------------------------------------------
function PrepCard({
  me,
  prep,
  setup,
}: {
  me: string
  prep: PlannerOf<'wed_prep'>[]
  setup?: PlannerOf<'wed_daySetup'>
}) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)

  const readyByMin = setup?.readyBy ? parseHm(setup.readyBy) : null
  const plan = readyByMin != null ? prepSchedule(prep, readyByMin) : null

  async function setReadyBy(value: string) {
    if (setup) await patch('wedding', setup.id, { readyBy: value || undefined })
    else await db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), kind: 'wed_daySetup', readyBy: value || undefined } as never)
  }

  const slotById = (id: string) => plan?.slots.find((s) => s.id === id)

  return (
    <Card
      title={t('wedding2.prep.title')}
      icon="calendar"
      hint={t('wedding2.prep.hint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('wedding2.prep.add')}
        </button>
      }
    >
      <Field label={t('wedding2.prep.readyBy')} hint={t('wedding2.prep.readyByHint')}>
        {(p) => (
          <input
            {...p}
            type="time"
            value={setup?.readyBy ?? ''}
            onChange={(e) => setReadyBy(e.target.value)}
          />
        )}
      </Field>

      {prep.length === 0 ? (
        <EmptyState icon="calendar" title={t('wedding2.prep.empty')} hint={t('wedding2.prep.emptyHint')} />
      ) : readyByMin == null ? (
        <p className="card__hint">{t('wedding2.prep.needReadyBy')}</p>
      ) : (
        <>
          <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
            <span className="chip chip--blue">{t('wedding2.prep.firstAlarm', { time: hm(plan!.earliestStartMin) })}</span>
          </div>
          {plan!.tooEarly && (
            <p className="banner">
              <Icon name="info" size={16} /> {t('wedding2.prep.tooEarly')}
            </p>
          )}
          {plan!.perPerson.map((pp) => {
            const items = prep
              .filter((x) => x.person === pp.person)
              .map((x) => ({ x, slot: slotById(x.id) }))
              .filter((r): r is { x: PlannerOf<'wed_prep'>; slot: NonNullable<ReturnType<typeof slotById>> } => !!r.slot)
              .sort((a, b) => a.slot.startMin - b.slot.startMin)
            return (
              <div key={pp.person} className="stack stack--tight" style={{ marginBottom: 'var(--space-3)' }}>
                <strong style={{ fontSize: 13 }}>
                  {pp.person} <span className="chip">{t('wedding2.prep.starts', { time: hm(pp.startMin) })}</span>
                </strong>
                <ul className="list">
                  {items.map(({ x, slot }) => (
                    <li key={x.id} className="list__item">
                      <span className="chip">{hm(slot.startMin)}–{hm(slot.endMin)}</span>
                      <span className="grow stack stack--tight">
                        <strong style={{ fontSize: 14 }}>{x.task}</strong>
                        <span className="card__hint">
                          {t('wedding2.prep.mins', { n: slot.durationMin })}
                          {x.note ? ` · ${x.note}` : ''}
                        </span>
                      </span>
                      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', x.id, me)}>
                        <Icon name="close" size={16} label={t('common.deleteX', { name: x.task })} />
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )
          })}
          <p className="disclaimer">{t('wedding2.prep.caveat')}</p>
        </>
      )}

      <PrepSheet open={open} onClose={() => setOpen(false)} me={me} />
    </Card>
  )
}

function PrepSheet({ open, onClose, me }: { open: boolean; onClose: () => void; me: string }) {
  const { t } = useI18n()
  const [person, setPerson] = useState('')
  const [task, setTask] = useState('')
  const [dur, setDur] = useState('30')
  const [order, setOrder] = useState('')

  useEffect(() => {
    if (open) { setTask(''); setDur('30'); setOrder('') }
  }, [open])

  async function save() {
    if (!person.trim() || !task.trim()) return
    await db.wedding.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'wed_prep',
      person: person.trim(),
      task: task.trim(),
      durationMin: Math.max(0, Number(dur) || 0),
      ...(order ? { order: Number(order) } : {}),
    } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('wedding2.prep.add')}>
      <div className="stack">
        <Field label={t('wedding2.prep.fPerson')} hint={t('wedding2.prep.fPersonHint')}>
          {(p) => <input {...p} type="text" value={person} onChange={(e) => setPerson(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.prep.fTask')}>
          {(p) => <input {...p} type="text" value={task} onChange={(e) => setTask(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.prep.fDur')}>
          {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={dur} onChange={(e) => setDur(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.prep.fOrder')} hint={t('wedding2.prep.fOrderHint')}>
          {(p) => <input {...p} type="number" min="1" inputMode="numeric" value={order} onChange={(e) => setOrder(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!person.trim() || !task.trim()}>{t('common.save')}</button>
      </div>
    </Sheet>
  )
}

// -- W28 attire ------------------------------------------------------------
const ATTIRE_CHIP: Record<AttireStatus, string> = {
  belum: 'chip',
  diukur: 'chip chip--blue',
  proses: 'chip chip--yellow',
  siap: 'chip chip--mint',
}

function AttireCard({
  me,
  items,
  events,
  eventLabel,
}: {
  me: string
  items: PlannerOf<'wed_attire'>[]
  events: PlannerOf<'wed_event'>[]
  eventLabel: (id?: string) => string
}) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)

  const progress = attireProgress(items)
  const byPerson = attireByPerson(items)

  return (
    <Card
      title={t('wedding2.attire.title')}
      icon="self"
      hint={t('wedding2.attire.hint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('wedding2.attire.add')}
        </button>
      }
    >
      {items.length === 0 ? (
        <EmptyState icon="self" title={t('wedding2.attire.empty')} hint={t('wedding2.attire.emptyHint')} />
      ) : (
        <>
          <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
            {ATTIRE_STATES.map((s) => (
              <span key={s} className={ATTIRE_CHIP[s]}>
                {t(`wedding2.attire.st.${s}` as const)}: {progress[s]}
              </span>
            ))}
          </div>
          {byPerson.map((pp) => {
            const list = items
              .filter((x) => x.person === pp.person)
              .sort((a, b) => a.item.localeCompare(b.item))
            return (
              <div key={pp.person} className="stack stack--tight" style={{ marginBottom: 'var(--space-3)' }}>
                <strong style={{ fontSize: 13 }}>
                  {pp.person} <span className="chip chip--mint">{t('wedding2.attire.readyOf', { ready: pp.ready, total: pp.total })}</span>
                </strong>
                <ul className="list">
                  {list.map((x) => (
                    <li key={x.id} className="list__item">
                      <span className="grow stack stack--tight">
                        <strong style={{ fontSize: 14 }}>{x.item}</strong>
                        <span className="card__hint">
                          {eventLabel(x.eventId)}
                          {x.vendor ? ` · ${x.vendor}` : ''}
                          {x.note ? ` · ${x.note}` : ''}
                        </span>
                      </span>
                      <label>
                        <span className="visually-hidden">{`${x.item} — ${t('wedding2.attire.fStatus')}`}</span>
                        <select
                          value={x.status}
                          style={{ minHeight: 36, fontSize: 13 }}
                          onChange={(ev) => patch('wedding', x.id, { status: ev.target.value })}
                        >
                          {ATTIRE_STATES.map((s) => (
                            <option key={s} value={s}>{t(`wedding2.attire.st.${s}` as const)}</option>
                          ))}
                        </select>
                      </label>
                      <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', x.id, me)}>
                        <Icon name="close" size={16} label={t('common.deleteX', { name: x.item })} />
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )
          })}
        </>
      )}

      <AttireSheet open={open} onClose={() => setOpen(false)} me={me} events={events} />
    </Card>
  )
}

