// -- W30 transport ---------------------------------------------------------
function TransportCard({
  me,
  legs,
  events,
  eventLabel,
}: {
  me: string
  legs: PlannerOf<'wed_transport'>[]
  events: PlannerOf<'wed_event'>[]
  eventLabel: (id?: string) => string
}) {
  const { t } = useI18n()
  const [open, setOpen] = useState(false)

  const summary = transportSummary(legs)
  const level = (id: string) => summary.legs.find((l) => l.id === id)!

  return (
    <Card
      title={t('wedding2.trans.title')}
      icon="shared"
      hint={t('wedding2.trans.hint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('wedding2.trans.add')}
        </button>
      }
    >
      {legs.length === 0 ? (
        <EmptyState icon="shared" title={t('wedding2.trans.empty')} hint={t('wedding2.trans.emptyHint')} />
      ) : (
        <>
          <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
            <span className="chip">{t('wedding2.trans.seats', { n: summary.totalCapacity })}</span>
            <span className="chip chip--blue">{t('wedding2.trans.need', { n: summary.totalNeed })}</span>
            {summary.shortfall > 0 && (
              <span className="chip chip--yellow">{t('wedding2.trans.short', { n: summary.shortfall })}</span>
            )}
          </div>
          <ul className="list">
            {legs
              .slice()
              .sort((a, b) => (a.depart ?? '~').localeCompare(b.depart ?? '~') || a.label.localeCompare(b.label))
              .map((l) => {
                const st = level(l.id)
                return (
                  <li key={l.id} className="list__item">
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{l.label}</strong>
                      <span className="card__hint">
                        {eventLabel(l.eventId)}
                        {l.mode ? ` · ${l.mode}` : ''}
                        {l.depart ? ` · ${t('wedding2.trans.departs', { time: l.depart })}` : ''}
                        {l.from || l.to ? ` · ${l.from ?? '?'} → ${l.to ?? '?'}` : ''}
                      </span>
                      {l.note && <span className="card__hint">{l.note}</span>}
                    </span>
                    {st.level !== 'unknown' && (
                      <span className={st.level === 'short' ? 'chip chip--yellow' : 'chip chip--mint'}>
                        {t('wedding2.trans.occ', { cap: st.capacity, need: st.needPax })}
                      </span>
                    )}
                    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', l.id, me)}>
                      <Icon name="close" size={16} label={t('common.deleteX', { name: l.label })} />
                    </button>
                  </li>
                )
              })}
          </ul>
          <p className="disclaimer">{t('wedding2.trans.caveat')}</p>
        </>
      )}

      <TransportSheet open={open} onClose={() => setOpen(false)} me={me} events={events} />
    </Card>
  )
}

function TransportSheet({
  open,
  onClose,
  me,
  events,
}: {
  open: boolean
  onClose: () => void
  me: string
  events: PlannerOf<'wed_event'>[]
}) {
  const { t } = useI18n()
  const [label, setLabel] = useState('')
  const [eventId, setEventId] = useState('')
  const [mode, setMode] = useState('')
  const [capacity, setCapacity] = useState('')
  const [needPax, setNeedPax] = useState('')
  const [depart, setDepart] = useState('')
  const [from, setFrom] = useState('')
  const [to, setTo] = useState('')

  useEffect(() => {
    if (open) { setLabel(''); setMode(''); setCapacity(''); setNeedPax(''); setDepart(''); setFrom(''); setTo('') }
  }, [open])

  async function save() {
    if (!label.trim()) return
    await db.wedding.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'wed_transport',
      label: label.trim(),
      ...(eventId ? { eventId } : {}),
      ...(mode.trim() ? { mode: mode.trim() } : {}),
      ...(capacity ? { capacity: Math.max(0, Number(capacity) || 0) } : {}),
      ...(needPax ? { needPax: Math.max(0, Number(needPax) || 0) } : {}),
      ...(depart ? { depart } : {}),
      ...(from.trim() ? { from: from.trim() } : {}),
      ...(to.trim() ? { to: to.trim() } : {}),
    } as never)
    onClose()
  }

  return (
    <Sheet open={open} onClose={onClose} title={t('wedding2.trans.add')}>
      <div className="stack">
        <Field label={t('wedding2.trans.fLabel')} hint={t('wedding2.trans.fLabelHint')}>
          {(p) => <input {...p} type="text" value={label} onChange={(e) => setLabel(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.trans.fEvent')} hint={t('common.optional')}>
          {(p) => (
            <select {...p} value={eventId} onChange={(e) => setEventId(e.target.value)}>
              <option value="">{t('wedding2.log.allEvents')}</option>
              {events.map((e) => (
                <option key={e.id} value={e.id}>{e.label?.trim() || t(`wedding2.evt.${e.eventType}` as const)}</option>
              ))}
            </select>
          )}
        </Field>
        <Field label={t('wedding2.trans.fMode')} hint={t('wedding2.trans.fModeHint')}>
          {(p) => <input {...p} type="text" value={mode} onChange={(e) => setMode(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.trans.fCapacity')} hint={t('common.optional')}>
          {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={capacity} onChange={(e) => setCapacity(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.trans.fNeed')} hint={t('common.optional')}>
          {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={needPax} onChange={(e) => setNeedPax(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.trans.fDepart')} hint={t('common.optional')}>
          {(p) => <input {...p} type="time" value={depart} onChange={(e) => setDepart(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.trans.fFrom')} hint={t('common.optional')}>
          {(p) => <input {...p} type="text" value={from} onChange={(e) => setFrom(e.target.value)} />}
        </Field>
        <Field label={t('wedding2.trans.fTo')} hint={t('common.optional')}>
          {(p) => <input {...p} type="text" value={to} onChange={(e) => setTo(e.target.value)} />}
        </Field>
        <button className="btn btn--block" onClick={save} disabled={!label.trim()}>{t('common.save')}</button>
      </div>
    </Sheet>
  )
}
