import { INVITE_STATES, type InviteStatus, type QuotaSide } from './types'
import { quotaUsage, type GuestLike, type Quota } from './plannerMath'

/**
 * Guest-list logic (W11–W15).
 *
 * Structural inputs and numeric/key outputs only — no envelope, no database, no
 * user-facing copy. The screen turns a level into a message key; nothing here
 * ever interpolates a guest's name into a warning, because a quota is a family
 * agreement, not a verdict on a person (W13).
 */

export type QuotaLevel = 'ok' | 'near' | 'full' | 'over'

export interface QuotaWarning {
  side: QuotaSide
  used: number
  limit: number
  /** limit − used. Negative once the bucket is over. */
  remaining: number
  level: QuotaLevel
}

/**
 * W12/W13 — one row per family bucket, judged by the bucket alone. `near` trips
 * at 90% so there is room to talk before it is a fight; a bucket with no agreed
 * limit (0) is always `ok`, because an un-negotiated quota is not an overage.
 */
export function quotaWarnings(
  guests: readonly GuestLike[],
  quota?: Quota,
  nearFrac = 0.9,
): QuotaWarning[] {
  return quotaUsage(guests, quota).map(({ side, used, limit }) => {
    let level: QuotaLevel = 'ok'
    if (limit > 0) {
      if (used > limit) level = 'over'
      else if (used === limit) level = 'full'
      else if (used >= limit * nearFrac) level = 'near'
    }
    return { side, used, limit, remaining: limit - used, level }
  })
}

export interface InviteLike {
  invite?: InviteStatus
}

/**
 * W14 — how far each invitation got. An absent field counts as `belum`; we never
 * pre-write a row just to record "not sent yet".
 */
export function inviteFunnel(guests: readonly InviteLike[]): Record<InviteStatus, number> {
  const out = Object.fromEntries(INVITE_STATES.map((s) => [s, 0])) as Record<InviteStatus, number>
  for (const g of guests) out[g.invite ?? 'belum'] += 1
  return out
}

export interface HeadcountLike {
  invite?: InviteStatus
  pax: number
}

/**
 * W15 — confirmed heads: pax summed only over guests who have actually replied
 * (`invite === 'rsvp'`). Everyone else stays an unknown, never counted as a zero
 * and never assumed a yes.
 */
export function confirmedHeadcount(guests: readonly HeadcountLike[]): number {
  return guests
    .filter((g) => g.invite === 'rsvp')
    .reduce((s, g) => s + Math.max(0, g.pax), 0)
}
