import { useEffect, useState } from 'react'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, PARTNER_VISIBILITY_OPTIONS, Sheet, VisibilityBadge } from '@/components/ui'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useOwned } from '@/db/hooks'
import { useI18n } from '@/i18n'
import { formatRupiah } from '@/i18n/format'
import { confirmedHeadcount } from './guests'
import { souvenirReconcile, type StockLevel } from './souvenir'
import { giftTotals } from './gifts'
import type { Visibility } from '@/types/domain'
import type { PlannerOf, PlannerRecord } from './types'

/**
 * Souvenir / hantaran reconciliation (W17) and the angpao / gift record (W18).
 *
 * Souvenirs are checked against the RSVP *range* — confirmed floor to invited
 * ceiling — never a single guessed headcount. Gift rows are `C1_personal`, so
 * private by default; only their owner can widen who sees them, and the tally is
 * described, never turned into advice.
 */

const STOCK_CHIP: Record<StockLevel, string> = {
  unknown: 'chip',
  short: 'chip chip--yellow',
  tight: 'chip chip--blue',
  enough: 'chip chip--mint',
}

export function FavorsTab({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [sheet, setSheet] = useState<'souvenir' | 'gift' | null>(null)
  const [editId, setEditId] = useState<string | null>(null)
  const rows = useOwned<PlannerRecord>('wedding', me)

  const of = <K extends PlannerRecord['kind']>(kind: K) =>
    (rows ?? []).filter((r): r is PlannerOf<K> => r.kind === kind)

  const guests = of('wed_guest2')
  const souvenirs = of('wed_souvenir')
  const gifts = of('wed_gift')

  const confirmed = confirmedHeadcount(guests)
  const invited = guests.reduce((s, g) => s + Math.max(0, g.pax), 0)
  const recon = souvenirReconcile(souvenirs, confirmed, invited)
  const reconOf = (id: string) => recon.find((r) => r.id === id)!
  const totals = giftTotals(gifts)

  const openSouvenir = (id?: string) => { setEditId(id ?? null); setSheet('souvenir') }
  const openGift = (id?: string) => { setEditId(id ?? null); setSheet('gift') }

  return (
    <div className="stack">
      <p className="card__hint">{t('wedding2.fav.intro')}</p>

      {/* Souvenir / hantaran (W17) ----------------------------------- */}
      <Card
        title={t('wedding2.fav.souvenirs')}
        icon="groceries"
        hint={t('wedding2.fav.rangeHint', { min: confirmed, max: invited })}
        action={
          <button className="btn btn--sm" onClick={() => openSouvenir()}>
            <Icon name="plus" size={16} /> {t('wedding2.fav.addSouvenir')}
          </button>
        }
      >
        {souvenirs.length === 0 ? (
          <EmptyState icon="groceries" title={t('wedding2.fav.noSouvenirs')} hint={t('wedding2.fav.noSouvenirsHint')} />
        ) : (
          <ul className="list">
            {souvenirs.map((s) => {
              const r = reconOf(s.id)
              return (
                <li key={s.id} className="list__item">
                  <span className="grow stack stack--tight">
                    <button
                      className="btn btn--ghost btn--sm"
                      style={{ justifyContent: 'flex-start', padding: 0, fontWeight: 600, fontSize: 14 }}
                      onClick={() => openSouvenir(s.id)}
                    >
                      {s.name}
                    </button>
                    <span className="row" style={{ flexWrap: 'wrap', gap: 4 }}>
                      <span className="chip">{t('wedding2.fav.ordered', { n: r.ordered })}</span>
                      {r.perGuest !== 1 && <span className="chip">{t('wedding2.fav.perGuest', { n: r.perGuest })}</span>}
                      {r.received > 0 && <span className="chip">{t('wedding2.fav.received', { n: r.received })}</span>}
                      <span className={STOCK_CHIP[r.level]}>
                        {r.level === 'unknown'
                          ? t('wedding2.fav.needUnknown')
                          : t('wedding2.fav.needRange', { min: r.neededMin, max: r.neededMax })}
                      </span>
                    </span>
                    <span className="card__hint">{t(`wedding2.fav.stock.${r.level}` as const)}</span>
                    {s.note && <span className="card__hint">{s.note}</span>}
                  </span>
                  <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', s.id, me)}>
                    <Icon name="close" size={16} label={t('common.deleteX', { name: s.name })} />
                  </button>
                </li>
              )
            })}
          </ul>
        )}
        <p className="disclaimer">{t('wedding2.fav.souvenirCaveat')}</p>
      </Card>

      {/* Angpao / gifts (W18) ---------------------------------------- */}
      <Card
        title={t('wedding2.gift.card')}
        icon="private"
        hint={t('wedding2.gift.privateHint')}
        action={
          <button className="btn btn--sm" onClick={() => openGift()}>
            <Icon name="plus" size={16} /> {t('wedding2.gift.add')}
          </button>
        }
      >
        {gifts.length === 0 ? (
          <EmptyState icon="private" title={t('wedding2.gift.none')} hint={t('wedding2.gift.noneHint')} />
        ) : (
          <>
            <div className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
              <span className="chip">{t('wedding2.gift.count', { n: totals.count })}</span>
              <span className="chip chip--mint">{t('wedding2.gift.cashTotal', { amount: formatRupiah(totals.cashTotal, locale) })}</span>
              {totals.itemCount > 0 && <span className="chip">{t('wedding2.gift.items', { n: totals.itemCount })}</span>}
            </div>
            <ul className="list">
              {gifts
                .slice()
                .sort((a, b) => a.giver.localeCompare(b.giver))
                .map((g) => (
                  <li key={g.id} className="list__item">
                    <span className="grow stack stack--tight">
                      <button
                        className="btn btn--ghost btn--sm"
                        style={{ justifyContent: 'flex-start', padding: 0, fontWeight: 600, fontSize: 14 }}
                        onClick={() => openGift(g.id)}
                      >
                        {g.giver}
                      </button>
                      <span className="row" style={{ flexWrap: 'wrap', gap: 4 }}>
                        {g.amount ? <span className="chip chip--mint">{formatRupiah(g.amount, locale)}</span> : null}
                        {g.item ? <span className="chip">{g.item}</span> : null}
                      </span>
                      {g.note && <span className="card__hint">{g.note}</span>}
                    </span>
                    <VisibilityBadge visibility={g.visibility} />
                    <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('wedding', g.id, me)}>
                      <Icon name="close" size={16} label={t('common.deleteX', { name: g.giver })} />
                    </button>
                  </li>
                ))}
            </ul>
          </>
        )}
        <p className="disclaimer">{t('wedding2.gift.caveat')}</p>
      </Card>

      <FavorSheet
        kind={sheet}
        editingSouvenir={sheet === 'souvenir' && editId ? souvenirs.find((s) => s.id === editId) : undefined}
        editingGift={sheet === 'gift' && editId ? gifts.find((g) => g.id === editId) : undefined}
        onClose={() => { setSheet(null); setEditId(null) }}
        me={me}
      />
    </div>
  )
}

function FavorSheet({
  kind,
  editingSouvenir,
  editingGift,
  onClose,
  me,
}: {
  kind: 'souvenir' | 'gift' | null
  editingSouvenir?: PlannerOf<'wed_souvenir'>
  editingGift?: PlannerOf<'wed_gift'>
  onClose: () => void
  me: string
}) {
  const { t } = useI18n()
  const [name, setName] = useState('')
  const [ordered, setOrdered] = useState('')
  const [perGuest, setPerGuest] = useState('1')
  const [received, setReceived] = useState('')
  const [note, setNote] = useState('')
  // gift
  const [giver, setGiver] = useState('')
  const [amount, setAmount] = useState('')
  const [item, setItem] = useState('')
  const [visibility, setVisibility] = useState<Visibility>('private')

  const seedKey = editingSouvenir?.id ?? editingGift?.id ?? 'new'
  useEffect(() => {
    if (kind === 'souvenir') {
      setName(editingSouvenir?.name ?? '')
      setOrdered(String(editingSouvenir?.ordered ?? ''))
      setPerGuest(String(editingSouvenir?.perGuest ?? 1))
      setReceived(String(editingSouvenir?.received ?? ''))
      setNote(editingSouvenir?.note ?? '')
    } else if (kind === 'gift') {
      setGiver(editingGift?.giver ?? '')
      setAmount(String(editingGift?.amount ?? ''))
      setItem(editingGift?.item ?? '')
      setNote(editingGift?.note ?? '')
      setVisibility(editingGift?.visibility ?? 'private')
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [seedKey, kind])

  async function save() {
    if (kind === 'souvenir') {
      if (!name.trim()) return
      const fields = {
        name: name.trim(),
        ordered: Math.max(0, Number(ordered) || 0),
        perGuest: Math.max(1, Number(perGuest) || 1),
        received: Math.max(0, Number(received) || 0) || undefined,
        note: note.trim() || undefined,
      }
      if (editingSouvenir) await patch('wedding', editingSouvenir.id, fields)
      else await db.wedding.add({ ...newEnvelope(me, 'C2_shared_ops'), kind: 'wed_souvenir', ...fields } as never)
    } else if (kind === 'gift') {
      if (!giver.trim()) return
      const fields = {
        giver: giver.trim(),
        amount: Math.max(0, Number(amount) || 0) || undefined,
        item: item.trim() || undefined,
        note: note.trim() || undefined,
      }
      if (editingGift) await patch('wedding', editingGift.id, fields)
      else await db.wedding.add({ ...newEnvelope(me, 'C1_personal', { visibility }), kind: 'wed_gift', ...fields } as never)
    }
    onClose()
  }

  const title =
    kind === 'souvenir'
      ? editingSouvenir ? t('wedding2.fav.editSouvenir') : t('wedding2.fav.addSouvenir')
      : editingGift ? t('wedding2.gift.edit') : t('wedding2.gift.add')

  return (
    <Sheet open={kind !== null} onClose={onClose} title={title}>
      <div className="stack">
        {kind === 'souvenir' && (
          <>
            <Field label={t('wedding2.fName')}>
              {(p) => <input {...p} type="text" value={name} onChange={(e) => setName(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fav.fOrdered')}>
              {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={ordered} onChange={(e) => setOrdered(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fav.fPerGuest')} hint={t('wedding2.fav.fPerGuestHint')}>
              {(p) => <input {...p} type="number" min="1" inputMode="numeric" value={perGuest} onChange={(e) => setPerGuest(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fav.fReceived')} hint={t('common.optional')}>
              {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={received} onChange={(e) => setReceived(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fNote')} hint={t('common.optional')}>
              {(p) => <input {...p} type="text" value={note} onChange={(e) => setNote(e.target.value)} />}
            </Field>
          </>
        )}

        {kind === 'gift' && (
          <>
            <Field label={t('wedding2.gift.fGiver')}>
              {(p) => <input {...p} type="text" value={giver} onChange={(e) => setGiver(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.gift.fAmount')} hint={t('wedding2.gift.fAmountHint')}>
              {(p) => <input {...p} type="number" min="0" inputMode="numeric" value={amount} onChange={(e) => setAmount(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.gift.fItem')} hint={t('wedding2.gift.fItemHint')}>
              {(p) => <input {...p} type="text" value={item} onChange={(e) => setItem(e.target.value)} />}
            </Field>
            <Field label={t('wedding2.fNote')} hint={t('common.optional')}>
              {(p) => <input {...p} type="text" value={note} onChange={(e) => setNote(e.target.value)} />}
            </Field>
            {!editingGift && (
              <Field label={t('common.whoCanSee')} hint={t('wedding2.gift.visHint')}>
                {(p) => (
                  <select {...p} value={visibility} onChange={(e) => setVisibility(e.target.value as Visibility)}>
                    {PARTNER_VISIBILITY_OPTIONS.map((v) => (
                      <option key={v} value={v}>{t(`vis.opt.${v}` as const)}</option>
                    ))}
                  </select>
                )}
              </Field>
            )}
          </>
        )}

        <button className="btn btn--block" onClick={save}>{t('common.save')}</button>
      </div>
    </Sheet>
  )
}
