import { ATTIRE_STATES, type AttireStatus } from './types'

/**
 * Attire-tracking logic (W28).
 *
 * Counts by lifecycle state and a per-person roll-up. No verdict on how anyone
 * looks — `siap` means the outfit is ready to wear, nothing more. Structural in,
 * numbers out.
 */

export interface AttireLike {
  person: string
  status: AttireStatus
}

/** Tally of items across the lifecycle (W28). Absent states read as zero, not missing. */
export function attireProgress(items: readonly AttireLike[]): Record<AttireStatus, number> {
  const out = Object.fromEntries(ATTIRE_STATES.map((s) => [s, 0])) as Record<AttireStatus, number>
  for (const it of items) out[it.status] += 1
  return out
}

export interface PersonAttire {
  person: string
  total: number
  ready: number
}

/**
 * Per-person roll-up (W28): how many of each person's items are `siap`. Sorted by
 * person name so the list is stable, never ranked by who is "more ready".
 */
export function attireByPerson(items: readonly AttireLike[]): PersonAttire[] {
  const map = new Map<string, PersonAttire>()
  for (const it of items) {
    const row = map.get(it.person) ?? { person: it.person, total: 0, ready: 0 }
    row.total += 1
    if (it.status === 'siap') row.ready += 1
    map.set(it.person, row)
  }
  return [...map.values()].sort((a, b) => a.person.localeCompare(b.person))
}
