/**
 * Accommodation reconciliation for out-of-town guests (W31).
 *
 * Beds against heads is exactly the seats-against-heads maths transport already
 * does, so this reuses `transportSummary` rather than re-deriving it. The only
 * thing lodging adds is "how many places do you have" — the app surfaces a bed
 * shortfall, it never books anything.
 *
 * Structural in, numbers and a level key out — no copy, no database.
 */

import { transportSummary, type LegLevel, type TransportLegLike } from './transport'

export type { LegLevel } from './transport'

export interface LodgingPlaceLike extends TransportLegLike {}

export interface PlaceStatus {
  id: string
  capacity: number
  needPax: number
  /** beds − heads. Negative once the place is over-booked. */
  spare: number
  level: LegLevel
}

export interface LodgingSummary {
  places: PlaceStatus[]
  placesCount: number
  totalBeds: number
  totalNeed: number
  /** Heads with no bed across all places. Zero when everyone is covered. */
  shortfall: number
}

/**
 * Per-place and overall bed reconciliation (W31). A place with neither a capacity
 * nor a need reads `unknown`, never as a shortage.
 */
export function lodgingSummary(places: readonly LodgingPlaceLike[]): LodgingSummary {
  const s = transportSummary(places)
  return {
    places: s.legs,
    placesCount: places.length,
    totalBeds: s.totalCapacity,
    totalNeed: s.totalNeed,
    shortfall: s.shortfall,
  }
}
