/**
 * Offline check-in tokens and verification (W19/W20).
 *
 * A guest's QR encodes only `TD1:<guestId>:<checksum>`. There is no server and
 * no signing key: the guest id is an unguessable UUID that already lives in the
 * couple's local roster, so "is this a real invitee?" is answered entirely by a
 * local lookup — the scanner works in airplane mode. The checksum only rejects a
 * mistyped code or a QR from some other app before we bother searching; it is
 * not a security claim, and this module says so rather than pretending to sign.
 *
 * Keys and structural results only — no user-facing copy, no database.
 */

const PREFIX = 'TD1'

/** Small, order-sensitive digit checksum. Not a signature — a typo guard. */
function checksum(id: string): string {
  let h = 7
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) % 10000
  return String(h).padStart(4, '0')
}

/** The string a guest's QR (and the manual fallback) carries. */
export function makeToken(guestId: string): string {
  return `${PREFIX}:${guestId}:${checksum(guestId)}`
}

/** Returns the guest id if the token is well-formed and its checksum holds. */
export function parseToken(raw: string): string | null {
  const parts = raw.trim().split(':')
  if (parts.length !== 3) return null
  const [prefix, id, sum] = parts
  if (prefix !== PREFIX || !id) return null
  return checksum(id) === sum ? id : null
}

export type CheckinStatus = 'bad' | 'unknown' | 'already' | 'ok'

export interface CheckinGuestLike {
  id: string
  checkedInAt?: string
}

export interface CheckinResult<G extends CheckinGuestLike> {
  status: CheckinStatus
  guest?: G
}

/**
 * Resolves a scanned/typed token against the local roster. `bad` = not our
 * format; `unknown` = not on the list; `already` = a prior check-in exists;
 * `ok` = a first-time match. Never blocks a real guest over invitation state —
 * a door scanner confirms identity, it does not re-litigate the invite.
 */
export function verifyCheckin<G extends CheckinGuestLike>(
  raw: string,
  guests: readonly G[],
): CheckinResult<G> {
  const id = parseToken(raw)
  if (!id) return { status: 'bad' }
  const guest = guests.find((g) => g.id === id)
  if (!guest) return { status: 'unknown' }
  if (guest.checkedInAt) return { status: 'already', guest }
  return { status: 'ok', guest }
}

export interface CheckinCounts {
  checkedIn: number
  total: number
}

/** How many of the roster have checked in. Plain counts, never a rate to judge. */
export function checkinCounts(guests: readonly CheckinGuestLike[]): CheckinCounts {
  return {
    checkedIn: guests.filter((g) => g.checkedInAt).length,
    total: guests.length,
  }
}
