/**
 * Document-vault logic (W27).
 *
 * The vault stores that a document exists and where it is — never a scan. This
 * derives expiry status and a small summary. Structural in, keys/numbers out.
 */

export type DocStatus = 'ok' | 'soon' | 'expired' | 'none'

/**
 * Expiry state of one document (W27). `none` when it has no expiry at all —
 * plenty of berkas never expire, and a missing date is not a problem to flag.
 */
export function docStatus(expiresAt: string | undefined, todayMs: number, soonDays = 30): DocStatus {
  if (!expiresAt) return 'none'
  const exp = Date.parse(expiresAt)
  if (Number.isNaN(exp)) return 'none'
  const days = Math.floor((exp - todayMs) / 86_400_000)
  if (days < 0) return 'expired'
  if (days <= soonDays) return 'soon'
  return 'ok'
}

export interface DocLike {
  where?: string
  expiresAt?: string
}

export interface DocVaultSummary {
  total: number
  /** How many have a location recorded — the whole point of the vault. */
  located: number
  expiringSoon: number
  expired: number
}

/** Roll-up over the vault (W27): totals, how many are locatable, what is expiring. */
export function docVaultSummary(docs: readonly DocLike[], todayMs: number, soonDays = 30): DocVaultSummary {
  let located = 0
  let expiringSoon = 0
  let expired = 0
  for (const d of docs) {
    if (d.where && d.where.trim()) located += 1
    const s = docStatus(d.expiresAt, todayMs, soonDays)
    if (s === 'soon') expiringSoon += 1
    else if (s === 'expired') expired += 1
  }
  return { total: docs.length, located, expiringSoon, expired }
}
